INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the impact of patient privacy regulations on health systems management?', 'To reduce focus on patient confidentiality', 'To ensure the protection of patient information and compliance with privacy laws and regulations', 'To limit data security measures', 'To ignore patient consent', 'B', 'Privacy regulations require protecting patient information and complying with data-protection law (Kenya Data Protection Act 2019; NCK Code of Conduct confidentiality). Reducing confidentiality, limiting security or ignoring consent (A, C, D) violate these legal duties.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers improve patient flow within healthcare facilities?', 'By ignoring bottlenecks in care delivery', 'By optimizing processes, scheduling, and resource allocation to streamline patient flow and reduce wait times', 'By increasing patient wait times', 'By limiting staff involvement in patient flow management', 'B', 'Patient flow is improved by optimizing processes, scheduling and resource allocation to reduce wait times, per health-services operations management. Ignoring bottlenecks, increasing wait times or limiting staff involvement (A, C, D) worsen flow.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of telehealth in modern health systems management?', 'To limit access to care', 'To provide remote healthcare services, improve access, and enhance patient convenience', 'To reduce technology use', 'To ignore virtual care options', 'B', 'Telehealth provides remote services, improving access and patient convenience, consistent with Kenya''s Digital Health Act/eHealth strategy. Limiting access, reducing technology or ignoring virtual care (A, C, D) contradict telehealth''s purpose.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers support interdisciplinary collaboration?', 'By limiting team interactions', 'By promoting communication and collaboration among diverse healthcare professionals to improve patient care', 'By reducing team meetings', 'By ignoring the benefits of diverse perspectives', 'B', 'Interdisciplinary collaboration is supported by promoting communication among diverse professionals to improve patient care, per WHO interprofessional practice framework. Limiting interactions, reducing meetings or ignoring diverse perspectives (A, C, D) undermine teamwork.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the role of patient satisfaction surveys in health systems management?', 'To limit feedback collection', 'To gather patient feedback on their care experience and identify areas for improvement', 'To ignore patient opinions', 'To reduce focus on service quality', 'B', 'Patient satisfaction surveys gather feedback on the care experience to identify areas for improvement, a core continuous-quality-improvement tool in HSM. Limiting feedback, ignoring opinions or reducing quality focus (A, C, D) defeat the survey''s purpose.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('How can health systems managers address the challenges of chronic disease management?', 'By ignoring chronic conditions', 'By implementing comprehensive care plans, patient education, and regular monitoring to manage chronic diseases effectively', 'By reducing support for chronic disease programs', 'By limiting patient engagement in care management', 'B', 'Chronic disease is managed through comprehensive care plans, patient education and regular monitoring, per Kenya NCD management guidelines and WHO chronic-care model. Ignoring conditions, cutting programs or limiting engagement (A, C, D) worsen outcomes.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Qualities of good entrepreneurs include;', 'Conformists, risk takers, critical thinkers', 'Critical thinkers, tolerant, conformists', 'Conformists, tolerant, risk takers', 'Critical thinkers, risk takers, tolerant', 'D', 'Per entrepreneurship principles in the NCK health-systems-management syllabus, good entrepreneurs are critical/creative thinkers, risk takers and tolerant of ambiguity and failure; they are innovators, NOT conformists. Only option D excludes ''conformists'' and lists the three genuine traits, so options A, B and C are wrong for including conformism.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is an advantage of Functional Nursing care modality?', 'There is specialization', 'It can be monotonous hence boredom', 'Client may become impersonal', 'There is little avenue for development', 'A', 'Per nursing management texts (Marquis & Huston), in the functional/task-oriented care modality each nurse performs specific assigned tasks, giving specialization and efficiency, which is its chief advantage. Monotony/boredom (B), impersonal/fragmented care (C) and little avenue for professional development (D) are recognised DISADVANTAGES, so only A is an advantage.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is a type of nursing audit:', 'Performance appraisal', 'Job analysis', 'Job description', 'Operational audit', 'D', 'Per nursing quality-assurance texts, nursing audits are classified as structure, process and outcome audits and by scope include operational (concurrent/process) audits, so operational audit (D) is a type of nursing audit. Performance appraisal, job analysis and job description (A, B, C) are human-resource functions, not audits.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Factors to remember while purchasing commodities include the following _____________?', 'Quantity & payment discounts', 'Locality of the supplier', 'Gender of supplier', 'Primary contract', 'A', 'Per procurement/supplies-management principles in the NCK health-systems syllabus, factors to consider when purchasing include quantity and payment (cash/trade) discounts, quality, price and supplier reliability. Gender of the supplier (C) is irrelevant/discriminatory, and mere locality (B) or an unexplained ''primary contract'' (D) are not core purchasing criteria, so A is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following describes inventory control.', 'It is the full range of activities related to purchasing goods, services and works', 'It is the process required to supply equipment , material , service and other resources needed to carry out a project', 'It is concerned with planning, organizing and controlling the flow of materials from their initial purchase through internal operations to the service point through distribution.', 'It means stocking adequate number and kind of stores, so that the materials are available whenever required and wherever required.', 'D', 'Per health-systems/supplies management texts, inventory control means keeping adequate numbers and kinds of stock so materials are available whenever and wherever required, avoiding both stock-outs and overstocking (option D). Option A defines procurement, B defines project supply/logistics, and C defines materials management, so D best defines inventory control.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the correct sequence of the procurement process?', 'Planning, Documentation, Product evaluation, Awarded and Administration, Inspection and Delivery', 'Planning, Awarded and Administration, Documentation, Product evaluation, Inspection and Delivery', 'Planning, Documentation, Awarded and Administration, Inspection and Delivery, Product evaluation', 'Planning, Documentation, Product evaluation, Awarded and , Inspection and Delivery, Administration', 'A', 'Per public procurement practice (PPAD-based) in the NCK syllabus, the logical sequence is planning, documentation (tender documents), product/bid evaluation, award and contract administration, then inspection and delivery/acceptance. Only option A places evaluation before award and delivery last; B, C and D disorder award, evaluation or delivery.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Tactical plans in an organisation', 'Focus on single daily action', 'Are concerned on how to implement operational plans', 'Are of intermediate time frame', 'Are mainly developed from the major organisation goals', 'C', 'Per nursing management/planning theory (Marquis & Huston), tactical plans are of intermediate time frame, prepared by middle management to translate strategic plans into departmental action. Plans developed directly from major organisational goals are strategic (D) and single daily actions are operational (A), so C describes tactical plans.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Feedback to subordinate from nurse managers;', 'Should be given in private always', 'Should be done daily', 'Should be both objective and subjective', 'Should have negative comments last.', 'C', 'Per nursing supervision/feedback principles (Marquis & Huston), effective feedback is balanced, using both objective (measurable) and subjective information, and is timely and constructive. It need not always be given in private (A), daily (B) or always end with negatives (D), so C is the best-supported statement.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following theorist emphasised on the use of rules, regulations and policies to govern employees.', 'Frederic Taylor', 'Max Weber', 'Henri Fayol', 'Douglas McGregor', 'B', 'Max Weber''s bureaucratic theory of management emphasises rules, regulations, hierarchy and impersonal policies to govern employees (Marquis & Huston, Leadership Roles and Management Functions in Nursing). Taylor (A) is scientific management, Fayol (C) administrative principles, and McGregor (D) Theory X/Y, so B is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Principles of customer care that you can utilize include;', 'Understanding what you do, ensuring you are compensated for what you do', 'Finishing your tasks, being happy with your job', 'Understanding your customer needs, Ensuring division of labour', 'Being hospitable, proper time management', 'D', 'Per health-service customer-care/quality guidelines used in Kenyan facilities, customer-care principles centre on serving clients courteously and efficiently; being hospitable and practising good time management (D) are genuine customer-care behaviours. The distractors emphasise self-interest (compensation, own happiness) or internal operations (division of labour) rather than client focus.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ascribed status includes being;', 'A politician', 'An eldery', 'A businessman', 'A nurse', 'B', 'Per behavioural science/sociology texts used in Kenyan nursing training, ascribed status is assigned at birth or acquired involuntarily (e.g. age/being elderly, sex, race), so ''an elderly'' (B) is ascribed. Politician, businessman and nurse (A, C, D) are achieved statuses earned through effort, so B is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are elements of an advocacy objective', 'Policy actor, the advocates, timeline', 'Policy action, the advocates, budget', 'Policy actor, policy action, timeline', 'Resources, advocacy issue, networks', 'C', 'Per the SMART advocacy-objective framework (community health/advocacy guidelines), an advocacy objective specifies WHO must act (policy actor), WHAT change is sought (policy action) and BY WHEN (timeline), which is option C. ''Advocates'', ''budget'' and ''resources'' in the other options are strategy inputs, not elements of the objective itself.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Positive non verbal communication includes the following__________?', 'Personal appearance', 'Dancing', 'Laughing', 'Frowning', 'A', 'Per Kozier & Erb''s Fundamentals of Nursing (communication), positive non-verbal communication includes a neat personal appearance/grooming, which conveys professionalism and respect. Frowning (D) is negative, and dancing (B) and laughing (C) are not standard positive professional non-verbal cues in a therapeutic context, so A is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Issues for consideration for advocacy include ____________?', 'Gender based violence', 'Community diagnosis', 'Adult education', 'Political seats', 'A', 'Per Kenya community-health nursing/advocacy guidelines, advocacy addresses social/health injustices needing policy or societal change, and gender-based violence (A) is a classic advocacy issue. Community diagnosis and adult education (B, C) are programme activities, and political seats (D) are not a health-advocacy issue, so A is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is an example of an activity involved in monitoring and evaluation.', 'Registers', 'Outreach', 'Blood Pressure machine', 'Meeting venue', 'A', 'Per Kenya HMIS/community M&E guidelines, monitoring and evaluation is a data/information function, and keeping and reviewing registers (A) is a core M&E activity for tracking indicators. A BP machine (C) and meeting venue (D) are physical resources and outreach (B) is a service-delivery activity, so A is the M&E activity.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is a purpose of monitoring and evaluation?', 'Management', 'Orientation', 'Deployment', 'Employment', 'A', 'Per Kenya health-management/M&E guidelines, the purpose of monitoring and evaluation is to inform management decision-making by tracking progress, ensuring accountability and guiding corrective action (A). Orientation, deployment and employment (B, C, D) are human-resource functions, not the purpose of M&E, so A is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Categories of local resources include _______________?', 'Human Resources, Organizational Resources, Infrastructural Resources, Geographical Resources', 'Human Resources, Organizational Resources, Biological Resources, Infrastructural Resources,', 'Human Resources, Organizational Resources, Biological Resources, Financial Resources', 'Human Resources, Organizational Resources, Infrastructural Resources, Financial Resources', 'D', 'Per community-health resource-mobilisation guidelines, local resources are categorised as human, organizational, infrastructural (material) and financial resources (option D). ''Geographical'' (A) and ''biological'' (B, C) are not standard resource-mobilisation categories, so D lists the correct four categories.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Importance of resource mobilization is to _________________________?', 'Diversify and expand resources', 'Compromise financial sustainability', 'Promote dependency', 'Increase competition', 'A', 'Per community-health resource-mobilisation principles, the importance of resource mobilisation is to diversify and expand the resource base, strengthening sustainability and reducing dependency (A). Compromising sustainability (B), promoting dependency (C) and increasing competition (D) are undesirable outcomes, so A is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Strategies of time management include:', 'Goal setting, Time analysis, prolonged meetings, Delegation, Controlling of interruptions', 'Goal setting, Time analysis, Priority setting, Delegation, Controlling of interruptions', 'Goal setting, prolonged meetings, Priority setting, Delegation, Controlling of interruptions', 'Goal setting, Time analysis, Priority setting, prolonged meetings, Controlling of interruptions', 'B', 'Per nursing management texts (Marquis & Huston), effective time-management strategies are goal setting, time analysis, priority setting, delegation and controlling interruptions (option B). ''Prolonged meetings'' is a recognised time-waster, so every option containing it (A, C, D) is wrong, leaving B.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following categories of patients are automatically exempted:', 'Prisoners, National Youth Service personnel, street children and children above five years of age.', 'Prisoners, National Youth Service personnel, foreigners and children under five years of age', 'Prisoners, National Youth Service personnel, street children and children under five years of age', 'Prisoners, National Youth Service personnel, street children and foreigners', 'C', 'Per Kenya MOH cost-sharing/user-fee exemption policy, automatically exempted groups include prisoners, National Youth Service personnel, street children and children under five years (option C). Children ''above five'' (A) and ''foreigners'' (B, D) are not automatic exemptions, so C is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In advocacy, a constituency refers to;', 'The people in positions of authority', 'The champions who lead the advocacy process', 'The persons affected by the advocacy issue', 'The networks formed to advocate for change', 'C', 'Per community-health advocacy guidelines, a constituency is the people affected by the advocacy issue, on whose behalf advocacy is done (option C). Those in authority (A) are the targets/decision-makers, the champions (B) are the advocates, and networks (D) are advocacy structures, so C is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A manager who is involved in the process of grouping the necessary responsibilities and activities into workable units engages in a role of:', 'Job designing', 'Staffing', 'Scheduling', 'Organizing', 'D', 'Per nursing management texts (Marquis & Huston), grouping necessary responsibilities and activities into workable units is the management function of organizing (structuring work and resources). Job designing (A) shapes individual jobs, staffing (B) fills posts, and scheduling (C) allocates duty times, so D is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The skills of an effective manager are;', 'Conceptual, human, technical', 'Human, communication, technical', 'Technical, political, social', 'Conceptual, social, communication', 'A', 'Per Katz''s classic managerial-skills model (Marquis & Huston), an effective manager needs conceptual, human (interpersonal) and technical skills (option A). The other options substitute non-Katz terms such as communication, political or social skills, so A is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Positive nonverbal communication includes the following__________?', 'Personal appearance', 'Dancing', 'Laughing', 'Frowning', 'A', 'Per Kozier & Erb''s Fundamentals of Nursing, positive non-verbal communication includes appropriate personal appearance/grooming, which signals professionalism and respect (A). Frowning (D) is negative, and dancing (B) and laughing (C) are not standard positive professional non-verbal cues, so A is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the correct sequence of the steps involved in employee disciplinary procedure?', 'Verbal warning, warning letter, termination, suspension', 'Warning letter, verbal warning, suspension, termination', 'Verbal warning, warning letter, suspension, termination', 'Warning letter, suspension, verbal warning, termination', 'C', 'Per progressive discipline (Marquis & Huston; Kenya HR/labour practice), the sequence is verbal (oral) warning, written warning letter, suspension, then termination as a last resort (option C). Options A, B and D disorder these steps (e.g. placing termination before suspension or the warning letter first), so C is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The assumption in theory X of Douglas McGregor’s is _____________', 'An average human being who has an inherent dislike for work and will avoid it if possible.', 'Employees are seen, as liking work naturally', 'Human beings do not have to be controlled or coerced as long as commitment to the organization is present.', 'Under proper conditions, people will not only accept but also seek responsibility', 'A', 'Per McGregor''s management theory (Marquis & Huston), Theory X assumes the average human inherently dislikes work and will avoid it if possible, requiring control and coercion (option A). Options B, C and D describe Theory Y assumptions (people naturally like work, are self-directed and seek responsibility), so A is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Henry Fayol:', 'Introduced innovations in how jobs were designed and how workers were trained to perform.', 'Identified specific functions of a manger', 'Developed the bureaucratic model', 'Examined motivation from the perspective of why people choose to follow a particular course of action.', 'B', 'Henri Fayol, the father of administrative management, identified the specific functions of a manager (planning, organizing, commanding, coordinating, controlling) and 14 principles (option B). Job design/worker training (A) is Taylor''s scientific management, the bureaucratic model (C) is Weber, and expectancy motivation (D) is others, so B is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Espirit de corps is a principle of management that:', 'Ensures a just working environment for employees', 'Encourages harmony and general good feelings among employees', 'Encourages worker initiative', 'Ensures retention of productive employees', 'B', 'Per Fayol''s 14 principles of management (Marquis & Huston), esprit de corps promotes team spirit, harmony and general good feelings/unity among employees (option B). A just working environment (equity), worker initiative and staff retention are separate principles/concerns, so B is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A capital budget:', 'It is prepared by Nursing ward in charges in consultation with staff', 'Usually coincides with the calendar year', 'Includes the accumulated estimates of operating revenues and expenses', 'Outlines the need for major equipment requiring large sums of money.', 'D', 'Per nursing financial management (Marquis & Huston), a capital budget outlines the need for major equipment, buildings and other long-term assets requiring large sums of money, usually with a multi-year life (option D). Accumulated operating revenues/expenses (C) and calendar-year alignment (B) describe an operating budget, so D is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Managerial functions include;', 'Planning, controlling and staffing', 'Planning, negotiating and liaising', 'Organizing, planning, monitoring', 'Resource allocation, negotiating, monitoring', 'A', 'Per nursing management texts (Marquis & Huston), the core managerial functions are planning, organizing, staffing, directing/leading and controlling; option A (planning, controlling, staffing) lists three genuine functions. Options B, C and D mix in non-core roles such as negotiating, liaising and resource allocation, so A is correct.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following leadership theory states that leaders are born and not made?', 'Trait', 'Charismatic', 'Great man', 'Situational', 'C', 'Per leadership theory (Marquis & Huston), the Great Man theory holds that leaders are born, not made, possessing innate qualities (option C). Trait theory (A) identifies leader characteristics but does not strictly claim they are inborn, charismatic (B) focuses on personal charisma, and situational (D) on context, so C best fits ''born not made''.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Recruitment involves ___________?', 'Advertising a vacancy, short-listing, controlling , induction', 'Advertising a vacancy, short-listing, interviewing, induction.', 'Advertising a vacancy, short-listing, interviewing, controlling', 'Advertising a vacancy, controlling , interviewing, induction', 'B', 'Recruitment and selection is the process of advertising a vacancy, short-listing applicants, interviewing candidates and inducting the successful hire. Option B lists exactly these authentic steps. Options A, C and D each substitute ''controlling'' — a distinct management (monitoring) function, not a recruitment activity. Per Marquis & Huston nursing management and standard HR practice.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Evaluation errors in performance appraisal include _____________________?', 'Formal effect', 'Informal effect', 'Halo effect', 'Double effect', 'C', 'The halo effect is a recognised performance-appraisal rating error in which one strong (favourable) trait causes the rater to score the employee highly across all dimensions. ''Formal effect'', ''informal effect'' and ''double effect'' are not appraisal errors and are distractors. Per Marquis & Huston performance appraisal.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is a stakeholder in occupational health?', 'Refugees', 'Members of the health team', 'Long distance drivers', 'Travellers', 'B', 'In occupational health, the members of the health team are workers exposed to occupational hazards (needlestick, infection, back injury) and are therefore direct stakeholders in an occupational-health programme. Refugees, long-distance drivers and travellers are general/mobile populations, not the defined occupational cohort of the facility. Per Kenya OSH / occupational health guidelines.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Theory Y in management emphasizes on:', 'The organizational goals', 'Motivation', 'Self esteem', 'The goals of an individual.', 'B', 'McGregor''s Theory Y takes an optimistic view of workers as self-directed, responsibility-seeking and internally driven, so management emphasises motivation and empowerment rather than control. Theory X (not Y) focuses on close control toward organisational goals; self-esteem and individual goals are not the defining emphasis. Per Marquis & Huston management theory.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Barriers to effective delegation include all the following EXCEPT?', 'Reluctance to delegate', 'Lack of confidence in subordinates', 'Inability to plan', 'Employees values and interests', 'D', 'Recognised barriers to effective delegation are the manager''s reluctance to delegate, lack of confidence/trust in subordinates and inability to plan or organise work. Employees'' values and interests are a factor used to match tasks to the right staff, not a barrier — hence the EXCEPT answer. Per Marquis & Huston nursing management.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The manager stresses the need for employees to follow orders and instructions and not from anyone else. which of the following principles does he refer to?', 'Scalar chain', 'Discipline', 'Unity of command', 'Order', 'C', 'Fayol''s principle of unity of command holds that each employee should receive orders and be accountable to only one superior, exactly as the manager describes. Scalar chain is the vertical line of authority, discipline concerns obedience/agreements, and order concerns arrangement of people/resources. Per Fayol''s 14 principles (Marquis & Huston).', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The statement “The Holy spirit Medical center aims to provide patient centred care in a total healing environment” refers to which of the following', 'Vision', 'Goal', 'Philosophy', 'Mission', 'D', 'A mission statement declares the organisation''s present core purpose and what it aims to do now (''aims to provide patient-centred care in a total healing environment''). A vision describes the desired future state, a goal is a measurable target, and a philosophy states underlying values/beliefs. Per Marquis & Huston strategic planning.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is NOT an advantage of Functional nursing model', 'It is economical', 'It is time saving', 'Easy to organize', 'Cultivates team spirit', 'D', 'Functional (task-oriented) nursing is economical, time-saving and easy to organise, but because staff perform isolated tasks it fragments care and does NOT cultivate team spirit — that benefit belongs to team/modular nursing. Hence D is the correct EXCEPT answer. Per Marquis & Huston care delivery models.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The leadership theory states that leaders are born and not made is___________?', 'Trait', 'Charismatic', 'Great man', 'Situational', 'C', 'The Great Man theory asserts that leaders are born, not made, possessing innate leadership qualities from birth. Trait theory catalogues characteristics of effective leaders but does not insist they are inborn, charismatic theory centres on personal magnetism, and situational theory ties leadership to context. Per Marquis & Huston leadership theory.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The function of a manager that ensures effective and appropriate use of resources is:', 'Organizing', 'Planning', 'Controlling', 'Implementation', 'C', 'Controlling is the management function that measures performance against standards and ensures resources are used effectively and appropriately through monitoring and corrective action. Planning sets objectives, organising arranges resources, and implementation executes plans. Per Marquis & Huston nursing management.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Some principles of management include:', 'Priority setting, Evaluating progress, minimal breaks', 'Time analysis, goal setting, delegation', 'Avoiding delegation, time analysis, controlling interruptions', 'Time analysis, goal setting, minimal breaks', 'B', 'Sound time/management principles include time analysis, goal setting and delegation, all of which appear together in option B. The other options contain poor practices such as ''minimal breaks'' and ''avoiding delegation'', which impair rather than improve managerial effectiveness. Per Marquis & Huston nursing management.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The advantages of decentralization in management include:', 'Increased level of decision making and flexibility', 'Quick and better decision making', 'Flexibility of staff and decreased bureaucracy', 'Reduced cost and avoids duplication of efforts', 'B', 'Decentralisation pushes decision-making authority downward, so decisions are made quicker and better by those closest to the situation. Option B captures this primary advantage most precisely; the other options blend it with less accurate or overstated claims. Per Marquis & Huston nursing management.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following statement is true regarding evaluator’s rating errors', 'Halo Effect- The ratter only recalls or uses recent data', 'Recency Effect- The ratter assumes that if the person does well in several known areas, he or she will do well in all areas', 'Sunflower effect-Ratter scores all the employees high because they are a great team', 'Central tendency effect- Different ratters tend to score leniently or strictly.', 'C', 'Only option C correctly pairs error and definition: the sunflower effect is rating all group members high because they are perceived as a great team. A, B and D mislabel the definitions (recency = using only recent data; halo = one good area assumed across all; central tendency = clustering scores at the middle). Per Marquis & Huston performance appraisal.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When preparing staff schedules, the nurse manager should:', 'Determine hours of minimum and maximum workload before preparing the schedule', 'Avoid displaying the schedule early to minimize complaints from the staff', 'Avoid reviewing the schedule as the week progresses', 'Never consider the patient care needs', 'A', 'Effective staff scheduling begins by determining the minimum and maximum workload/staffing requirements dictated by patient care needs before drafting the roster. The other options — concealing the schedule, not reviewing it, and ignoring patient needs — are all poor scheduling practices. Per Marquis & Huston staffing/scheduling.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Disasters of geographical origin includes;', 'Tsunamis, hurricanes, volcanic eruptions', 'Fire, earthquakes, acid rain', 'Cyclones, floods, desertification', 'Volcanic eruptions, explosions, fire', 'A', 'Disasters of geophysical/geographical origin are natural earth- and weather-driven events such as tsunamis, hurricanes and volcanic eruptions, grouped in option A. The other options mix in man-made/technological hazards (fire, explosions) and environmental degradation (acid rain, desertification), which are not classified as geographical disasters. Per WHO / Kenya disaster management classification.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Principles of time management include:', 'Goal setting, priority setting, controlling interruptions', 'Goal setting, setting priorities, organization.', 'Organization, time analysis, goal setting', 'Setting priorities, organization, controlling interruptions', 'A', 'Core time-management principles are goal setting, priority setting and controlling interruptions, all present in option A. While other options list some valid elements, A best combines three recognised principles without redundancy for the stem. Per Marquis & Huston nursing management.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Main managerial functions include;', 'Planning, controlling, organizing and staffing', 'Planning, liaising organizing and staffing', 'Organizing, planning, monitoring, staffing', 'Planning, controlling, negotiating, monitoring', 'A', 'The main managerial functions are planning, organising, staffing, directing/leading and controlling; option A lists four authentic ones (planning, controlling, organising, staffing). The other options insert non-core activities such as liaising, negotiating and monitoring. Per Marquis & Huston nursing management.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main difference between a manager and a leader is that, a leader____;', 'Works with and through people to achieve organizational goals.', 'Works effectively and efficiently', 'Has formal authority and responsibility', 'Is able to influence people.', 'D', 'Leadership is fundamentally the ability to influence people toward achieving goals, and this influence — not formal authority — distinguishes a leader from a manager. Working through people and being efficient can describe both roles, while formal authority/responsibility specifically characterises the manager. Per Marquis & Huston leadership theory.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following principle of management explains systematic retention of power at higher levels of an organisation', 'Decentralisation', 'Centralisation', 'Coercive authority', 'Unity of command', 'B', 'Centralisation is the systematic retention/concentration of decision-making authority at the higher (top) levels of an organisation. Decentralisation is its opposite (dispersal of authority downward), coercive authority is power through threat, and unity of command concerns reporting to one superior. Per Fayol''s principles (Marquis & Huston).', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lose-lose strategy of conflict management;', 'Leads to a greater conflict', 'The conflicting parties come up with something neutral', 'One party achieves its desire at the expense of the other', 'The reason for conflict is addressed', 'A', 'In a lose-lose conflict strategy neither party meets its needs, leaving both dissatisfied so the underlying conflict typically persists or escalates. Win-lose is where one party gains at the other''s expense, compromise reaches something neutral, and win-win/collaboration addresses the root cause. Per Marquis & Huston conflict management.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is true about the development of the male gonads:', 'Requires 36°C temperature', 'Testosterone production causes maturation of the wolffian ducts', 'Descends into the scrotum during the eighth infancy week', 'Testicular production of mullerian inhibits sabstances (MIS) Causes degeneration of the wolffian duct', 'B', 'Per embryology (Langman/Myles), fetal Leydig-cell testosterone drives maturation of the wolffian (mesonephric) ducts into male internal genitalia. Mullerian Inhibiting Substance (MIS/AMH) causes regression of the Mullerian ducts, not the wolffian, so D is wrong; spermatogenesis (not development) needs ~34C, and testicular descent is late fetal (7th-8th month), not the eighth week.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Maximum normal time for second stage off labour in primigravida without anaesthesia is:', '20 minutes', '60 minutes', '120 minutes', '240 minutes', 'C', 'Per Myles Textbook for Midwives, the maximum normal duration of the second stage in a primigravida without regional anaesthesia is about 2 hours (120 minutes); prolongation beyond this warrants review. 60 minutes is a typical average, not the maximum, and 240 minutes is well beyond safe limits.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In graffian follicle the inner most cells of the corona that are very clear are referred to as:', 'Perivitelline space', 'Corona radiate', 'Zona pellucinda', 'External limiting membrane', 'C', 'Per reproductive anatomy (Myles), the innermost clear layer immediately surrounding the oocyte, inside the corona radiata, is the zona pellucida, a translucent glycoprotein membrane. The corona radiata is the outer follicular cell layer; perivitelline space and external limiting membrane are not the clear zone described.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The area enclosed by labia minora is called.', 'Fourchette', 'Vestibular', 'Perineum', 'Vaginal os', 'B', 'Per anatomy of the external female genitalia (Myles), the area enclosed by the labia minora is the vestibule, into which the urethral and vaginal openings and Bartholin ducts open. The fourchette is the posterior junction of the labia minora, and the perineum is the tissue between vagina and anus.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Crowning is best defined as:', 'When the greatest diameter of the fetal head comes through vulva', 'When presenting part reaches the pelvis floor', 'When the perineum bulges in front of fetal head', 'When the head is visible at vulva', 'A', 'Per Myles Textbook for Midwives, crowning is when the widest transverse (biparietal) diameter of the fetal head distends the vulva and no longer recedes between contractions. Option D (head merely visible) is ''head on view'', and B/C describe earlier events (descent to pelvic floor and perineal bulging).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In an erect fetal head (not flexed) the presenting diameter are:', 'Occipito-frontal and biparietal', 'Sub occipito-bregmatic and biparietal', 'Submento-bregmatic and bi temperol', 'Mento-vertical and bi-temperol', 'A', 'Per Myles, a deflexed (erect/military) vertex presents the occipito-frontal diameter (11.5 cm) antero-posteriorly with the biparietal diameter (9.5 cm) transversely. Sub-occipito-bregmatic goes with a well-flexed head, and mento-vertical/submento-bregmatic belong to brow and face presentations.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Duration of latent phase in a multigravida is', '1-2 hours', '2-4 hours', '4-6 hours', '6-8 hours', 'B', 'Per Myles and standard obstetric teaching, the latent phase of the first stage is shorter in the multigravida, typically about 2-4 hours, compared with up to ~6-8 hours in a primigravida. The longer ranges (4-6, 6-8 hours) reflect primigravid rather than multigravid patterns.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Progress of labour is determined by which of the following.', 'Dilatation and intensity of contractions', 'Dilatation and effacement', 'Dilatation and descent', 'Frequency of the contractions and descent', 'C', 'Per Myles and the WHO/Kenya partograph, progress of labour is monitored primarily by cervical dilatation and descent of the presenting part. Descent is the key marker especially in the second stage, making dilatation and descent the best pairing; effacement and contraction frequency are supportive but not the core progress measures.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The three components of the cervical exam are:', 'Dilatation, presentation and effacement', 'Dilatation, effacement and station', 'Station, dilatation and effacement', 'Effacement, dilatation and station.', 'B', 'Per Myles, cervical assessment on vaginal examination comprises dilatation, effacement and station of the presenting part. Presentation is determined by abdominal palpation, not as a component of the cervical exam, so A is wrong; B, C and D list the same three components, with B being the conventional ordering.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The plug of mucus that block the cervical canal during pregnancy is known as:', 'Speculum', 'Operculum', 'Show', 'Leucorrhoea', 'B', 'Per Myles, the operculum is the plug of thick cervical mucus that seals the cervical canal during pregnancy; its release forms the ''show''. A speculum is an instrument and leucorrhoea is normal vaginal discharge, so neither names the mucus plug.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Presentation is the part of the fetus that is:', 'Relates to right or left side of the maternal pelvis', 'Presenting or is the closest in the proximity to the birth canal', 'Relates to the long axis of the mother', 'First enters the pelvic cavity', 'B', 'Per Myles, presentation is the part of the fetus that lies at the pelvic brim / is closest to the birth canal (e.g. cephalic, breech). Relation to the maternal long axis defines lie, side of pelvis relates to position, and first entering the pelvis describes engagement.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Before a vaginal examination is done the midwife must:', 'Obtain a verbal consent, ensure privacy, and provide for emotional comfort to the women.', 'Empty the urinary bladder, consider the dignity of the woman, and ensure privacy', 'Take history, consider the dignity of the woman, and ensure privacy', 'Obtain a written consent, perform abdominal examination and confirm presentation', 'A', 'Per Myles and Kenya MOH standards, before a vaginal examination the midwife obtains informed (verbal) consent, ensures privacy and provides emotional support/comfort. A written consent is not required for a routine VE (option D), and emptying the bladder or taking history alone omit consent, the essential prerequisite.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are some of the hormone responsible for causing muscles contraction', 'Progesterone, Relaxin', 'Prolactin, Oxytocin', 'Prostaglandins, Progesterone', 'Prostaglandins, Oxytocin', 'D', 'Per Myles, the hormones that stimulate myometrial contraction are prostaglandins and oxytocin. Progesterone and relaxin promote uterine quiescence/relaxation, and prolactin governs lactation, so options containing them are incorrect.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Capacitation of the sperm:', 'Is caused by the zona pellucida', 'Is essential for fertilization', 'Prevents polyspermy', 'Occurs in the male', 'B', 'Per reproductive physiology (Myles), capacitation is the final maturation of sperm within the female genital tract that is essential for fertilization, enabling the acrosome reaction. It occurs in the female (not male) tract, is not caused by the zona pellucida, and the block to polyspermy is the cortical/zona reaction, not capacitation.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The seven day blastocyst', 'Has a single layer of the trophoblast at the embryonic pole', 'Has an amniotic cavity', 'Is attached to the endometrial epithelium', 'Is surrounded by degenerative zona pellucida', 'C', 'Per embryology (Langman/Myles), by about day 6-7 the blastocyst begins to attach and implant onto the endometrial epithelium. The amniotic cavity and bilaminar disc appear later (around days 8-12), the zona pellucida is shed before implantation, and the trophoblast is thickest (not single-layered) at the embryonic pole, so C best fits.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physiologic event that takes place during peurperium include:', 'Contraction and retraction of the uterus muscles', 'Establishment and maintainance of lactation', 'Displacement of bladder and perineal body', 'Motivation of the mother to gain confidence and play mother role within her family and culture.', 'A', 'Per Myles, the key physiological event of the puerperium is involution of the uterus through contraction and retraction of the myometrium. Establishment of lactation also occurs but uterine involution is the defining physiological process; psychosocial adjustment (option D) is a psychological, not physiological, event.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term given to a vaginal discharge from uterus during puerperium is:', 'Lochia loss', 'Lochia serosa', 'Lochia alba', 'Lochia Rubra', 'D', 'Per Myles, lochia rubra is the red vaginal discharge from the uterus in the first few days of the puerperium (days 1-3/4), followed by lochia serosa then lochia alba. As the earliest and defining postnatal discharge it best answers the term; ''lochia loss'' (A) is not a recognised type.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The part of the sperm containing proteolytic enzyme to digest the zona pellucida is:', 'Capacitor', 'Head crosome', 'Corona', 'Acrosome', 'D', 'Per reproductive physiology (Myles), the acrosome is the cap over the sperm head containing proteolytic enzymes such as hyaluronidase and acrosin that digest the zona pellucida during fertilization. ''Head crosome'' and corona are distractors; capacitation is a process, not a sperm part.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The obstetrical outlet of the pelvic is:', 'Of greater practical significance because it includes the narrow pelvic straight through which foetus must pass', 'The space between the narrow pelvic straight and an anatomical outlet.', 'Formed by the lower border of each of the bones together with the sacratuberous ligaments', 'Said to be between the obturator foramen and sacro-spinous ligaments.', 'A', 'Per Myles pelvic anatomy, the obstetrical outlet is of greater practical significance than the anatomical outlet because it includes the narrow plane of least dimensions (mid-pelvis) through which the fetus must pass. The other options misdescribe the anatomical outlet and its ligamentous boundaries.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('On the examination of the placenta, absence of one umbilical artery is an indication of:', 'Placenta insufficiency', 'Atresias', 'Heart disease', 'Renal anomalies', 'D', 'Per Myles/neonatal teaching, a single umbilical artery on placental/cord examination is associated with congenital anomalies, most notably renal (urinary tract) anomalies, warranting neonatal assessment. It is not a specific marker of placental insufficiency, atresias or heart disease.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('On approximately the sixth day postpartum, the uterine fundus is:', '5 cm below the umbilicus', 'Slightly below the umbilicus and should be in state of contraction feeling firm', 'Midway between the symphysis pubis and the umbilicus', 'At the level of the umbilicus', 'C', 'Per Myles Textbook for Midwives, uterine involution is progressive after delivery. By approximately day 6–7 postpartum, the fundus lies midway between the symphysis pubis and the umbilicus, reducing by about 1 cm per day from its post-delivery position at or just below the umbilicus. It becomes non-palpable abdominally by around day 10–14. Option C (midway between symphysis pubis and umbilicus) best describes this expected involution on approximately the sixth postnatal day. Options A, B, and D either overstate or understate the expected fundal height at this time.', 'KRCHN', 'Paper I', 'Midwifery', 'Postnatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The presumptive signs of the second stage of labor include:', 'Uterine action, soft tissue displacement', 'Rupture of the forewaters, expulsive uterine contraction', 'Backache, progressive cervical dilatation', 'Show, erratic uterine contraction', 'B', 'Per Myles, presumptive (indicative) signs of the second stage include expulsive (bearing-down) uterine contractions and rupture of the forewaters. Progressive cervical dilatation (option C) is a confirmatory, not presumptive, sign, and show with erratic contractions typifies the latent first stage.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Presence of a hole in the membranes on examination of the placenta is indicative of:', 'Velamentous insertion', 'Tripartite placenta', 'Succenturiate placenta', 'Bipartite', 'C', 'Per Myles, a hole in the membranes with torn vessels running to it indicates a succenturiate (accessory) lobe that may have been retained; this warrants uterine exploration to prevent PPH and infection. Velamentous insertion, bipartite and tripartite placentae are described by different placental appearances.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Most pregnant women experience morning sickness between which weeks of gestation?', '4th – 14th', '8th – 10th', '1st – 5th', '20th – 30th', 'A', 'Per Myles Textbook for Midwives, morning sickness (nausea and vomiting of pregnancy) is a first-trimester symptom that typically begins around the 4th week of gestation, as rising human chorionic gonadotrophin (hCG) levels stimulate the nausea centres. It largely resolves by approximately the 14th week in most women as hCG levels plateau and decline. Option A (4th–14th weeks) best represents this window. Option B (8th–10th weeks) is too narrow and only captures the peak, not the full duration. Option C (1st–5th weeks) is too early — symptoms rarely begin before week 4. Option D (20th–30th weeks) is the second trimester, well beyond when morning sickness typically resolves.', 'KRCHN', 'Paper I', 'Midwifery', 'Antenatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The shortest diameter of the female pelvis is:', 'Anatomical conjugate', 'Interspinous (Bispinous)', 'Sacro-cotyloid dimension', 'Obstetric conjugate', 'C', 'Per Myles pelvic anatomy, among the listed measurements the sacro-cotyloid dimension (~9-9.5 cm) is the shortest; the obstetrical conjugate is ~11 cm and the anatomical conjugate ~11-12 cm. The sacro-cotyloid is clinically important in an oblique/asynclitic pelvis.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('From 28 – 32 weeks of gestation the developmental changes that occurs to the fetus include:', 'Testes descends into scrotum, ear cartilage becomes firm, stores fats and iron.', 'Vernix caseosa disappears, kidney begins to function and the fetus passes urine, lanugo disappear from the base.', 'Testes descends into the scrotum, lanugo disappear from the face stores fat and iron.', 'Planter creases become visible, skull is firm and skin becomes pale and less wrinkled', 'A', 'Per Myles fetal development, from about 28-32 weeks the fetus lays down subcutaneous fat and iron stores, ear cartilage firms and the testes begin descending toward the scrotum. Disappearance of vernix and lanugo and pale, less-wrinkled skin are features of term (38-40 weeks), so B, C and D are incorrect.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The correct sequence of antenatal abdominal palpation is.', 'Fundal, lateral, pelvic', 'Fundal, pelvic, lateral', 'Pelvic, lateral, fundal', 'Lateral, fundal, pelvic', 'A', 'Per Myles, the correct sequence of antenatal abdominal palpation is fundal palpation, then lateral palpation, then pelvic palpation (with Pawlik''s grip to confirm the presenting part). The other sequences reverse or transpose these steps.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('To help a woman recognize the best time for conceiving a midwife would instruct the woman to monitor for:', 'Abdominal bloating that occurs suddenly', 'Breast tenderness accompanied by slight nipple discharge', 'Drop in the body temperature lasting several days', 'Increase in amount of cervical mucus that is clear and stretchy.', 'D', 'Per family-planning/fertility-awareness teaching (Kenya MOH FP guidelines), peak fertility is signalled by abundant clear, slippery, stretchy (spinnbarkeit) cervical mucus around ovulation. Basal body temperature rises (not drops) after ovulation, so option C is wrong; bloating and breast tenderness are non-specific.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When performing a physical examination of a woman who is 34 weeks pregnant, a midwife would expect to palpate the uterine fundus at:', 'Umbilicus', 'Xymphoid process', 'Midway between umbilicus and xymphoid precess', 'Midway between the umbilicus and symphysis pubis', 'C', 'Per Myles fundal-height assessment, at 34 weeks the uterine fundus is palpated about midway between the umbilicus and the xiphisternum. It reaches the xiphisternum at ~36 weeks and the umbilicus at ~22-24 weeks, so those options are incorrect.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Areas of concern in individual child birth plan during antenatal care include:', 'Danger signs in pregnancy, identify a birth partner during delivery, diet', 'Identifying true and false signs of labour, ensure availability of funds for emergency, use of drugs', 'Planning for transport, knowing when baby is due, rest and exercise', 'Identifying dander signs in pregnancy, identifying a birth attendant, knowing when baby is due.', 'D', 'Per Kenya MOH FANC birth-preparedness guidance, key birth-plan components include recognising danger signs, identifying a skilled birth attendant/place of delivery, transport and funds, and knowing the expected date of delivery. Option D best captures danger signs, birth attendant and EDD; A and C omit the skilled attendant, a core element.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The temporary structure of the fetal circulation which carries pure oxygenated blood is:', 'Ductus arteriosus', 'Hypogastric arteries', 'Umbilical vein', 'Ductus Venosus', 'C', 'Per Myles fetal circulation, the umbilical vein carries oxygenated (pure) blood from the placenta to the fetus. The ductus venosus and ductus arteriosus carry mixed blood, and the umbilical/hypogastric arteries carry deoxygenated blood back to the placenta.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A danger signs during pregnancy is:', 'Reduced fetal movements', 'Labour pains more tha 12hours', 'Placenta not delivered within 30 minutes', 'Cord, arm or leg prolapse', 'A', 'Per Kenya MOH FANC danger-sign list, reduced fetal movements is a recognised antenatal danger sign requiring urgent assessment. Cord/limb prolapse and an undelivered placenta are intrapartum/third-stage complications, and prolonged labour is intrapartum, not a pregnancy (antenatal) danger sign.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The layer of the blastocyst that produces human chorionic gonadotropin is:', 'Syncytiotrophoblas', 'Cytotrophoblast', 'Mesoderm', 'Ectoderm', 'A', 'Per embryology (Langman/Myles), the syncytiotrophoblast produces human chorionic gonadotropin (hCG), which maintains the corpus luteum in early pregnancy. The cytotrophoblast is the inner cellular trophoblast layer, and mesoderm/ectoderm are embryonic germ layers, not hCG sources.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Most pregnant women experience morning sickness between the weeks', '4th – 14th', '8th – 10th', '1st – 5th', '20th – 30th', 'A', 'Per Myles/obstetric teaching, morning sickness (nausea and vomiting of pregnancy) is a first-trimester feature, typically beginning around week 4-6 and largely resolving by about week 14. Option A (4th-14th) best fits this window; the other ranges are too narrow or too late.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The sequence of delivery of head in a normal labor is:', 'Chin – face – brow – vertex – occiput', 'Occiput – vertex – brow – face – chin', 'Face – brow – vertex – occiput – chin', 'Vertex – brow – face – chin – occiput', 'B', 'Per Myles, in normal labour with a well-flexed vertex the head is born by extension, and the parts sweep the perineum in the order occiput, then vertex, brow, face and finally chin. Option B gives this correct sequence; the others reverse or scramble it.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The shortest diameter of the true pelvis is.', 'Interspinous diameter', 'Diagonal conjugate', 'True conjugate', 'Intertuberous diameter', 'A', 'Per Myles pelvic anatomy, the interspinous (bispinous) diameter between the ischial spines, about 10-10.5 cm, is the shortest diameter of the true pelvis and the narrowest plane the fetus must negotiate. The diagonal/true conjugates (~11-12.5 cm) and intertuberous diameter (~11 cm) are larger.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A hormone synthesized and stored in the anterior pituitary gland, that stimulates milk production after child birth is called', 'Prolactin', 'Progesterone', 'Oestrogen', 'Oxytocin', 'A', 'Per Myles/physiology, prolactin, secreted by the anterior pituitary, stimulates milk production (lactogenesis) after childbirth. Oxytocin (posterior pituitary) causes the milk-ejection/let-down reflex, and progesterone/oestrogen actually suppress lactogenesis until their post-delivery fall.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Artificial rupture of the membrane (ARM) is also called.', 'Amniocentesis', 'Amnioticity', 'Amniogravidus', 'Amniotomy', 'D', 'Per Myles Textbook for Midwives, artificial rupture of membranes (ARM) is termed amniotomy, the deliberate rupture of the amniotic sac with an amnihook to induce or augment labour. Amniocentesis is aspiration of amniotic fluid for testing; the other terms are not recognised.', 'KRCHN', 'Paper I', 'Midwifery', 'Labour Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Occurs when a foetus is born with no signs of life before 24weeks gestation.', 'Miscarriage', 'Perinatal mortality', 'Early neonatal death', 'Still birth', 'A', 'Per Myles Textbook for Midwives, loss of a fetus with no signs of life before 24 weeks (viability) is a miscarriage (spontaneous abortion). Stillbirth is fetal death at or after the viability threshold (24/28 weeks); perinatal and early neonatal death involve later or post-birth deaths.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A woman in your early pregnancy class asks when she will feel her baby move. You base your response on the knowledge that fetal movement are usually FIRST felt by the mother between,', '6 – 10 weeks', '16 – 18 weeks', '16 – 20 weeks', '21 – 24 weeks', 'C', 'Per Myles Textbook for Midwives (17th Edition), quickening — the mother''s first perception of fetal movement — is felt between 16 and 20 weeks of gestation. Multigravidas tend to feel movement earlier, around 16–18 weeks, while primigravidas usually feel it between 18 and 20 weeks. The question asks generally, without specifying parity, so the correct inclusive range is 16–20 weeks (option C). Option B (16–18 weeks) is too narrow because it excludes primigravidas. Option A (6–10 weeks) is far too early. Option D (21–24 weeks) is beyond the normal expected range.', 'KRCHN', 'Paper I', 'Midwifery', 'Antenatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A laboring woman has been pushing for 45 minutes in a semi recumbent position, but has made no progress. Which of the following is MOST likely to promote the progress of labour.', 'Changing her position', 'Augmenting with Pitocin', 'Applying fundal pressure', 'Prolonged breath holding with contraction', 'A', 'Per Myles Textbook for Midwives and WHO intrapartum care, changing to an upright/alternate maternal position uses gravity and optimises pelvic diameters to promote descent when second-stage progress stalls. Fundal pressure and prolonged breath-holding (Valsalva) are discouraged as unsafe, and oxytocin augmentation is a later, medically-directed step.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The largest diameter of the fetal skull is', 'Sub-mento vertical', 'Mento occipital', 'Mento-vertical', 'Sub- occipital frontal', 'C', 'Per Myles Textbook for Midwives, the mento-vertical diameter (~13.5 cm), presenting in a brow presentation, is the largest anteroposterior diameter of the fetal skull. It exceeds the mento-occipital and sub-occipito-frontal diameters, which is why a persistent brow presentation obstructs vaginal delivery.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A woman is brought to a maternity in labour and the fetal heart rate is noticed to be 114bpm. Which is the best action for the midwife to take first.', 'Monitor the FHR every 15 minutes', 'Administer oxygen inhalation', 'Call the obstetrician', 'Place her on the left lateral position', 'D', 'An FHR of 114 bpm is within the normal fetal range (110-160 bpm) but at the lower end; the safe first intrauterine resuscitation manoeuvre is placing the woman in the left lateral position to relieve aortocaval compression and improve placental perfusion (Myles Textbook for Midwives). Oxygen and calling the obstetrician are later steps, and continued 15-minute monitoring alone is insufficient as a first corrective action. Left lateral positioning is the least invasive, immediate corrective step.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The transition period between childhood and adulthood is called?', 'Puberty', 'Adolescence', 'Teenager', 'Youth', 'B', 'Adolescence is the WHO-defined developmental transition between childhood and adulthood (roughly 10-19 years); puberty denotes only the physical/hormonal maturation occurring within adolescence (WHO adolescent health framework; Kozier Fundamentals of Nursing). ''Teenager'' and ''youth'' are colloquial/age-band terms, not the developmental-stage term. Adolescence is therefore correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The four pelvic joints of the bony pelvis include the following except', '1 symphysis pubis', '2 sacroilliac joints', '1 sacrococcygeal joint', '2 sacrococcygeal joint', 'D', 'The four joints of the bony pelvis are one symphysis pubis, two sacroiliac joints and one sacrococcygeal joint (Myles Textbook for Midwives). There is only ONE sacrococcygeal joint, so option D (''2 sacrococcygeal joint'') is the false statement and the correct ''except'' answer. Options A, B and C correctly state real pelvic joints.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The four bones of the bony pelvis include the following except.', '2 innomimate bones', '2 sucrums', '1 sucrum', '1 coccyx', 'B', 'The four bones of the bony pelvis are two innominate (hip) bones, one sacrum and one coccyx (Myles Textbook for Midwives). There is only ONE sacrum, so option B (''2 sacrums'') is the false statement and correct ''except'' answer. The OCR garbles ''sacrum'' as ''sucrum'' but the intent is clear.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Three supports of the uterus include the following except.', 'Ovarian ligamrnts', 'Broad ligaments', 'Round ligaments', 'Pelvic plexus', 'D', 'The uterus is supported by ligaments — the broad, round, ovarian (plus uterosacral and cardinal) ligaments (Myles Textbook for Midwives). The pelvic plexus is an autonomic nerve network, not a supporting ligament, so it is the correct ''except'' answer. The stem''s ''three supports'' phrasing is loose but the intended exception is the non-ligamentous structure.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Uterus leans forward and bends forwards on itself means?', 'Anteversion and anteflexion', 'Anteflexion and anteversion', 'Eversion and anteflexion', 'Flexionand and anteversion', 'A', 'The normal uterus leans forward over the bladder (anteversion) and bends forward on itself at the isthmus (anteflexion); the stem lists ''leans forward...bends forward on itself'', matching anteversion then anteflexion in that order (Myles Textbook for Midwives). Option B reverses the order, and options C/D introduce ''eversion''/garbled terms. Option A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The function of the batholin gland.', 'Secrets female hormone during menses', 'Secretes mucus which lubricates vaginal opening', 'Secrets vaginal acids', 'Erectile tissue of vestibular bulb of clitoris', 'B', 'The Bartholin''s (greater vestibular) glands secrete mucus that lubricates the vaginal introitus, especially during sexual arousal (Myles Textbook for Midwives; standard anatomy). They do not secrete hormones or vaginal acids, and the erectile vestibular bulb is a separate structure. Option B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Prominence ischial spines indicate reduced', 'Oblique diameter of the pelvic outlet', 'Transverse diameter of the pelvic brim', 'Diameter of the pelvic cavity', 'Transverse diameter of the pelvic outlet', 'C', 'Per Myles Textbook for Midwives, the ischial spines project into the pelvic cavity and define the mid-pelvic plane. The bispinous (interspinous) diameter — the narrowest diameter of the true pelvis — lies at the level of the pelvic cavity (mid-pelvis). Prominent ischial spines encroach on and reduce the diameter of the pelvic cavity. The pelvic outlet is bounded by the ischial tuberosities (intertuberous diameter), not the spines; the transverse diameter of the outlet (option D) is therefore not defined by ischial spine prominence. The pelvic brim (option B) is the inlet plane and is also unaffected by spine prominence.', 'KRCHN', 'Paper I', 'Midwifery', 'Pelvic Anatomy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Monthly physiological changes takes place in the ovary and the uterus, regulated by hormone produced by?', 'The anterior pituitary gland, uterus and hypothalamus', 'The posterior pituitary gland, ovaries and hypothalamus', 'The hypothalamus, anterior pituitary gland and ovaries', 'The hypothalamus, posterior pituitary gland and ovaries', 'C', 'The cyclical ovarian and uterine changes are regulated by the hypothalamic-pituitary-ovarian axis: the hypothalamus (GnRH), the anterior pituitary (FSH/LH) and the ovaries (oestrogen/progesterone) (Myles Textbook for Midwives; reproductive physiology). Options citing the posterior pituitary are wrong because it secretes oxytocin/ADH, not the cycle-regulating gonadotrophins. Option C correctly names all three axis components.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The diagonal conjugate is measured between which two points of the pelvis', 'Sacral promontory to the posterior border of the upper surface of the symphysis pubis', 'Extends across the greatest width of the brim', 'Lower border of the symphysis to the sacral promontory', 'Sacral promontory to the upper most point of the symphysis pubis', 'C', 'The diagonal conjugate is measured clinically from the lower (inferior) border of the symphysis pubis to the sacral promontory (~12-13 cm), from which ~1.5-2 cm is subtracted to estimate the obstetric conjugate (Myles Textbook for Midwives). Option A describes the true/anatomical conjugate (upper symphysis border), and option B describes the transverse diameter, so they are wrong. Option C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The average length of normal cycle that recurs regularly from puberty to the menopause takes?', '14 days', '28 days', '30 days', '5 days', 'B', 'The average length of the normal menstrual cycle, recurring from puberty to menopause, is 28 days (Myles Textbook for Midwives). 14 days is the approximate follicular/luteal half, and 5 days is the average menses duration, so those are distractors. Option B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Woman’s ability to have a safe and healthy pregnancy and delivery', 'Antenatal care', 'Perinatal care', 'Safe motherhood', 'Postnatal', 'C', 'Safe motherhood is the concept of ensuring a woman''s ability to have a safe, healthy pregnancy and delivery (and a healthy newborn) (Kenya Safe Motherhood/Reproductive Health guidelines). Antenatal, perinatal and postnatal care are individual components/phases within safe motherhood, not the overarching ability described. Option C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The layer of the endometrium that never alters during menstrual cycle is called', 'Regenerative', 'Functional layer', 'Cuboidal Layer', 'Basal layer', 'D', 'The basal layer of the endometrium is not shed during menstruation and remains constant; it regenerates the functional layer that is lost each cycle (Myles Textbook for Midwives). The functional/regenerative layer is precisely the part that alters and sheds, so those options are wrong. Option D is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The cavity is a circular in shape. Diameter is considered to be:', '13 cm', '12 cm', '11 cm', '10 cm', 'C', 'The pelvic cavity is described as almost circular in shape, with its anteroposterior and transverse diameters each averaging about 11 cm (Myles Textbook for Midwives). 12-13 cm overstates and 10 cm understates the cavity diameter, so those are distractors. Option C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The human sexual response cycle consist of the following stages in order.', 'Excitement, plateau, resolution, orgasm', 'Excitement, plateau, orgasm, resolution', 'Excitement, resolution, orgasm, plateau', 'Plateau, orgasm, excitement and resolution', 'B', 'Masters and Johnson''s human sexual response cycle proceeds in order: excitement, plateau, orgasm, resolution (standard reproductive physiology). The other options reorder the phases incorrectly (e.g. resolution before orgasm). Option B lists the correct sequence.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Four foundation measures of safe mother hood', 'Skilled attendant, lack of supportive system, male involvements and equity for all', 'Skilled attendant, supportive system, lack of male involvement and equity for all', 'Unkilled attendants, supportive health system, male involvement and equity for all', 'Skilled attendant, supportive health systems, male involvements and equity for all', 'D', 'The foundation measures/pillars of safe motherhood are a skilled attendant, a supportive health system, male involvement and equity for all (Kenya Safe Motherhood framework). Options A/B negate an element (''lack of supportive system'', ''lack of male involvement'') and option C says ''unskilled attendants''. Option D lists all four correctly.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Factors influencing maternal mortality', 'Prenatal care, parity, sex, socio-economic factors', 'Prenatal care, parity, age, gender.', 'Prenatal care, parity, age, socio-economic factors', 'Prenatal care, gender,age, socio-economic factors', 'C', 'Factors influencing maternal mortality include prenatal care, parity, maternal age and socio-economic factors (WHO/Kenya maternal health). ''Sex'' and ''gender'' are irrelevant to maternal deaths (all mothers are female), so options A, B and D that include them are wrong. Option C lists the correct four determinants.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The definition of a perinatal death is:', 'The death of a fetus weighing at least 200grams, (or 22 weeks gestation) plus the number of early neonatal death (up to 7 days)', 'The death of fetus weighing at least 500grams, (or 22 weeks gestation) plus the number of early neonatal death (up to 7 days)', 'The death of a fetus weighing at least 500grams ( or 22 weeks gestation) plus the number of early neonatal deaths (up to 5 days )', 'The death of fetus weighing at least 800grams ( or 22 weeks gestation) plus the number of early neonatal deaths (up to 7 days)', 'B', 'Perinatal death is defined as fetal death of a fetus weighing at least 500 g (or ~22 weeks gestation) plus early neonatal deaths up to 7 days of life (WHO/ICD perinatal definition). Option A uses 200 g, option C uses 5 days, and option D uses 800 g — all incorrect. Option B correctly states 500 g and 7 days.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pillars of safe motherhood include the following except', 'Focused antenatal care', 'Safe and clean delivery', 'Youth friendly', 'Essential obstetric care', 'C', 'The pillars of safe motherhood are family planning, focused antenatal care, clean/safe delivery, essential obstetric care and postnatal/post-abortion care (WHO/Kenya Safe Motherhood). ''Youth friendly (services)'' is an adolescent reproductive-health concept, not a safe-motherhood pillar, so it is the correct ''except'' answer. Options A, B and D are genuine pillars.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Making motherhood safe requires the following action', 'Reduce the number of high risk and unwanted pregnancies', 'Reduced the number of obstetric complication', 'Reduced the case of high fertility rate in women with complication', 'Increased the case of high fertility rate in women with complication', 'A', 'Making motherhood safe requires reducing the number of high-risk and unwanted pregnancies, primarily through family planning (Kenya Safe Motherhood/RH guidelines). Options that ''increase'' fertility or complications are clearly wrong, and the OCR-garbled ''reduced'' options B/C are less complete than A. Option A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The cells of the breast that contract and propel the milk out of the lobule are:', 'Acini', 'Myoepithelial', 'Lactiferous tubules', 'Lobular', 'B', 'Myoepithelial cells surround the acini/alveoli of the breast and contract under oxytocin to propel milk out of the lobule into the ducts — the milk-ejection (let-down) reflex (Myles Textbook for Midwives). Acini are the secretory cells, and lactiferous tubules/lobules are conducting/structural, not contractile. Option B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Structures in fetal circulation which carries deoxygenated blood and wastes products from the fetus to the placenta for excretion are:', 'Umbilical ligaments', 'Foramen ovale', 'Ductus arteriosus', 'Umbilical arteries', 'D', 'The two umbilical arteries carry deoxygenated blood and waste products from the fetus to the placenta, while the single umbilical vein returns oxygenated blood to the fetus (Myles Textbook for Midwives). The foramen ovale and ductus arteriosus are shunts within the fetal circulation, and umbilical ligaments are postnatal remnants, so they are wrong. Option D is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An infant death is referred to as:', 'One occurs in the 1st one year of life', 'A still birth or death occurring in the fisrt 28 days of life', 'One occurring in the first 28 days of life', 'Failure of baby to show signs of life after expalsion from the uterus', 'A', 'An infant death is the death of a live-born child before the first birthday (under 1 year) (WHO/Kenya MOH definitions). Death within the first 28 days is specifically a neonatal death (a subset of infant death), and failure to show signs of life after expulsion describes stillbirth, so those options are narrower or wrong. Option A (''occurs in the first one year of life'') is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In uterine asphyxia is a common complication of:', 'Caesarean section', 'Uterine atony', 'Obstructed labor', 'Hyperemesis gravidarum', 'C', 'Prolonged/obstructed labour causes intrauterine (fetal) asphyxia through impaired placental perfusion and cord compression during strong or prolonged contractions (Myles Textbook for Midwives). Caesarean section and hyperemesis gravidarum are not primary causes of intrauterine asphyxia, and uterine atony is a postpartum haemorrhage cause. Option C is correct. (The stem''s ''in uterine asphyxia'' is an OCR rendering of ''intrauterine asphyxia''.)', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The signs and symptoms of mild hypothermia in a new born include:', 'Restlessness, increased respiratory rate, hypoglycemia', 'Little movements of limbs, hypercalcemia, decreased respiratory rate', 'Restlessness, decreased respiratory rate, hypoglycemia', 'Little movements of the limbs, dehydration, increased respiratory rate', 'C', 'In neonatal cold stress/mild hypothermia the baby becomes restless/irritable, develops hypoglycaemia from increased metabolic demand, and shows a falling (decreased) respiratory rate as hypothermia progresses (Kenya Basic Paediatric Protocols; Myles). Option A wrongly cites increased respiratory rate, and option B cites hypercalcaemia; option D adds dehydration. Option C best captures mild neonatal hypothermia.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fetal cause of fetal distress include:', 'Hypotension, cord prolapse, hemorrhage', 'Pre-eclampsia, placenta abruption, cord presentation', 'Hypotension, pre-eclampsia, hemorrhage', 'Cord prolapse, placenta abruption, cord presentation.', 'D', 'Fetal (as opposed to maternal) causes of fetal distress relate to compromised umbilical/placental oxygen delivery — cord prolapse, cord presentation and placental abruption (Myles Textbook for Midwives). Maternal hypotension and pre-eclampsia are maternal factors, so options A, B and C are wrong. Option D lists cord/placental causes and is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The midwife prevents spina bifida antenatally by:', 'Tetanus toxoid', 'Folic acid', 'Ferrous sulphate', 'Albendazole', 'B', 'Periconceptional and antenatal folic acid supplementation prevents neural tube defects such as spina bifida (Kenya National maternal guidelines; WHO). Tetanus toxoid prevents neonatal tetanus, ferrous sulphate treats/prevents anaemia, and albendazole treats helminths — none prevent spina bifida. Option B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When the fetus is in occipital posterior and takes a persistence occipo-posterior position, the outcome of the delivery is:', 'Spontaneous vertex delivery', 'Face to pubis', 'Breech delivery', 'Symphysiotomy', 'B', 'In a persistent occipitoposterior position that fails to undergo long internal rotation, the head extends and delivers face-to-pubis (the persistent OP outcome) (Myles Textbook for Midwives). Spontaneous vertex delivery follows normal anterior rotation, breech relates to a different presentation, and symphysiotomy is an intervention, not an outcome. Option B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The clinical features of cardiac disease in pregnancy include:', 'Raised jugular vein pressure, tachypnea, dyspnea', 'Hematemesis, hemoptysis, tachycardia', 'Tachypnea, chest pain with activity, dyspnea', 'Palpitations, distended neck vein, bradycardia', 'A', 'Cardiac disease in pregnancy presents with signs of cardiac congestion/failure: raised jugular venous pressure, tachypnoea and dyspnoea (Myles Textbook for Midwives; Brunner & Suddarth). Haematemesis (option B) and bradycardia (option D) are not typical, and while chest pain and tachypnoea (option C) occur, the classic congestive triad in option A is the best-fit answer. Option A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The signs and symptoms of pyelonephritis in pregnancy include:', 'Urinary agency, urinary frequency, dysuria, haematuria, rigors', 'Bradycardia, haematuria, urinary frequency and proteinuria', 'Reduced fetal movements, haematuria, tachycardia and proteinuria', 'Tachycardia, pyrexia, severe vomiting and burning sensation on micturition.', 'D', 'Acute pyelonephritis in pregnancy presents with high fever/rigors, tachycardia, loin pain, nausea/severe vomiting and dysuria (burning micturition) — a systemic sepsis picture (Kenya MOH clinical guidelines; Brunner & Suddarth). Option D best captures this systemic presentation, whereas options A-C mix in bradycardia, proteinuria and reduced fetal movements that are not the hallmark features. Option D is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The dose of magnesium sulphate to a pregnant woman with pre eclampsia following fits is:', 'IV 4g loading dose given slowly, followed by 10g IM (5g into each buttock) as loading, then 5g IM every 4 hours for 24 hours', 'IV 4mg started slowly followed by 10g IM slowly then 4g IM every 4 hours for 24 hours', 'IV 5mg start slowly followed by 5mg IM slowly on each buttock every 4 hours for 24 hours', 'IV 4g started slowly followed by 5g IM slowly then 4g IM every 4 hours for 24 hours', 'A', 'Per the Kenya MOH/WHO Pritchard eclampsia regimen, the correct magnesium sulphate protocol is: a 4g IV loading dose given slowly over 5–10 minutes, PLUS a simultaneous 10g IM loading dose (5g into each buttock as a 50% solution), followed by 5g IM into alternate buttocks every 4 hours for at least 24 hours after the last fit. Option A is the only choice that correctly states all three components — 4g IV loading, 10g IM simultaneous loading, and 5g IM every 4 hours maintenance. Option B uses milligrams (4mg) — an incorrect unit. Option C uses milligrams and the wrong maintenance route. Option D omits the full 10g IM loading dose and uses 4g (not 5g) for maintenance — both departures from the Pritchard standard.', 'KRCHN', 'Paper I', 'Midwifery', 'Obstetric Emergencies', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Tear of the fourchette is classified as:', 'Second degree', 'Third degree', 'Fourth degree', 'First degree', 'D', 'Per Myles Textbook for Midwives, a first-degree perineal tear involves only the fourchette, perineal skin and vaginal mucosa without muscle involvement. A second-degree tear extends into the perineal muscles, third-degree involves the anal sphincter, and fourth-degree extends into the rectal mucosa, so those options are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In an obstructed labour there is:', 'Good descent but poor contractions', 'Adequate pelvis with good contractions', 'No descent with good contractions', 'Slow descent with moderate contractions', 'C', 'Per Myles Textbook for Midwives, obstructed labour is characterised by strong (good) uterine contractions with failure of descent of the presenting part due to a mechanical obstruction. Option C (no descent with good contractions) captures this; options describing adequate pelvis or good descent contradict the definition of obstruction.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Causes of puerperal pyrexia include:', 'Deep venous thrombosis, pulmonary embolism', 'Genital tract infection, urinary tract infection', 'Urine retention, urinary tract infection', 'Deep venous thrombosis, crackle nipples.', 'B', 'Per Myles Textbook for Midwives, puerperal pyrexia (temperature >=38C in the puerperium) is most commonly due to genital tract (endometritis) and urinary tract infection. DVT, pulmonary embolism and cracked nipples/mastitis are less common or secondary causes, so option B lists the classic infective causes.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Risk of HIV transmission from breastfeeding is increased when the mother.', 'Has unprotected sex with an infected partner during puerperium, involved in substance abuse', 'Has smoking habit, has STIs and other co-infections', 'Has crackle nipple, abscess or other breast problems, has symptoms for HIV related disease.', 'Become first infected while pregnant or while she is breast feeding, has vitamin A deficiency.', 'D', 'Per Kenya PMTCT guidelines, new (acute) maternal HIV infection acquired during pregnancy or breastfeeding produces a high viral load and greatly raises transmission risk, and maternal vitamin A deficiency further increases risk. Cracked nipples/breast abscess (option C) do increase risk but option D captures the highest-risk acute-infection scenario with a recognised nutritional co-factor.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of cardiac disease Grade IV in pregnancy include:', 'A heart lesion exist but the patient is a symptomatic, leads a normal active life without discomfort or breathlessness.', 'Patient experience breathlessness, exhaustion with moderate to heavy work, has slight limitation of physical activities', 'Heart lesion exist and patient is symptomatic, patient is unable to carry out any light work or exercise.', 'Patient experience breathlessness with any light work or exercice, has marked limitation to physical activities.', 'C', 'By the NYHA classification (Myles), Grade/Class IV cardiac disease means symptoms at rest and inability to undertake any physical activity without discomfort. Option C (heart lesion, symptomatic, unable to do any light work) best reflects this; options describing asymptomatic normal life (Grade I) or symptoms only on moderate/heavy work (Grades II-III) are lower grades.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The clinical features that suggest of acute pyelonephritis in pregnancy is:', 'Kinking of the ureters', 'Vesico-uretic reflux', 'Fishy smell in urine', 'Sugar in urine', 'B', 'Per Myles Textbook for Midwives, physiological ureteric dilatation and vesico-ureteric reflux in pregnancy predispose to ascending infection and clinically suggest acute pyelonephritis. Kinking of the ureters is anatomical predisposition rather than a clinical feature, fishy urine suggests bacterial vaginosis, and glycosuria is not a feature of pyelonephritis.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The drug of choice in management of eclampsia:', 'Phenobarbitone', 'Magnesium sulphate', 'Calcium gluconate', 'Sodium bicarbonate', 'B', 'Per Kenya MOH and WHO guidelines, magnesium sulphate is the drug of choice to control and prevent convulsions in eclampsia. Phenobarbitone is inferior for eclamptic seizures, calcium gluconate is the antidote for magnesium toxicity, and sodium bicarbonate has no role in seizure control.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During induction of labor on Bishops score, the finding noted on the cervix include:', 'Dilatation, consistency, effacement', 'Consistency, descent, position', 'Effacement, station, dilatation.', 'Adequacy, position, dilatation', 'A', 'Per Myles Textbook for Midwives, the Bishop score assesses cervical dilatation, consistency, effacement and position (plus fetal station). Option A lists three genuine cervical parameters; options citing descent, station or ''adequacy'' refer to the presenting part or are not Bishop cervical criteria.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The commonest cause of primary Postpartum Hemorrhage is:', 'Trauma of the genital tract', 'Blood coagulation disorder', 'Prolonged 3rd stage of labour', 'Atony of the uterus', 'D', 'Per Myles and Kenya MOH guidelines, uterine atony is the commonest cause of primary postpartum haemorrhage, accounting for roughly 70-80% of cases (first of the 4 Ts). Genital tract trauma, coagulopathy and prolonged third stage are less frequent causes.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Quickening', 'Can occurs as early as 16 weeks of gestation', 'Is a positive sign of pregnancy', 'Refers to pulsation of fornices', 'Is caused by increased blood flow to the uterus', 'A', 'Per Myles Textbook for Midwives, quickening (maternal perception of fetal movements) is a presumptive/subjective sign, not a positive sign of pregnancy, and may be felt as early as 16-18 weeks in multiparous women. Option B is wrong because it is only presumptive; options C and D misdescribe its cause.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a minor complication of pregnancy.', 'Breast tenderness', 'Constipation', 'Deep venous thrombosis', 'Leucorrhea', 'C', 'Per Myles Textbook for Midwives, breast tenderness, constipation and leucorrhoea are minor disorders of pregnancy, whereas deep venous thrombosis is a major/potentially life-threatening complication. The question asks which is NOT minor, so C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The four stages of an eclamptic fit in order of occurrence', 'Premonitory, tonic, clonic, coma', 'Premonitory, clonic, tonic, coma', 'Coma, clonic, tonic, premonitory', 'Tonic, coma, premonitory, clonic', 'A', 'Per Myles Textbook for Midwives, an eclamptic fit proceeds in order through premonitory, tonic, clonic, then coma stages. Options reversing tonic and clonic or beginning with coma contradict the recognised sequence.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In placenta previa:', 'There is severe lower abdominal pain on abdominal examination', 'The degree correspond to the amount of bleeding', 'The midwife should perform a digital vaginal examination to confirm the degree.', 'Vagina delivery is possible for 2nd degree type.', 'B', 'Per Myles Textbook for Midwives, placenta praevia causes painless bleeding (so option A is wrong), digital vaginal examination is contraindicated (option C wrong), and vaginal delivery is generally not safe with major degrees. The degree of praevia broadly corresponds to the severity/amount of bleeding, making B the best answer.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following does not measure labor progress while using a partograph:', 'Cervical dilatation', 'Blood pressure', 'Contraction', 'Descent of the presenting part.', 'B', 'Per the WHO/Myles partograph, labour progress is measured by cervical dilatation, descent of the presenting part and uterine contractions. Blood pressure is a maternal-condition observation recorded on the partograph but does not measure labour progress, so B is the exception.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The antidote for magnesium sulphate:', 'Dantrolene', 'Protamine', 'Calcium gluconate', 'Acetylcysteine', 'C', 'Per Kenya MOH guidelines, calcium gluconate (10ml of 10% IV slowly) is the antidote for magnesium sulphate toxicity. Dantrolene treats malignant hyperthermia, protamine reverses heparin, and acetylcysteine treats paracetamol overdose, so those are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The action of Oxytocin on the uterus is by.', 'Inhiting spontaneous contract of the pregnant uterus', 'Contracting the pregnant uterus but relaxes the cervix', 'Causing regular coordinated uterine contractions followed by relaxation', 'Causing uterine contraction with an increase in basal tone', 'C', 'Per Myles Textbook for Midwives (17th Edition) and standard obstetric physiology, oxytocin stimulates the myometrium to produce regular, rhythmic, coordinated uterine contractions, each followed by a period of relaxation. This characteristic intermittent contraction-relaxation pattern is the hallmark of normal oxytocin-stimulated labour, allowing uteroplacental blood flow to be restored between contractions. Option A is incorrect — oxytocin does the opposite, stimulating rather than inhibiting contractions. Option B is incorrect — oxytocin does not directly relax the cervix; cervical ripening is mediated primarily by prostaglandins. Option D describes a pathological effect: an excessive increase in resting (basal) uterine tone causing tonic/tetanic contractions is an adverse reaction to oxytocin overdose, not its intended normal physiological action. The therapeutic action of oxytocin is coordinated, intermittent contractions with relaxation between them — option C.', 'KRCHN', 'Paper I', 'Midwifery', 'Pharmacology in Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The placenta does not produce:', 'Human chorionic somatomammotropin (placental lactogen)', 'Chorionic gonadotropin', 'Follicle stimulating hormone', 'Progesterone precursor substance', 'C', 'The placenta is an active endocrine organ. It produces: hCG — maintains the corpus luteum; human chorionic somatomammotropin (hCS/hPL) — growth-hormone- and prolactin-like activity; progesterone (takes over from corpus luteum at ~10–12 weeks); oestrogens synthesised using fetal adrenal precursors. Follicle-stimulating hormone (FSH) is produced exclusively by the anterior pituitary gland under hypothalamic GnRH control — the placenta has no capacity to produce it. Option A has been corrected from the OCR error ''somatotropin'' (anterior-pituitary growth hormone) to the accurate placental hormone ''human chorionic somatomammotropin''. FSH (option C) is the only listed hormone the placenta does NOT produce.', 'KRCHN', 'Paper I', 'Midwifery', 'Placental Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The post-partum nurse should encourage newly delivered clients to ambulate early in order to promote:', 'Respiration', 'Increase the tone of the bladder', 'Maintain the tone of abdominal muscles', 'Increase periphery vasomotor activity', 'D', 'Per Myles Textbook for Midwives, early ambulation in the puerperium improves peripheral circulation and venous return (peripheral vasomotor activity), reducing venous thromboembolism risk. While ambulation also aids respiration and bladder/muscle tone, the classic taught rationale is promotion of peripheral circulation to prevent thrombosis, so D is the best answer.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client in active labor spontaneously raptures membranes. The nurse should first.', 'Monitor fetal heart rate', 'Call the physician', 'Check BP and pulse', 'Time contraction', 'A', 'Per Myles Textbook for Midwives, immediately after spontaneous rupture of membranes the priority is to auscultate the fetal heart rate to detect cord prolapse or fetal distress. Checking maternal BP/pulse, timing contractions or calling the physician are secondary to first confirming fetal wellbeing.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('On vaginal observation, during labour the midwife should document the following about the cervix.', 'Effacement, ischial spines, dilatation', 'Effacement, position, dilatation', 'Position, ischial Spines', 'Effacement, Ischial Spines, position', 'B', 'Per Myles Textbook for Midwives, on vaginal examination the cervix is documented for effacement, position, consistency and dilatation. Option B lists valid cervical findings; the ischial spines relate to descent/station of the presenting part, not the cervix, so options citing ischial spines are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The management of hyperemesis gravidarum include:', 'Antibiotics, psychological support', 'Psychological support, correct fluids and electrolytes imbalance', 'Correct fluid and electrolytes imbalances, antibiotics', 'Encourage oral feeds, antiemetic', 'B', 'Per Myles/Kenya MOH, management of hyperemesis gravidarum centres on IV correction of fluid and electrolyte imbalance, antiemetics and psychological support. Antibiotics are not indicated (excluding options A and C), and oral feeds are withheld initially, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The expected date of delivery (EDD) of a mother whose last menstrual period was 24/9/2019 is:', '31/7/2020', '01/06/2020', '31/06/2020', '01/07/2020', 'D', 'By Naegele''s rule (Myles), from LMP 24/9/2019 add 7 days (1/10) and subtract 3 months to give an EDD of 01/07/2020. Option D is correct; the other dates result from arithmetic errors, and options C (31/06) is an invalid calendar date.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are major cause of post-partum hemorrhage except:', 'Excessive use of uterotonic medication during labor', 'Pre-existing or acquired coagulopathy', 'Fetal distress during labor', 'Retained placenta and clots.', 'C', 'Per Myles Textbook for Midwives, postpartum haemorrhage causes follow the 4 Ts (tone, tissue/retained placenta, trauma, thrombin/coagulopathy), and excessive uterotonic use can also contribute. Fetal distress in labour is not a cause of PPH, so it is the correct exception.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following doesn’t cause folic acid deficiency.', 'Low dietary intake', 'Reduced reabsorption', 'Excess folic acid demand and loss like in hemolytic anemia', 'Hookworm infestation', 'D', 'Per standard haematology (Brunner & Suddarth), folic acid deficiency results from low dietary intake, malabsorption (reduced reabsorption) and increased demand/loss such as haemolytic anaemia. Hookworm infestation causes chronic blood loss leading to iron-deficiency anaemia, not folate deficiency, so it is the exception.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which is the correct order of action given to a baby who has not cried at birth.', 'Clear the airway, position, provide warm, position', 'Position, provide warm, position, and clear the airway', 'Stimulate, clear the airway, position and provide warmth.', 'Provide warmth, position, clear the airway and stimulate', 'D', 'Per Kenya Basic Paediatric Protocols and Helping Babies Breathe newborn resuscitation, the initial steps in order are: provide warmth, position the head, clear the airway, then stimulate/dry before assessing breathing. Option D gives this correct sequence; the others place stimulation or airway clearance out of order.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A low birth weight baby weighs.', '100grams – 1500grams', '1500grams – 2000grams', '1500grams – 2500grams', 'Below 1000grams', 'C', 'Per WHO/Kenya definitions, low birth weight is any birth weight below 2500g; the range 1500-2500g represents LBW while below 1500g is very low birth weight. Option C best matches the LBW definition; the other ranges are incorrect or describe VLBW/ELBW.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('All HIV exposed infants should be done:', 'DNA PCR at 6 weeks or at first contact thereafter', 'HIV antibody test at birth', 'HIV antibody test at 6 months and 12 months for those breastfeeding', 'DNA PCR at 18 months', 'A', 'Per Kenya Early Infant Diagnosis (EID) guidelines, HIV-exposed infants have a DNA PCR test at 6 weeks of age or at first contact thereafter, because antibody tests are unreliable before 18 months due to passively acquired maternal antibodies. Options relying on antibody testing at birth or 6 months are therefore incorrect.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Non pulmonary cause of RDS include:', 'Anemia, congenital heart disease, medication', 'Pneumothorax, anemia, upper airway obstruction', 'Persistent hypertension of the newborn, medications, chronic neonatal lung disease', 'Anemia, chronic neonatal lung disease, pneumothorax', 'A', 'Per Kenya Basic Paediatric Protocols, non-pulmonary causes of neonatal respiratory distress include anaemia, congenital heart disease and drug/medication effects. Pneumothorax, upper airway obstruction and chronic neonatal lung disease are pulmonary causes, so option A is the only purely non-pulmonary set.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Below are fetal factors associated with premature except.', 'Multiple pregnancies', 'Chromosomal abnormalities', 'Fetal placental dysfunction', 'Anatomical abnormalities', 'C', 'Per Myles Textbook for Midwives, fetal factors in preterm birth include multiple pregnancy, chromosomal abnormalities and anatomical abnormalities. Feto-placental dysfunction is a placental/uteroplacental factor rather than a strictly fetal factor, so C is the correct exception.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In second stage, the appropriate mode of delivery in a woman with cardiac disease grade III is:', 'Vacuum extraction', 'Spontaneous vertex delivery', 'Caesarean section', 'Laparotomy', 'A', 'Per Myles Textbook for Midwives, in cardiac disease Grade III the second stage should be shortened to limit the cardiac strain of bearing down, so an assisted vaginal (vacuum/forceps) delivery is preferred. Spontaneous vertex delivery prolongs pushing, and caesarean/laparotomy add unnecessary surgical cardiac stress, so A is best.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the management of primary postpartum hemorrhage, the uterine contraction are maintained by administering.', '40 units’ syntocinon in ½ litre normal saline', '40 units of syntocinon in 1 litre normal saline', '20 units of syntocinon in 1 litre normal saline', '20 units of syntocinon start', 'B', 'Per Kenya MOH/WHO PPH guidelines and Myles, after the initial oxytocin bolus sustained uterine contraction is maintained with an infusion of 40 units of oxytocin in 1 litre of normal saline. Options with 20 units or a half-litre volume give the wrong maintenance concentration, and a bolus-only option provides no maintenance.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common method of delivery of the placenta and the membrane.', 'Fundal pressure application', 'Maternal effort method', 'Controlled cord traction', 'Supra-pubic pressure application', 'C', 'Per Myles Textbook for Midwives and Kenya MOH maternal care guidelines, controlled cord traction (Brandt-Andrews) is the recommended and most common method of delivering the placenta and membranes in active management of the third stage. Fundal pressure and suprapubic pressure risk uterine inversion, and maternal effort alone is used in physiological management.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In grade II of cardiac condition in pregnancy the mother has.', 'Heart lesion on examination within no symptoms limiting activity', 'Marked limitation (dysponea or pain on minima activity less than ordinary activity)', 'Heart lesion and slight and marked symptoms at rest or patients failure', 'Heart lesion and slight limitation on mild to moderate activity but has no symptoms at rest.', 'D', 'By the NYHA classification used in cardiac disease in pregnancy (Myles), Grade/Class II means a heart lesion with slight limitation of physical activity: the mother is comfortable at rest but ordinary/mild-to-moderate activity causes symptoms. Marked limitation on minimal activity is Grade III, symptoms at rest is Grade IV, and no limitation is Grade I.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In placenta praevia type 3 partial implantation of the placenta.', 'Covers the external os even when the cervix is fully dilated', 'Lower margin dips into the lower segment', 'Reaches the internal os when closed but does not cover it.', 'Covers the internal os when closed but not when fully dilated', 'D', 'Per Myles Textbook for Midwives, Type III (partial central) placenta praevia covers the internal os when the cervix is closed but does not completely cover it once the cervix is fully dilated. Type IV covers the os even when fully dilated (option A), and lesser descriptions correspond to Types I-II, so D is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The obstetric procedures that is carried out to drain excessive amniotic fluid is refers to as:', 'Chorionic villi sampling', 'Abdominal centesis', 'Therapeutic amniocentesis', 'Placentalcentesis', 'C', 'Per Myles Textbook for Midwives, drainage of excess amniotic fluid (amnioreduction, e.g. in polyhydramnios) is therapeutic amniocentesis. Chorionic villus sampling is a diagnostic placental procedure, and ''abdominal centesis'' and ''placentacentesis'' are not the recognised terms for amniotic fluid drainage.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The complication of the amniotic fluid embolism associated with high mortality rate is:', 'Congenital disorders', 'Renal failure', 'Uterine atony', 'Convulsion', 'B', 'Per Myles Textbook for Midwives, amniotic fluid embolism triggers cardiorespiratory collapse, disseminated intravascular coagulation and multi-organ failure; acute renal failure is a major high-mortality complication among the listed options. Uterine atony/haemorrhage occurs but renal failure best fits the high-mortality organ failure asked for, and congenital disorders/convulsion are not AFE complications.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Some of the cause of delayed second stage of labor include:', 'Shoulder dystocia, precipitate labor', 'Uterine fibroids, cord prolapse', 'Obstruction in vagina, uterine inertia', 'Cord around the neck, precipitate labor.', 'C', 'Per Myles Textbook for Midwives, delayed second stage arises from the three P''s: poor powers (uterine inertia) and obstruction in the passage (vagina/soft tissue), both listed in option C. Precipitate labour causes a rapid rather than delayed second stage, so options containing it are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main cause of secondary post-partum hemorrhage is:', 'Retained of products of conception', 'Infection', 'Retained placenta', 'Fibroids', 'A', 'Per Myles Textbook for Midwives and Kenya MOH guidelines, secondary postpartum haemorrhage (24 hours to 6 weeks postpartum) is most commonly caused by retained products of conception, frequently with associated endometrial infection. Retained placenta and fibroids are less specific, and infection alone is usually secondary to retained tissue.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Direct cause of maternal mortality include:', 'Hemorrhage, Malaria, anemia', 'Eclampsia, haemorrhage, sepsis', 'Malaria, eclampsia, anemia', 'Anemia, cardiac disease, hemorrhage', 'B', 'Per Myles Textbook for Midwives (African edition), direct maternal deaths arise from obstetric complications of the pregnancy itself. The three classic direct causes are haemorrhage, eclampsia (hypertensive disorders of pregnancy) and puerperal sepsis. Option B (eclampsia, haemorrhage, sepsis) correctly lists all three unambiguous direct causes and is the only option free of indirect causes. Malaria, anaemia and cardiac disease are indirect causes — pre-existing conditions aggravated by pregnancy — and must not be listed as direct causes.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Deep transverse arrest occurs when:', 'The presenting dimensions of the flexed head escapes the pelvis', 'The head become extended and the face presents', 'The head is flexed at the onset of labour', 'The occipital diamenter is cought ata anarrow bisponius diameter of the outlet.', 'D', 'Per Myles Textbook for Midwives, deep transverse arrest occurs in an occipito-posterior labour when the head fails to rotate and arrests in the transverse position at the ischial spines, the occiput caught at the narrow bispinous (bis-ischial) diameter of the pelvic outlet. The other options describe normal flexion/descent or face presentation.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In polyhydromnios, the quantity of amniotic fluid exceeds:', '500mls', '800mls', '1,000mls', '2,000mls', 'D', 'Per Myles Textbook for Midwives (African edition), polyhydramnios is diagnosed when amniotic fluid volume exceeds 2,000 ml (2 litres) at term. Normal amniotic fluid at term is approximately 500–1,500 ml (average ~800–1,000 ml); 1,500 ml is the upper limit of normal, not the diagnostic threshold for polyhydramnios. Option D (2,000 mls) is the standard teaching cut-off per Myles. Modern obstetric practice also uses ultrasound criteria: AFI ≥ 24–25 cm or deepest vertical pocket ≥ 8 cm. Common causes: fetal congenital anomalies (oesophageal/duodenal atresia, anencephaly), maternal diabetes mellitus, multiple pregnancy, fetal anaemia (Rh isoimmunisation), idiopathic. Maternal/fetal complications include preterm labour, PROM, malpresentation, cord prolapse, placental abruption and postpartum haemorrhage from uterine overdistension.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A procedure used to strengthened labor contraction is called:', 'Induction', 'Vacuum extraction', 'Caesarean section', 'Augmentation', 'D', 'Per Myles Textbook for Midwives and Kenya MOH guidelines, augmentation is the procedure that strengthens/enhances existing but inadequate labour contractions (e.g. with oxytocin or ARM). Induction starts labour de novo, while vacuum extraction and caesarean section are modes of delivery, not methods of strengthening contractions.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A movement that should be observed before delivery of the shoulder is:', 'Restitution', 'Crowning', 'Extension', 'Extended rotation of the head.', 'A', 'Per Myles Textbook for Midwives, after delivery of the head restitution (the head untwisting to realign with the shoulders) is observed, followed by external rotation, before the shoulders are delivered. Crowning and extension occur during delivery of the head itself, not before the shoulders.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Some of the condition that predispose a mother to peuperial psychosis include:', 'Anemia, severe puerperal sepsis, Malaria', 'Anaemia, Diabetes, Cardiac disease', 'Epilepsy, Diabetes, Anemia', 'Severe puerperal sepsis, polyhydromnious', 'A', 'Puerperal psychosis is predisposed by conditions causing systemic exhaustion, toxaemia and infection such as severe puerperal sepsis, anaemia and malaria, together with a prior psychiatric history (Myles Textbook for Midwives). Options citing diabetes/cardiac disease/epilepsy/polyhydramnios describe obstetric-medical risks, not the infective/toxic-exhaustion triad classically linked to puerperal psychosis.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Some of the actual warning signs of the actual rapture of the uterus include.', 'Vaginal blood loss, rising pulse', 'Severe fetal distress, maternal shock', 'Tonic uterine contraction, maternal shock', 'Painful contraction, severe fetal distress', 'B', 'Actual (complete) rupture of the uterus presents with sudden cessation of contractions, severe fetal distress or death and maternal collapse/shock (Myles Textbook for Midwives). Tonic contraction and a rising pulse are features of impending/threatened rupture, so options C and A describe the warning phase rather than the actual rupture.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In breech presentation the denominator is:', 'Sacrum', 'Pubis', 'Occiput', 'Sinciput', 'A', 'In breech presentation the denominator is the sacrum (Myles Textbook for Midwives). The occiput is the denominator only in vertex presentation and the sinciput is not a recognised denominator, so B, C and D are incorrect.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Maurice au-smelle veit maneuver is used when:', 'The arms are extended', 'The arms are flexed', 'The head is flexed', 'The head is extended', 'D', 'The Mauriceau-Smellie-Veit manoeuvre (OCR-garbled in the stem) is used in breech delivery to flex and deliver an extended (deflexed) after-coming head (Myles Textbook for Midwives). It is not used for the arms (Lovset delivers extended arms), so options referring to the arms are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Occult cord prolapse occurs when the umbilical cord lies:', 'In front of the presenting part with fetal membranes still intact', 'In front of the presenting part and the fetal membrane is ruptured.', 'Alongside but not in front of the presenting part with the membranes intact', 'Besides the presenting part with membrane raptured', 'C', 'Occult cord prolapse is when the cord lies alongside (beside) but not in front of the presenting part, and the membranes may still be intact (Myles Textbook for Midwives). A cord in front of the presenting part with ruptured membranes (option B) is overt cord prolapse, and a cord in front with intact membranes (option A) is cord presentation.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Maternal mortality ratio is defined as:', 'Number of maternal death per 100,000 live births', 'Direct and indirect maternal death per 10,000 live births', 'Maternal death between 14 – 44 years per 10,000 live births', 'Maternal deaths between 14 – 55 years per 1,000 live births', 'A', 'The maternal mortality ratio is defined as the number of maternal deaths per 100,000 live births in a given period (WHO; Kenya MOH reproductive health guidelines). The other options use incorrect denominators (10,000 or 1,000) and irrelevant age brackets, so they are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A midwife performs a lateral palpation to the abdomen of the pregnant woman with the aim of:', 'Detecting fetal lie', 'Detecting fetal position', 'Detecting fetal descent', 'Detecting engagement', 'B', 'Lateral palpation feels the sides of the uterus to locate the fetal back and limbs, thereby determining fetal position (Myles Textbook for Midwives). Fundal palpation and pelvic (Pawlik) palpation determine lie, presentation, descent and engagement, so options A, C and D are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Wernickle’s encephalopathy and Mallory – Weiss syndrome are among the complication of:', 'Placenta pravia', 'Hypertensive disorders', 'Vitamin B deficiency', 'Hyperemesis gravidarum', 'D', 'Severe hyperemesis gravidarum causes thiamine (vitamin B1) depletion leading to Wernicke''s encephalopathy and forceful vomiting causing Mallory-Weiss oesophageal tears (Myles Textbook for Midwives). Although a B-vitamin deficiency underlies Wernicke''s, the syndrome pairing with Mallory-Weiss points specifically to hyperemesis gravidarum as the overarching complication, so D is the best answer over C.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following mother need Anti-D to prevent isoimmunization', 'RH positive mother who delivers a RH negative fetus', 'RH negative mother who delivered a RH Positive fetus', 'RH positive mother who delivered RH Positive fetus', 'RH Negative mother who deliver a RH Negative fetus', 'B', 'Anti-D immunoglobulin is given to a Rhesus-negative mother who has delivered a Rhesus-positive baby to prevent isoimmunization and formation of anti-D antibodies affecting future pregnancies (Kenya MOH maternal guidelines; Myles Textbook for Midwives). The other combinations pose no sensitisation risk (Rh-negative fetus) or are biologically impossible (Rh-positive mother sensitised against D).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Deep transverse arrest is:', 'Where flexion is always well maintained', 'Caused by strong uterine contraction throughout labour', 'Caused by sacrum that is well curved', 'Where the level of the occiput and the sinciput is same', 'D', 'Deep transverse arrest arises from deflexion in an occipito-posterior position so the occiput and sinciput lie at the same level, arresting transversely at the pelvic outlet (Myles Textbook for Midwives). Well-maintained flexion (A) would prevent it, and a well-curved sacrum favours rotation rather than arrest, so the other options are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is an indication for forceps delivery:', 'Cephalopelvic disproportion', 'Occipital posterior position', 'Breech presentation', 'Placenta abruption', 'B', 'Persistent occipito-posterior position causing delay in the second stage is an indication for forceps (rotational/traction) delivery (Myles Textbook for Midwives). Cephalopelvic disproportion, breech and placental abruption are contraindications to forceps and are managed by caesarean section, so A, C and D are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Delivery of breech with an extended head is accomplished through:', 'Burns Marshall Maneuver', 'Lovset Maneuver', 'Maureceous smwllie maneuver', 'Mc Robert Maneuver', 'A', 'The Burns Marshall manoeuvre delivers the after-coming (extended) head in breech by grasping the ankles and sweeping the body over the maternal abdomen (Myles Textbook for Midwives). Lovset delivers extended arms and McRoberts is for shoulder dystocia, so B and D are wrong; the Mauriceau-Smellie-Veit (garbled C) is an alternative but A is a correct listed option.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term persistent occipito-posterior position indicates that the occiput.', 'Fails to rotate forward', 'Escape under the symphysis pubis', 'Rotates forward always', 'Reaches the pelvic floor first', 'A', 'In persistent occipito-posterior position the occiput fails to rotate forward and remains directed towards the sacrum, so delivery may occur face-to-pubis (Myles Textbook for Midwives). Options describing forward rotation or reaching the pelvic floor first describe the normal well-flexed vertex, so they are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a characteristics of fetal post maturity syndrome:', 'Closed eye usually alerts', 'Long, frails finger nails', 'Wrinkled, peeling skin', 'Excess vernix caseosa', 'C', 'Post-maturity (dysmaturity) syndrome features dry, wrinkled, peeling/cracked skin with absent vernix, long nails and an alert ''old-man'' look (Basic Paediatric Protocols, Kenya; Myles Textbook for Midwives). Excess vernix (D) is a feature of prematurity, and long frail nails alone (B) is less specific, so C is the best answer.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Some of neonatal complications of eclampsia are:', 'Cerebral hemorrhage and pneumonia', 'Severe asphyxia and prematurity', 'Fracture and soft tissue fractures', 'Respiratory distress and hypoglycemia', 'B', 'Eclampsia impairs uteroplacental perfusion and commonly forces preterm delivery, so the neonate typically suffers severe birth asphyxia and complications of prematurity (Myles Textbook for Midwives; Kenya MOH guidelines). Cerebral haemorrhage/pneumonia and bony fractures are maternal or birth-trauma issues rather than the primary neonatal effects of eclampsia.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The immediate action the midwife should take after the delivery of the fetal head in second stage of labor is:', 'Clear the airway', 'Check the cord round the neck', 'Wait for sign of restitution', 'Hold the head by the bi-parietals', 'B', 'Immediately after the head is born the midwife runs a finger around the neck to check for a nuchal cord before delivering the shoulders, so it can be loosened or clamped and cut if tight (Myles Textbook for Midwives). Clearing the airway and awaiting restitution follow, but feeling for the cord is the immediate next action.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following an amniocentesis, the nurse should instruct a client to immediately report which of the following symptoms.', 'Flu-like symptoms', 'Inability to sleep', 'A decrease in uterine contractions', 'An increase in uterine contraction', 'D', 'After amniocentesis the client must immediately report increased uterine contractions (plus fluid leakage, bleeding or fever), which may signal preterm labour or complications (maternal-newborn nursing; Brunner & Suddarth). A decrease in contractions, insomnia and flu-like symptoms are not the urgent warning signs, so the other options are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The recommended fluid to a mother in labour with signs of fetal distress is:', 'Normal saline', 'Dextrose', 'Hartmans', 'Ringers lactate', 'A', 'In labour with fetal distress the recommended intravenous fluid is normal saline for maternal hydration and improved placental perfusion, while dextrose is avoided because it can precipitate neonatal hypoglycaemia (Kenya MOH maternal care guidelines). Ringer''s lactate/Hartmann''s are acceptable crystalloids but normal saline is the classically endorsed answer here.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The immediate action to take when you diagnose cord prolapse on vaginal examination is to:', 'Check pulsation', 'Position the mother in knee-chest', 'Take patient to theatre', 'Call for help', 'A', 'On diagnosing cord prolapse per vaginam the immediate action is to feel the cord for pulsation to establish fetal viability, which then directs urgent management (relieve cord pressure, knee-chest position, prepare for delivery) (Myles Textbook for Midwives; Kenya MOH guidelines). Positioning, calling for help and moving to theatre follow the initial assessment.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main causative organism for congenital abnormalities include:', 'Syphilis, toxoplasmosis, rubella', 'Herpes simplex, microbacteria tuberculosis, cytomegalovirus', 'Malaria, herpes simplex, syphilis.', 'Toxoplasmosis, rubella, HIV', 'A', 'Syphilis, toxoplasmosis and rubella are classic TORCH congenital infections causing congenital abnormalities (Myles Textbook for Midwives; Basic Paediatric Protocols, Kenya). Options containing Mycobacterium tuberculosis and malaria are not part of the TORCH teratogenic group, so B, C and D are less correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The objective of the first examination of the newborn include:', 'Assess injury, assess maturity, and assess growth', 'Assess congenital abnormality, assess injury and assess for breastfeeding', 'Assess maturity, assess condition and congenital abnormalities', 'Assess injury, assess maturity, and assess congenital abnormalities', 'D', 'The first newborn examination aims to detect birth injury, assess maturity/gestation and screen for congenital abnormalities (along with general condition) (Myles Textbook for Midwives; Basic Paediatric Protocols, Kenya). Breastfeeding assessment and growth are not primary objectives of this first check, so options A, B and C are incomplete or wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pregnant woman report to the clinic on 7th March 2011 and gives history of FLMP on 15th June 2010. What is her maturity by date to the pregnancy.m', '37 weeks 6 days', '38 weeks 6 days', '39 weeks 1 day', '42 weeks 1 day', 'A', 'Counting from LMP 15 June 2010 to 7 March 2011 gives 265 days, which is exactly 37 weeks and 6 days (verified by date calculation). The maturity by dates is therefore 37 weeks 6 days, making A correct and the other options arithmetically wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('At a glance, a postdate baby .on examination will have the following features.', 'Old man’s look, weak cry and plenty of vernix', 'Dry skin, jaundice and thin extremities', 'Long nails, hard skull, old man’s look', 'Peeling skin, long nails and meconium stain', 'D', 'A postdate (postmature) baby classically shows dry peeling/cracked skin, long finger nails and meconium staining, with an old-man look and absent vernix (Basic Paediatric Protocols, Kenya; Myles Textbook for Midwives). Option A wrongly includes ''plenty of vernix'' (a preterm feature), so D is the correct combination.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A woman is one hour postpartum following vaginal delivery. Which of the following action would you take first?', 'Initiate perineal pad count', 'Assess the location of the bladder', 'Obtain vital signs', 'Massage uterine fundus', 'D', 'One hour postpartum the priority is to ensure the uterus is well contracted, as a boggy fundus (uterine atony) is the leading cause of early postpartum haemorrhage, so massaging/checking the fundus is done first (Myles Textbook for Midwives; Kenya MOH guidelines). Pad count, bladder assessment and vital signs follow after securing uterine tone.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of an amniotic membrane include:', 'Peel up to the edge of the placenta, transparent, hard to tear', 'Transparent, peel up to the insertion of the cord, hard to tear', 'Opaque, peels up to the edge of the placenta, hard to tear', 'Hard to tear, peel up to insertion of the cord opaque.', 'B', 'The amnion is the smooth, tough, transparent inner membrane that peels off the chorion up to the insertion of the umbilical cord and is difficult to tear (Myles Textbook for Midwives). The chorion is opaque and friable and peels only to the placental edge, so the opaque options and the one stopping at the placental edge are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The role of midwife during 4th focused antenatal visit at 36weeks include;', 'Assess for anaemia ,pelvic adequacy ,give iron and folate', 'Give iron and folate ,give tetanus toxoid ,assess pelvic adequacy', 'Give antimalarial,assess for anaemia ,give tetanus toxoid', 'Check for fetal presentation ,give antimalarial,assess for anaemia', 'D', 'At the 4th focused antenatal visit near 36 weeks the midwife checks fetal presentation (to detect malpresentation before term), continues IPTp antimalarial and assesses for anaemia (Kenya MOH Focused Antenatal Care guidelines). Pelvic adequacy assessment and tetanus toxoid are not the focus of this late visit, so options citing them are less correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The immediate effects of hyperemesis gravidarum on the mother include;', 'Electrolyte imbalance ,anaemia ,ketosis', 'Dehydration ,ketosis ,anaemia', 'Anaemia ,electrolyte imbalance ,ketosis', 'Dehydration ,electrolyte imbalance, ketosis', 'D', 'Hyperemesis gravidarum causes intractable vomiting leading to the immediate effects of dehydration, electrolyte imbalance (hypokalaemia/hyponatraemia) and ketosis from fat catabolism (Myles Textbook for Midwives). Anaemia is a later secondary consequence, not an immediate effect, so options A, B and C that include anaemia are less correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The organism that cross the placenta barrier and affect the fetus include;', 'Chlamydia trachomatis ,gonorrhea', 'Treponema palllidum ,chlamydia trachomatis', 'Tubercle bacillus ,Neisseria gonorrhea', 'Treponema pallidum ,tubercle bacillus', 'D', 'Treponema pallidum readily crosses the placenta to cause congenital syphilis, and Mycobacterium tuberculosis can cause congenital TB by haematogenous placental spread (Myles Textbook for Midwives; Kenya MOH guidelines). Chlamydia and gonorrhoea are transmitted mainly at delivery through the birth canal, not transplacentally, so the other options are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A mother with cardiac disease grade III [three] will present with;', 'No symptoms during ordinary activity', 'Symptoms during mild physical activity', 'Symptoms at rest', 'Symmptoms during ordinary physical activity', 'B', 'By the NYHA classification used in Myles Textbook for Midwives, Class III cardiac disease means marked limitation with symptoms on less-than-ordinary (mild) physical activity, though comfortable at rest. Symptoms at rest is Class IV, symptoms on ordinary activity is Class II, and no symptoms on ordinary activity is Class I, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The mechanism of normal labor in sequence include;', 'Descent ,Internal rotation of the head ,extension of the head ,restitution ,crowning ,extension of the head', 'Descent ,flexion of the head ,internal rotation of the head ,crowning ,extension of the head ,restitution', 'Flexion of the head , internal rotation of the head ,extension of the head ,restitution ,crowning ,extension of the head', 'Internal rotation of the head , flexion of the head ,crowning ,external rotation of the head, descent, extension of the head', 'B', 'The mechanism of normal labour in a vertex presentation is descent, flexion, internal rotation of the head, crowning, extension (birth of the head), then restitution and external rotation (Myles Textbook for Midwives). Only option B follows this correct physiological sequence; the others start with rotation or place steps out of order.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The fetal indication for induction of labour include ;', 'Intrauterine fetal death, prolonged labour', 'Intrauterine growth retardation , intrauterine fetal death', 'Unstable lie prolonged pregnancy', 'Unstable lie ,intrauterine growth retardation', 'B', 'Fetal indications for induction of labour include intrauterine growth restriction and intrauterine fetal death (Myles Textbook for Midwives). Prolonged labour is not an induction indication, and unstable lie is in fact a contraindication, so options A, C and D are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During labour the midwife discourages the mother to lie on supine position to prevent ;', 'Obstructed labour and fetal distress', 'Maternal hypotension and fetal distress', 'Maternal hypotension and obstructed labour', 'Maternal hypertension and fetal distress', 'B', 'The supine position causes aortocaval compression by the gravid uterus, producing supine hypotensive syndrome and reduced uteroplacental perfusion leading to fetal distress (Myles Textbook for Midwives). The midwife encourages a left lateral tilt to prevent this; obstructed labour and hypertension are not the mechanisms, so the other options are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The possible indications for elective caesarean section include ;', 'Cephalo-pelvic disproportion ,major degree of placenta praevia ,severe pre- eclamsia', 'Diabetes mellitus ,major degree of placenta praevia ,severe pre –eclampsia', 'Severe pre-eclampsia ,breech presentation ,diabetes mellitus', 'Breech presentation ,cephalo-pelvic disproportion ,severe pre-eclampsia', 'A', 'Indications for elective caesarean section include cephalo-pelvic disproportion, major-degree placenta praevia and severe pre-eclampsia (Myles Textbook for Midwives). Diabetes mellitus and breech presentation are relative indications rather than absolute, so option A which lists three strong indications together is the best answer.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The maneuver used by midwife to deliver the after coming head in breech presentation is reffered to;', 'Mauriceau-smellie-vet', 'Lovest’s', 'Pawlik’s', 'Burn marshall', 'A', 'The Mauriceau-Smellie-Veit manoeuvre is the classic named technique for delivering the after-coming head of the breech by promoting flexion (Myles Textbook for Midwives). Lovset delivers extended arms and Pawlik is a palpation grip, so those are wrong; Burns Marshall (D) is an alternative but the named after-coming-head manoeuvre is Mauriceau-Smellie-Veit.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The reflex elicited when the midwife allows the head of the baby to drop by 45 degrees is ;', 'Stepping', 'Grasping', 'Moro', 'Rooting', 'C', 'The Moro (startle) reflex is elicited by allowing the baby''s head to drop back suddenly (about 30-45 degrees), producing symmetrical abduction then adduction of the arms (Myles Textbook for Midwives; standard neonatal assessment). Stepping, grasping and rooting are elicited by different stimuli, so they are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nerve trauma in which the upper arm of the newborn has normal movement but the lower arm, wrist and hand is affected is', 'Klumpke’s palsy', 'Torticollis', 'Total brachial plexus palsy', 'Erb’s palsy', 'A', 'Klumpke''s palsy involves the lower brachial plexus (C8-T1), so the upper arm moves normally but the forearm, wrist and hand are affected (claw hand) (Myles Textbook for Midwives). Erb''s palsy affects the upper plexus (C5-C6) giving the ''waiter''s tip'' upper-arm deformity, so D is wrong; torticollis is a sternomastoid injury, not a nerve palsy.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term battledore insertion is used when the cord is inserted ;', 'At the edge of the placenta', 'Into the membranes of the placenta', 'At the lateral side of the placenta', 'At the middle of the placenta', 'A', 'Battledore insertion is when the umbilical cord is inserted at the margin/edge of the placenta, resembling a battledore bat (Myles Textbook for Midwives). Insertion into the membranes is velamentous insertion, and central insertion is normal, so options B, C and D are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Intrauterine contraceptive device insertion can be carried out as early as;', 'After third stage of labour', '48 hours post delivery', 'Six weeks post partum', 'Six months post partum', 'A', 'A postpartum IUCD can be inserted immediately after delivery of the placenta (post-placental, within 10 minutes of the third stage), which is the earliest recommended time (Kenya National Family Planning Guidelines; WHO). If this window is missed within 48 hours, insertion is deferred to 4-6 weeks, so ''after third stage of labour'' is the earliest.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The presence of surfactant factor in the lungs of a newborn helps to;', 'Provide stimulations to the respiratory centre', 'Reduces alveolar surface tension and allow expansion of the lungs', 'Prevent transcient tachypneoa of the newborn', 'Increase alveolar surface tension and prevent neonatal atelectasis', 'B', 'Surfactant lowers alveolar surface tension, preventing alveolar collapse and allowing the lungs to expand and remain inflated (physiology in Myles Textbook for Midwives). Its deficiency causes respiratory distress syndrome and atelectasis, so the option stating it increases surface tension is wrong, as are the respiratory-centre and transient-tachypnoea options.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The fluid selection regimen for women with shock in labour is ;', 'Colloids 2ltrs, then crystalloids more than 2ltrs', 'Crystalloids 2ltrs ,then colloids 2ltrs', 'Crystalloids not more than 2ltrs ,then colloids', 'Colloids not more than 2ltrs ,then crystalloids', 'C', 'Initial fluid resuscitation in obstetric shock uses crystalloids first (up to about 2 litres), then colloids if further volume is required (Myles Textbook for Midwives; standard shock management). Colloids are not given as the first-line unlimited fluid, so the options leading with colloids or giving crystalloids beyond 2 litres before colloids are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The stoma cells that control the excessive invasion of the placenta are found in the', 'Muscle layer', 'Ectoderm', 'Trophoblastic', 'Functional layer', 'C', 'Trophoblastic cells (cytotrophoblast with the Nitabuch fibrinoid layer) regulate and limit the depth of placental invasion into the decidua (Myles Textbook for Midwives). Failure of this control leads to abnormally adherent/invasive placenta (accreta/increta/percreta); the muscle layer, ectoderm and functional (decidual) layer do not perform this regulatory role.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During fetal development, brown fat begins to form at;', '12 weeks', '16 weeks', '20 weeks', '24 weeks', 'B', 'Brown adipose tissue begins to be laid down in the fetus from about 16-28 weeks gestation, stored around the neck, scapulae and mediastinum for non-shivering thermogenesis (Myles Textbook for Midwives). Among the options, 16 weeks represents the earliest point at which it begins to form, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The hormone responsible for secretion of mucus by the endocervical cell during pregnancy is;', 'Progesterone', 'Oestrogen', 'Prostaglandin', 'Human chorionic gonadotrophin', 'A', 'Progesterone stimulates the endocervical glands to secrete thick tenacious mucus forming the operculum (mucus plug) that seals the cervix during pregnancy (Myles Textbook for Midwives). Oestrogen promotes reproductive tract growth but the cervical mucus plug is progesterone-mediated, so B, C and D are wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A rhesus positive foetus is affected by a rhesus negative mother due to;', 'Antibodies of the foetus crosses the placenta barrier to the mother’s circulation', 'Antibodies of the mother crosses the placenta into the foetal circulation', 'The foetal red blood cells enters the mother’s circulation', 'The maternal red blood cells enters the foetal circulation', 'B', 'In Rhesus incompatibility a sensitised Rh-negative mother produces anti-D IgG antibodies that cross the placenta into the Rh-positive fetal circulation, haemolysing fetal red cells (haemolytic disease of the newborn) (Myles Textbook for Midwives). Option C (fetal red cells entering maternal circulation) describes the sensitising event, not the mechanism of fetal harm, so it is wrong.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Retention of a portion of the placenta in the uterus after third stage of labour will;', 'Prevent the uterus from contracting effectively', 'Cause the blood vessels in the placental bed to dilate', 'Make the uterus to become hard as a tennis ball', 'Prevent the blood vessels in the placental bed to contract', 'A', 'Per Myles Textbook for Midwives, retained placental fragments mechanically prevent the uterus from contracting and retracting effectively, keeping the placental-bed sinuses open and producing uterine atony with postpartum haemorrhage. A hard, tennis-ball uterus (C) describes a well-contracted uterus, which cannot occur while fragments remain; dilating (B) or failing-to-contract vessels (D) do not describe the primary mechanism as accurately as the loss of effective uterine contraction.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The midwife will encourage the mother to empty the urinary bladder during first stage of labour mainly to ;', 'Minimize infection', 'Avoid bladder rupture during the third stage of labour', 'Prevent contamination during second stage of labour', 'Avoid complications during second stage and third stage of labour', 'D', 'Per Myles Textbook for Midwives, a full bladder in labour obstructs descent of the presenting part in the second stage and impairs uterine contraction and placental separation in the third stage, and is at risk of trauma. Emptying it therefore prevents complications in BOTH the second and third stages, making D the most complete answer. B (bladder rupture only) and C (contamination only) each capture a single narrower risk.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ductus arteriosus is a bypass in a baby’s circulation from;', 'Umbilical vein to the inferior vena cava', 'Pulmonary artery to the aorta', 'Left atria and right atria', 'Internal iliac artery to umbilical artery', 'B', 'Per Myles Textbook for Midwives fetal circulation, the ductus arteriosus is the shunt connecting the pulmonary artery to the aorta, diverting blood away from the non-aerated fetal lungs. Umbilical vein to inferior vena cava (A) is the ductus venosus, and the interatrial shunt (C) is the foramen ovale; D describes normal internal iliac/umbilical vessels.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A reduction in urinary output in prolonged labour may be associated with;', 'Antidiuretic hormone effect of oxytocin, pyrexia , dehydration', 'Dehydration ,pyrexia ,dirrhoea', 'Antidiuretic effect of ,pyrexia ,vomiting', 'Dirrhoea, pyrexia ,vomiting', 'A', 'Per Myles Textbook for Midwives, reduced urinary output in prolonged labour is caused by the antidiuretic effect of oxytocin, pyrexia and dehydration (with pressure on the ureters). Option A correctly groups these three recognised causes; the other options substitute diarrhoea or vomiting, which are not the established causes of the oliguria of prolonged labour.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In a normal delivery with a well flexed head the presenting diameters are;', 'Mentovertical 13.5cm, bitemporal 8.2cm', 'Bitemporal 8.2cm,and sub-mentobregmatic 9.5cm', 'Bipariental 9.5cm and sub-occipitobregmatic 9.5cm', 'Bitemporal 9.5cm and occipitofrontal11.5cm', 'C', 'Per Myles Textbook for Midwives, in a well-flexed vertex the presenting anteroposterior diameter is the suboccipitobregmatic (9.5 cm) and the presenting transverse diameter is the biparietal (9.5 cm). The mentovertical (13.5 cm, option A) presents in a brow and the occipitofrontal (11.5 cm, option D) in a deflexed vertex, so C describes the well-flexed head.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The maternal characteristics a midwife will use to diagnose late obstructed labor through a partograph include;', 'Slow cervical dilatation ,pyrexia ,excessive moulding', 'Rapid pulse rate ,pyrexia ,excessive moulding', 'Slow cervical dilatation ,excessive moulding ,oliguria', 'Rapid pulse rate ,pyrexia ,oliguria', 'D', 'Per Myles Textbook for Midwives, the MATERNAL characteristics of obstructed labour recorded on the partograph are a rising (rapid) pulse, pyrexia and oliguria/concentrated urine reflecting exhaustion and dehydration. Slow cervical dilatation is a progress finding and excessive moulding is a fetal finding, so options containing them (A, B, C) mix in non-maternal signs; D lists only maternal signs.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Maternal causes of shoulder presentation include;', 'Lax uterine muscles ,uterine abnormality', 'Contracted pelvis ,preterm pregnancy', 'Lax uterine muscles ,multiple pregnancy', 'Uterine abnormality, multiple pregnancy', 'A', 'Per Myles Textbook for Midwives, maternal causes of shoulder/transverse-lie presentation include lax uterine and abdominal muscles (grand multiparity), uterine abnormality (e.g. bicornuate uterus), contracted pelvis and placenta praevia. Option A pairs two maternal causes; B and C are diluted by preterm pregnancy and multiple pregnancy, which are fetal/other causes rather than maternal.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('To prevent neural tube defect the midwife advises a woman planning to conceive to take:', 'Vitamin B12', 'Vitamin A', 'Ferrous sulphate', 'Folic acid', 'D', 'Per Kenya MOH/WHO antenatal and preconception guidelines, women planning to conceive should take periconceptional folic acid (0.4 mg daily) to prevent fetal neural tube defects such as spina bifida. Vitamin B12 and ferrous sulphate (C) address anaemia, and vitamin A is not used for NTD prevention and is teratogenic in excess, so D is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The milk secreting cells in the breast are referred to as:', 'Acini cells', 'Myoepithelial cells', 'Alveolar cells', 'Montogomery tubercle', 'A', 'Per Myles Textbook for Midwives, the milk-secreting cells lining the alveoli of the breast are the acini (secretory) cells, making A the intended answer. Myoepithelial cells (B) contract to eject milk and Montgomery''s tubercles (D) are areolar sebaceous glands; note ''alveolar cells'' (C) is essentially a synonym for acini cells, but the classic textbook term used here is acini.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The midwife would formulate the following nursing diagnosis for a mother who develops hypovolemic shock after uterine rupture :', 'Fluid volume deficit related to intra uterine bleeding evidenced by vaginal bleeding', 'Risk of fluid volume deficit related to uterine rupture', 'Impaired tissue perfusion as evidenced by blood loss', 'Ineffective gas exchange related to uterine rupture', 'A', 'Per Kozier & Erb''s Fundamentals of Nursing, an ACTUAL problem that has already developed (hypovolaemic shock after uterine rupture) is stated as an actual diagnosis with aetiology and defining characteristics: ''Fluid volume deficit related to intrauterine bleeding as evidenced by vaginal bleeding''. B is a ''risk'' diagnosis, inappropriate once shock is established; C omits a clear related-to aetiology and D (gas exchange) is not the primary problem.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Maternal distress can be diagnosed from the partograph through:', 'Cervical dilatation ,urine testing ,blood pressure', 'Urine testing ,blood pressure ,maternal pulse', 'Cervical dilatation ,urine testing ,amniotic fluid', 'Cervical dilatation ,uterine contraction ,blood pressure', 'B', 'Per Myles Textbook for Midwives, maternal condition/distress on the partograph is assessed through maternal pulse, blood pressure, temperature and urine (volume, protein, ketones). Cervical dilatation, uterine contractions and amniotic fluid record labour progress and fetal condition, so options A, C and D mix in progress/fetal parameters; B lists the maternal parameters.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Maternal minor complications which may occur during puerperium include:', 'Cracked nipples , breast engorgement ,bleeding', 'Depression , cracked nipples ,sore perineum', 'Sore perineum, engorgement, cracked nipples', 'Depression , engorgement ,bleeding', 'C', 'Per Myles Textbook for Midwives, minor complications of the puerperium include a sore perineum, breast engorgement and cracked nipples. Bleeding (secondary PPH) and depression are MAJOR complications, so every option containing them (A, B, D) is excluded, leaving C.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Definitive indications for elective caesarean section include:', 'Cephalopelvic disproportion ,major degree of placenta preavia', 'Cephalopelvic disproportion , breech presentation', 'High order multiple pregnancies ,breech presentation', 'Major degree of placenta preavia , diabetes mellitus', 'A', 'Per Myles Textbook for Midwives, definitive/absolute indications for elective caesarean section include cephalopelvic disproportion and major-degree placenta praevia (placenta covering the os). Breech presentation and diabetes mellitus are relative indications, so options B, C and D dilute the answer; A pairs the two absolute indications.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The Expected date of delivery of a human pregnancy can be calculated:', 'From a change in the patient''s weight.', 'As 10 lunar months after the time of ovulation.', 'As 40 weeks after last menstrual period.', 'As 280 days from the last full moon.', 'C', 'By Naegele''s rule the expected date of delivery is 40 weeks (280 days) counted from the first day of the last menstrual period. ''Ten lunar months'' is measured from the LMP not from ovulation, and weight change, ''last full moon'' and 36 weeks are all incorrect. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The last menstrual period was June 30. the expected date of delivery (EDD) is approximately:', 'March 23.', 'April 7.', 'March 28.', 'April 23.', 'B', 'Naegele''s rule: LMP + 7 days − 3 months (+1 year). June 30 + 7 days = July 7; subtracting 3 months gives April 7, so the EDD is April 7. The March options and April 23 do not follow the calculation. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The greatest diameter of the fetal head is:', 'Occipitofrontal.', 'Occipitomental.', 'D. Bitemporal.', 'Biparietal.', 'B', 'The occipitomental diameter (~13.5 cm), which presents in a brow presentation, is the largest anteroposterior diameter of the fetal skull. Occipitofrontal is ~11.5 cm, biparietal ~9.5 cm and bitemporal ~8.2 cm — all smaller. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main blood supply of the vulva is:', 'Inferior hemorrhoidal artery.', 'Pudendal artery.', 'Ilioinguinal artery.', 'Femoral artery.', 'B', 'The vulva is supplied mainly by the internal and external pudendal arteries, the internal pudendal (a branch of the internal iliac) being the principal supply. The inferior haemorrhoidal, ilioinguinal, femoral and hypogastric options are not the main vulval supply. Per Myles/Gray''s anatomy of the female genital tract.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are typical in the female bony pelvis EXCEPT:', 'Has a transverse diameter of the inlet greater than the antero-posterior diameter.', 'Has an obstetric conjugate of 11-12 cm.', 'Is funnel shaped.', 'Has an obtuse greater sciatic notch.', 'C', 'The typical female (gynaecoid) pelvis is rounded/oval, NOT funnel-shaped; a funnel shape characterises the android (male-type) pelvis and predisposes to obstructed labour, so it is the EXCEPT answer. A transverse inlet greater than AP, obstetric conjugate of 11–12 cm, obtuse sciatic notch and pubic angle >90° are all normal female features. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The ovarian artery is a branch of:', 'Common iliac artery.', 'Internal iliac artery.', 'Aorta.', 'Hypogastric artery.', 'C', 'The ovarian arteries arise directly from the abdominal aorta just below the renal arteries, unlike the uterine artery which branches from the internal iliac. The common iliac, internal iliac, hypogastric and sacral options are therefore incorrect. Per standard anatomy of the female genital tract (Myles/Gray''s).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The normal lining of the fallopian tube is:', 'Squamous epithelium.', 'Transitional epithelium.', 'Cuboidal epithelium.', 'Columnar epithelium with cilia.', 'D', 'The fallopian tube is lined by ciliated columnar epithelium whose cilia, together with peristalsis, propel the ovum toward the uterus. Squamous, transitional, cuboidal and fibrous tissue do not line the tube. Per histology/anatomy in Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The cilia of the fallopian tube has the following function:', 'Remove the zona pellucida which surrounds the ovum.', 'Transport the ovum towards the uterus.', 'Enhance the rapid division of the zygote.', 'Transport the ovum towards the peritoneal cavity. LABOR AND FETAL SURVEILLANCE AND MECHANISM OF LABOR:', 'B', 'The cilia of the fallopian tube beat toward the uterus, transporting the ovum/zygote from the ampulla toward the uterine cavity for implantation. They do not remove the zona pellucida, drive cell division, or carry the ovum toward the peritoneal cavity. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Stages of labor', 'The first stage commences at the time of membrane rupture', 'The cervix dilates at consistent rate of 3 cm per hour in the first stage', 'The third stage end with the delivery of the placenta and membranes', 'Forceps or ventose may be useful in slow progress of the late 1st stage', 'C', 'The third stage of labour extends from delivery of the baby to complete expulsion of the placenta and membranes, making C the true statement. The first stage begins with regular painful contractions and progressive dilatation (not membrane rupture), dilatation is not a fixed 3 cm/hour, and Syntometrine is used for active management/prevention of PPH, not treatment of secondary PPH. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('All the following characteristics are applied to a pelvis favorable to vaginal delivery EXCEPT:', 'Sacral promontory can not be felt.', 'Obstetric conjugate is less than 10 cm.', 'Ischial spines are not prominent.', 'Subpubic arch accepts 2 fingers.', 'B', 'A favourable pelvis has an obstetric conjugate of about 11–12 cm; an obstetric conjugate under 10 cm indicates inlet contraction and is UNfavourable, hence the EXCEPT answer. A non-palpable sacral promontory, non-prominent ischial spines, a sub-pubic arch admitting 2 fingers and an intertuberous diameter admitting 4 knuckles are all favourable signs. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the fetus:', 'The coronal suture lies between the two parietal bones.', 'The umbilical artery normally contains one artery and two veins.', 'Fetal lie describes the long axis of the fetus to the long axis of the mother.', 'Entanglement of the umbilical cord is common in diamniotic twins.', 'C', 'Fetal lie describes the relationship of the long axis of the fetus to the long axis of the mother/uterus, so C is correct. The sagittal (not coronal) suture lies between the parietal bones, the umbilical cord normally has two arteries and one vein, and the anterior fontanelle is open at birth. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following terms best describes the pelvic type of small posterior saggital diameter, convergent sidewalls, prominent ischial spines, and narrow pubic arch?', 'Android.', 'Gynecoid.', 'Anthropoid.', 'Platypelloid.', 'A', 'A small posterior sagittal diameter, convergent (funnel) side walls, prominent ischial spines and a narrow pubic arch characterise the android pelvis, which predisposes to obstructed labour. The gynaecoid pelvis has a wide arch and non-prominent spines; anthropoid and platypelloid have different shapes. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pelvic inlet is felt to be contracted if :', 'The anterio-posterior diameter is only 12 cm.', 'The transverse diameter is only 10 cm .', 'Platypelloid pelvis.', 'The mother is short.', 'B', 'The pelvic inlet is contracted when its diameters fall below normal; a transverse diameter of only 10 cm (normal ~13 cm) indicates inlet contraction. An AP diameter of 12 cm is normal, and short stature or a previous C-section alone do not define inlet contraction. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During clinical pelvimerty, which of the following is routinely measured:', 'Bi-ischeal diameter.', 'Transverse diameter of the inlet.', 'Shape of the pubic arch.', 'Flare of the iliac crest.', 'A', 'On clinical (digital) pelvimetry the outlet''s bi-ischial (intertuberous) diameter is routinely assessed, along with the diagonal conjugate, sub-pubic arch and ischial spines. The transverse diameter of the inlet, iliac crest flare and levator elasticity cannot be measured on routine clinical examination. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During clinical pelvimetry, which of the following is routinely measured:', 'True conjugate.', 'Transverse diameter of the inlet.', 'Shape of the pubic arch.', 'Flare of the iliac crest.', 'A', 'Clinical pelvimetry estimates the true (obstetric) conjugate by measuring the diagonal conjugate on vaginal examination and subtracting ~1.5–2 cm. The transverse diameter of the inlet, flare of the iliac crest and elasticity of the levator muscles are not routinely measured clinically. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During the delivery, the fetal head follow the pelvic axis. The axis is best described as:', 'A straight line.', 'A curved line, 1ST directed anteriorly then caudal.', 'A curved line, 1ST directed posteriorly then caudal.', 'A curved line, 1ST directed posteriorly then cephalic.', 'C', 'The fetal head follows the curved pelvic axis (curve of Carus), directed first downward and backward (posteriorly) then curving forward and downward (caudal) toward the outlet. A straight line and the anteriorly/cephalic-directed options do not match the curve of Carus. Per Myles Textbook for Midwives mechanism of labour.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A woman who has never given birth to a viable baby is referred to as a', 'Primigravida', 'Primipara', 'Nullipara', 'Multipara', 'C', 'A nullipara is a woman who has never given birth to a viable (potentially live) infant, per Myles Textbook for Midwives terminology. Primigravida (A) means pregnant for the first time, primipara (B) has delivered one viable baby, and multipara (D) has delivered several; only nullipara denotes never having borne a viable child.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The hormone responsible for milk ejection is', 'Prolactin', 'Progesterone', 'Oestrogen', 'Oxytocin', 'D', 'Oxytocin causes contraction of the myoepithelial cells surrounding the alveoli, ejecting milk in the let-down reflex, per Myles Textbook for Midwives / physiology of lactation. Prolactin (A) governs milk production not ejection, and progesterone (B) and oestrogen (C) inhibit lactation antenatally; oxytocin is responsible for ejection.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Warmth and pinkish appearance of the vagina results from', 'Increased acidity', 'Increased vascularity', 'Decreased exudates', 'Decreased elasticity', 'B', 'The warm, bluish-pink appearance of the vagina and cervix in pregnancy (Chadwick''s/Jacquemier''s sign) results from increased vascularity and blood flow driven by raised oestrogen, per Myles Textbook for Midwives. Increased acidity (A), decreased exudates (C) and decreased elasticity (D) do not produce this colour change; increased vascularity does.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During pelvic assessment, evaluation of the outlet is based on', 'State of intertuberous diameter and pubic arch.', 'State of ischial spines and sciatic notches.', 'State of bispinous and intertuberous diameters.', 'State of coccyx and inferior pubic rami.', 'A', 'The pelvic outlet is assessed clinically by the intertuberous (bituberous) diameter and the width of the pubic arch/subpubic angle, which determine outlet adequacy, per Myles Textbook for Midwives. Ischial spines and sciatic notches (B) and the bispinous diameter (C) assess the mid-pelvis, so the intertuberous diameter and pubic arch are the outlet measures.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most appropriate health message to share with a primigravida at 36 weeks is on', 'Highly nutritious diet', 'Physiology of labour', 'Importance of rest', 'Signs of true labour', 'D', 'At 36 weeks a primigravida is approaching term, so the priority health message is recognising the signs of true labour (regular painful contractions, show, ruptured membranes) so she knows when to seek care, per MOH Kenya focused ANC and Myles Textbook for Midwives. Diet (A), physiology of labour (B) and rest (C) are useful but less critical than knowing when labour has started.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following observations is charted ½ hourly on the partograph?', 'Maternal blood pressure', 'Maternal respirations', 'Descent of the head', 'Uterine contractions', 'D', 'On the partograph uterine contractions are assessed and charted every half hour (together with FHR and maternal pulse), per WHO/MOH Kenya partograph guidelines. Maternal blood pressure (A) is recorded 4-hourly, respirations are not the ½-hourly item, and descent of the head (C) is assessed on vaginal examination roughly 4-hourly; contractions are the ½-hourly observation.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The hormone that influences the onset of normal labour by rising towards term is', 'Progesterone', 'Oestrogen', 'Oxytocin', 'Prolactin', 'B', 'Towards term rising oestrogen overtakes the quiescent effect of progesterone, increasing myometrial excitability and oxytocin receptors to help trigger labour, per Myles Textbook for Midwives physiology of labour onset. Progesterone (A) maintains uterine quiescence and falls in effect, while oxytocin (C) and prolactin (D) act later; oestrogen is the hormone rising towards term to influence onset.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The CORRECT statement about maternal physiological changes during the first stage of normal labour is that', 'There is an increase in cardiac output by 30- 40%', 'The maternal pulse rate initially decreases', 'There is an increase in cardiac output by 10- 15 %', 'Maternal oxygen consumption is initially minimized', 'A', 'During the first stage of labour cardiac output rises by about 30-40% (rising further in the second stage) as each contraction returns blood to the circulation, per Myles Textbook for Midwives. The maternal pulse and oxygen consumption increase, not decrease (B, D are wrong), and 10-15% (C) understates the rise; the 30-40% increase is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During labour, a contraction that lasts for 28 seconds is denoted as', 'Mild contraction', 'Severe contraction', 'Strong contraction', 'Moderate contraction', 'A', 'A contraction lasting under about 30 seconds is described as mild (weak), moderate about 30-40 seconds, and strong/severe over 40-60 seconds, per Myles Textbook for Midwives assessment of contractions. A 28-second contraction is therefore mild; severe (B), strong (C) and moderate (D) all imply a longer duration.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The CORRECT statement about the physiological changes in second stage of labour is that', 'Uterine contractions strengthen & are more expulsive', 'Uterine contractions strengthen & are less expulsive', 'Abdominal muscles & diaphragm become less active', 'Anteriorly, rectum is compressed alongside the sacral curve', 'A', 'In the second stage uterine contractions become stronger, longer and more expulsive, aided by active abdominal muscles and diaphragm (the secondary powers), per Myles Textbook for Midwives physiology of the second stage. ''Less expulsive'' (B) and ''less active'' abdominal muscles (C) are the opposite of what occurs, and D misstates the rectal/sacral anatomy; contractions strengthening and becoming more expulsive is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The presenting diameter in a normal vertex presentation is', 'Sub-occipital frontal diameter', 'Sub-occipital bregmatic diameter', 'Sub-mento bregmatic diameter', 'Sub-mento vertical diameter', 'B', 'In a well-flexed vertex presentation the engaging antero-posterior diameter is the suboccipito-bregmatic (9.5 cm). Per Myles Textbook for Midwives, the suboccipitofrontal (10 cm) presents in partial deflexion, the submentobregmatic (9.5 cm) in a face presentation, and the submentovertical in incomplete extension; none of these describe a normal flexed vertex, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The statement that BEST describes restitution during the second stage of labour is', 'The head turns 3/8 of a circle back to where it was before internal rotation took place', 'This movement takes place to cause a twist on the foetal neck for easier delivery of the shoulders', 'The head turns 1/8 of a circle back to where it was before internal rotation took place', 'This movement comes after birth of the shoulders to complete delivery of the entire body', 'C', 'Restitution is the head turning 1/8 of a circle to undo the twist of the neck created during internal rotation, realigning the head with the shoulders. Per Myles Textbook for Midwives mechanism of labour, a 3/8-circle turn describes external rotation of the shoulders (option A), the movement after shoulder birth (D) is not restitution, so C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The type of a vaginal tear that involves the vaginal tissues, perineal muscles & the muscle surrounding the anal sphincter is', '`First degree tear', 'Third degree tear', 'Second degree tear', 'Fourth degree tear', 'B', 'A third-degree tear extends through vaginal mucosa and perineal muscles to involve the muscle of the anal sphincter. Per Myles Textbook for Midwives, a second-degree tear (option C) involves perineal muscles but spares the sphincter and a fourth-degree tear (D) breaches the anal/rectal mucosa; so B (third degree) matches the stem. Option A carries an OCR backtick but the intended answer is B.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mechanical factors that take place during the third stage of labour include', 'There is a 2.5 cm reduction in size of the uterus below the umbilicus', 'Elasticity of the placenta allows it to easily detach from uterine wall', 'There is a 2.5 cm reduction in size of the uterus above the umbilicus', 'Formation of a retro-placental clot prevents further descent of the placenta', 'C', 'In the third stage, retraction reduces the placental site and the uterus rises and narrows, the firm fundus rising about 2.5 cm above the umbilicus. Per Myles Textbook for Midwives, the placenta is inelastic (B wrong), a retro-placental clot aids not prevents separation (D wrong), and the uterus rises above not below the umbilicus (A wrong), so C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The method of placenta separation whereby it is expelled with the foetal surface first exposed is', 'Matthew- Duncan method', 'Cord method', 'Haemostatic method', 'Schultz method', 'D', 'In the Schultze method the placenta separates centrally and descends with the shiny foetal (fetal) surface presenting first. Per Myles Textbook for Midwives, the Matthews-Duncan method (A) presents the dull maternal surface first, and ''cord''/''haemostatic'' are not recognised separation-expulsion methods, so D is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following statements is correct about the fourth stage of normal labour?', 'The fourth stage of labour is considered as the last part of the second stage of normal labour', 'Includes the period from delivery of placenta & membranes to the end of first 2 hours post-partum', 'The primary goal of the fourth stage of labour is to deliver the placenta as fast as possible', 'The primary goal of this stage is to prevent maternal mortality via antepartum haemorrhage', 'B', 'Per Myles Textbook for Midwives, the fourth stage of labour spans from delivery of the placenta and membranes through the first 1-2 hours postpartum, a critical monitoring window for postpartum haemorrhage. Option A confuses it with the second stage, C describes third-stage management, and D wrongly cites antepartum haemorrhage, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A total Apgar score of 5 is clearly indicative of', 'Severe asphyxia neonatorum', 'Mild asphyxia neonatorum', 'Moderate asphyxia neonatorum', 'A healthy normal neonate', 'C', 'An Apgar score of 4-6 indicates moderate asphyxia neonatorum. Per Kenya Basic Paediatric Protocols and neonatal resuscitation standards, 0-3 is severe and 7-10 is normal, so a score of 5 falls in the moderate range, making C correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('At birth, the G.I.T of a normal neonate is', 'Structurally complete', 'Structurally incomplete', 'Functionally mature', 'Physiologically unsterile', 'A', 'Per Myles Textbook for Midwives, the neonatal GIT is structurally complete at term birth but functionally immature (digestive enzymes and controls still developing); the gut is sterile at birth and becomes colonised within hours, so ''physiologically unsterile'' is wrong. Thus A (structurally complete) is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physiological maternal response that is considered normal in the early post-partum period is', 'Notable urinary urgency', 'Decreased blood pressure', 'Notable rapid diuresis', 'Increased G.I.T motility', 'C', 'Per Myles Textbook for Midwives, marked (rapid) diuresis in the early puerperium is a normal physiological response as the body excretes the excess extracellular fluid accumulated in pregnancy. Blood pressure normalises rather than falls notably, GIT motility is reduced not increased postpartum, and urinary urgency is not the expected normal finding, so C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('By the end of two weeks post-partumly, the uterus weighs approximately', '60 grams', '200 grams', '300 grams', '150 grams', 'D', 'Per Myles Textbook for Midwives, uterine involution reduces the uterus from about 1000 g at delivery to roughly 300-350 g at 1 week and about 100-150 g by 2 weeks. Among the options 150 g is the accepted value at two weeks, so D is correct (60 g applies at ~6 weeks).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The smallest longitudinal fetal skull diameter measures', '9.5 cm', '8.2 cm', '7.5 cm', '10.5 cm', 'A', 'Per Myles Textbook for Midwives, the suboccipitobregmatic diameter (9.5 cm), which engages in a well-flexed vertex, is the smallest longitudinal (anteroposterior) diameter of the fetal skull. The larger 10.5 cm (occipitofrontal) and other listed values are not the smallest, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The area of the decidua , directly underneath the developing embryo is known as', 'Parietalis', 'Compactalis', 'Basalis', 'Capsularis', 'C', 'The decidua directly beneath the implanted embryo is the decidua basalis, which forms the maternal part of the placenta. Per Myles Textbook for Midwives, decidua capsularis overlies the embryo and decidua parietalis (vera) lines the rest of the uterus; ''compactalis'' is a layer name not a region, so C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The correct sequential flow of lochia is', 'Lochia alba, lochia rubra, lochia serosa', 'Lochia serosa, lochia rubra, lochia alba', 'Lochia rubra, lochia alba, lochia serosa', 'Lochia rubra, lochia serosa, lochia alba', 'D', 'Per Myles Textbook for Midwives, lochia progresses in the sequence rubra (red, days 1-4), then serosa (pink-brown), then alba (whitish/yellow) up to about 6 weeks. Only option D lists this correct order, so D is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The clinical feature that is suggestive of placenta separation during third stage of labour is', 'Shortening of the umbilical cord at the vulva', 'Sudden gush of fresh blood through the vagina', 'The uterus becomes more globular shaped', 'Spongy feeling of the uterus on palpation', 'C', 'Per Myles Textbook for Midwives, signs of placental separation include the uterus becoming firmer, rounder (globular) and rising as the placenta descends into the lower segment. The cord lengthens (not shortens) at the vulva (A wrong), the gush is a supportive but less reliable sign, and a spongy uterus suggests atony, so the globular uterus (C) is the classic reliable sign.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The MOST common method of delivery of the placenta and the membranes is', 'Fundal pressure application', 'Maternal effort method', 'Controlled cord traction', 'Supra-pubic pressure application', 'C', 'Per Kenya MOH/WHO active management of the third stage of labour, controlled cord traction (with counter-traction and after a uterotonic) is the standard method of delivering the placenta and membranes. Fundal and supra-pubic pressure are not used to deliver the placenta and fundal pressure is contraindicated, so C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the immediate post-partum period, the midwife should take the woman''s vital signs', 'Every 15 minutes during the first 1 hour', 'Every 30 minutes during the first 1 hour', 'Every hour for the first two hours', 'Every 5 minutes for the first 30 minutes', 'A', 'Per Myles Textbook for Midwives and Kenya MOH postnatal care standards, vital signs in the immediate postpartum (fourth stage) are checked every 15 minutes during the first hour to detect early haemorrhage or shock. Half-hourly or hourly checks are less frequent than required in this critical window, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary CRITICAL observation for Apgar scoring is the', 'Heart rate', 'Respiratory rate', 'Presence of meconium', 'Evaluation of moro reflex', 'A', 'Per Kenya Basic Paediatric Protocols and neonatal resuscitation guidance, heart rate is the primary critical parameter in Apgar scoring and the key determinant guiding resuscitation. Respiratory rate, meconium and the Moro reflex are less central than heart rate in scoring, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A normal neonate''s respirations are described as', 'Irregular, abdominal, 40- 60 per minute', 'Regular, abdominal, 40- 60 per minute', 'Irregular, from chest wall, 40- 60 minute', 'Regular, from chest wall, 40- 60 minute', 'A', 'Per Myles Textbook for Midwives, normal neonatal respirations are diaphragmatic/abdominal, irregular in rhythm, and 40-60 breaths per minute. Neonates breathe abdominally not from the chest wall (C, D wrong) and the rhythm is irregular not regular (B wrong), so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term, used to describe the fine downy hair covering the neonate''s skin at birth is', 'Caseosa', 'Milia', 'Patches', 'Lanugo', 'D', 'Per Myles Textbook for Midwives, lanugo is the fine downy hair covering the fetal/neonatal skin. Vernix caseosa (A) is the greasy protective coating and milia (B) are tiny sebaceous cysts, so D is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Moro reflex response usually disappears after', '6 months', '4 months', '2 months', '3 months', 'B', 'Per standard paediatric references and Myles, the Moro (startle) reflex is present at birth and normally disappears by about 3-4 months of age. Among the options 4 months is the accepted upper limit for its disappearance, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The correct statement about the involution of the uterus during puerperium is', 'Through ischaemia, uterine muscle fibres are auto-digested by the proteolytic hormone', 'The process occurs mainly through autolysis which involves localized uterine anaemia', 'Lining of the uterus is cast off and replaced first by granular tissue', 'Lining of the uterus is cast off and replaced first by the decidua', 'A', 'Per Myles Textbook for Midwives, involution occurs by ischaemia (retraction constricting vessels), autolysis (proteolytic enzyme digestion of muscle fibres) and phagocytosis. Option A best captures ischaemia plus autolytic proteolytic digestion of muscle fibres; the endometrial lining is later regenerated but this is not the primary involution mechanism, so A is the best answer.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A minor disorder during puerperium includes', 'After pains', 'Puerperal psychosis', 'Puerperal sepsis', 'Puerperal thrombosis', 'A', 'Per Myles Textbook for Midwives, after-pains are a common minor, self-limiting disorder of the puerperium caused by uterine contractions. Puerperal sepsis, psychosis and thrombosis are major/serious complications, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The region of the fetal skull bounded superiorly by orbital ridges and inferiorly by mentum is', 'Vertex', 'Face', 'Brow', 'Base', 'B', 'Per Myles Textbook for Midwives, the face region of the fetal skull is bounded superiorly by the orbital ridges and inferiorly by the mentum (chin). The brow (C) lies between the orbital ridges and the anterior fontanelle, and the vertex (A) lies between the fontanelles and parietal eminences, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The chorionic villi the secures the placenta on the decidua are known as', 'Anchoring villi', 'Nutritive villi', 'Chorion frondosum', 'Chorion laeve', 'A', 'Per Myles Textbook for Midwives, anchoring villi attach the placenta to the decidua basalis, securing it. Nutritive/floating villi (B) handle exchange, chorion frondosum (C) is the villous chorion as a whole, and chorion laeve (D) is the smooth non-villous chorion, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Prenatally physiological changes on the renal system includes', 'Relaxation of ureters and chloasma', 'Frequency of micturition and pica', 'Occult oedema and increased renal activities', 'Stress incontinence and ureters relaxation', 'D', 'Physiological renal/urinary-tract changes in pregnancy include progesterone-induced relaxation and dilatation of the ureters (predisposing to stasis) and, later, stress incontinence from pressure of the gravid uterus on the bladder. Option D pairs two genuine renal-system changes, whereas the distractors mix in non-renal features (chloasma, pica), so D is correct. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The aim of having the nipple and half of the areola within the baby''s mouth is to', 'Ensure best position', 'Finish feed successfully', 'Trigger sucking reflex', 'Have baby relax', 'C', 'Per Myles Textbook for Midwives, taking the nipple and much of the areola into the mouth draws the teat back to the junction of the hard and soft palate, stimulating the sucking reflex and effective milk transfer. While correct positioning matters, the specific aim of adequate areolar attachment is to trigger effective sucking, so C is the best answer.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('At 36 weeks, a normal fetal is expected to weigh', '2000 gm', '2500 gm', '3000 gm', '1800 gm', 'B', 'Per Myles Textbook for Midwives fetal growth estimates, the fetus weighs approximately 2500 g at 36 weeks, reaching about 3400 g at term. The other values are too low or too high for 36 weeks, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A moderate contraction lasts for', '19 seconds', '42 seconds', '15 seconds', '28 seconds', 'B', 'Per midwifery labour assessment, a moderate uterine contraction lasts about 40-45 seconds (mild <20 sec, strong >60 sec). Among the options 42 seconds fits the moderate range, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The relief experienced on maternal lungs two weeks prior to labour onsent due to expansion of the lower uterine segment is collectively referred to as', 'Engagement', 'Lightening', 'Descent', 'Flexion', 'B', 'Per Myles Textbook for Midwives, lightening is the relief of upper-abdominal and diaphragmatic pressure a few weeks before labour as the fetal head descends and the lower uterine segment forms, easing maternal breathing. Engagement, descent and flexion describe mechanical positioning of the head, not the sensation of relief, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The statement that BEST defines fetal lie is', 'The relationship between the long axis of the fetus and the long axis of the uterus', 'The part of the presentation used when referring to the fetal position in the uterus', 'The relationship of the fetal head and limbs to its trunk', 'The part of the fetus which first lies at the pelvic brim', 'A', 'Per Myles Textbook for Midwives, fetal lie is defined as the relationship between the long axis of the fetus and the long axis of the uterus (longitudinal, transverse or oblique). Option C describes attitude, D describes presentation, and B is vague, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The third degree perineal tear involves a tear of the', 'Vaginal tissues, perineal muscles & the muscle that surrounds the anal sphincter', 'Vaginal tissues, perineal muscles & anal sphincter as well as tissue lining the rectum', 'Vaginal tissues, the cervix & the muscle that surrounds the anal sphincter', 'Vaginal tissues, the perineal muscles & the muscles surrounding the cervix', 'A', 'Per Myles Textbook for Midwives, a third-degree tear involves the vaginal tissues and perineal muscles extending to involve the anal sphincter muscle. Option B (which adds tearing of the rectal lining) describes a fourth-degree tear, so A is the correct description of a third-degree tear.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The correct statement with regards to uterine contractions during the second stage of labour is', 'The contractions intensify and are less expulsive in nature', 'The average strength of the contractions is approximately 38 seconds', 'The contractions intensify and are more expulsive in nature', 'Ferguson reflex occurs as a result of moderate contractions stimulating nerve receptors', 'C', 'Per Myles Textbook for Midwives, in the second stage uterine contractions become stronger, longer and more expulsive, aided by the Ferguson reflex and maternal bearing-down. Option A wrongly says less expulsive, and Ferguson reflex results from strong (not moderate) contractions, so C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Immediately after the delivery of the baby, the person assisting the midwife should first', 'Take the baby''s weight', 'Keep the neonate warm', 'Apply the identification band', 'Check the number of umbilical vessels', 'B', 'Per Kenya Basic Paediatric Protocols and essential newborn care, the immediate priority after delivery is thermoregulation (dry and keep the baby warm, skin-to-skin) to prevent hypothermia. Weighing, ID banding and vessel counting follow after the airway/warmth are secured, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The beginning of the second stage of normal labour is recognized by the client''s desire to', 'Relax during contractions', 'Pant during contractions', 'Push during contractions', 'Blow during contractions', 'C', 'Per Myles Textbook for Midwives, the second stage is heralded by an involuntary urge to push (bear down) during contractions as the presenting part descends onto the pelvic floor (Ferguson reflex). Panting and blowing are techniques used to avoid pushing prematurely, so C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The method of placenta separation whereby the placenta is expelled with the fetal surface first exposed is known as', 'Matthew Duncan method', 'Fundal pressure method', 'Supra-pubic pressure', 'Schultz Method', 'D', 'Per Myles Textbook for Midwives, in the Schultze method the placenta descends and is expelled with the glistening foetal surface presenting first. The Matthews-Duncan method (A) presents the maternal surface first, and fundal/supra-pubic pressure are not separation methods, so D is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During separation and descent of the placenta, blood is prevented from going back into the maternal system by retraction of', 'The transverse uterine muscle fibres', 'The oblique uterine muscle fibre vessels', 'The longitudinal uterine muscle fibres', 'The supra- vaginal muscle fibre vessels', 'C', 'Per Myles Textbook for Midwives, retraction of the myometrial fibres compresses the torn placental-site vessels (the ''living ligatures'') to prevent blood loss. Although the oblique/interlacing fibres are classically named the living ligatures, that option is corrupted as ''oblique... fibre vessels''; among sound options the longitudinal muscle fibres best fits, so C is the least-wrong answer.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The uterine supports that results from thickening of the broad ligaments are', 'Transverse cervical', 'Pubo cervical', 'Utero sacral', 'Round cervical', 'A', 'The transverse cervical (cardinal/Mackenrodt''s) ligaments are formed by thickening of the base of the broad ligaments and are the chief supports of the uterus. Per Myles Textbook for Midwives, the pubocervical and uterosacral ligaments arise separately and ''round cervical'' is not a recognised support, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ms. T comes to the labour ward in active phase of labour and appears restless and irritable. The MOST appropriate action the midwife should take is to', 'Contact the obstetrician on duty to come urgently', 'Administer a sedative drug to help her relax', 'Ask her to move immediately about the room to reduce pain', 'Coach the patient on breathing and relaxation techniques', 'D', 'For a restless, irritable woman in active labour, the most appropriate first midwifery action is supportive non-pharmacological care—coaching breathing and relaxation. Per Myles Textbook for Midwives, sedation is not first-line, restlessness alone does not warrant an urgent obstetric call, and forcing ambulation is not indicated, so D is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following messages would you include when teaching a mother on umbilical cord care?', 'Apply peroxide to the cord with each diaper change', 'Always keep the cord dry and open to air', 'Cover the cord with petroleum jelly after bathing', 'Wash the cord with soap and water every day', 'B', 'Per Kenya Basic Paediatric Protocols and WHO newborn care, dry cord care (keep the stump clean, dry and exposed to air) is recommended. Peroxide, petroleum jelly and daily soap-washing delay healing and increase infection risk, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The period between full cervical dilatation and the time when active maternal pushing efforts begin is known as the', 'Transition period', 'Second stage', 'Passive phase', 'First stage', 'C', 'The interval between full cervical dilatation and the onset of active maternal pushing is the passive (latent) phase of the second stage, before the expulsive urge begins. Per Myles Textbook for Midwives, the second stage as a whole (option B) spans full dilatation to birth, so the specific pre-pushing interval is the passive phase, making C correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Persistent nausea and vomiting related to pregnancy is indicative of', 'Morning sickness', 'Multiple gestation', 'Hyperemesis gravidarum', 'Hypertensive disorders', 'C', 'Persistent, intractable nausea and vomiting in pregnancy causing dehydration, weight loss and electrolyte imbalance is hyperemesis gravidarum, distinct from self-limiting morning sickness. Multiple gestation is a risk factor rather than the diagnosis, and hypertensive disorders do not present primarily as vomiting. Per Myles Textbook for Midwives and Kenya maternal care guidelines.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The complication that is associated with hyperemesis gravidarum is', 'Wernikle''s encephalopathy', 'Sheehan''s syndrome', 'Maurice encephalitis', 'Antepartum bleeding', 'A', 'Severe hyperemesis gravidarum causes thiamine (vitamin B1) depletion, which can precipitate Wernicke''s encephalopathy — the classic recognised complication. Sheehan''s syndrome follows postpartum haemorrhage, and ''Maurice encephalitis'' and antepartum bleeding are not linked to hyperemesis. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Specific management of moderate pre- eclampsia involves', 'Admission at first contact', 'Managing as an outpatient case', 'Admission in the intensive care unit', 'Encouraging plenty of oral fluids', 'A', 'Moderate pre-eclampsia warrants admission at first contact for close maternal and fetal monitoring and blood-pressure control. It is not managed purely as an outpatient, ICU is reserved for severe pre-eclampsia/eclampsia, and simply encouraging oral fluids is not specific management. Per Kenya National Guidelines for Quality Obstetrics and Perinatal Care / Myles.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Arched back and tightly clenched teeth, are among the features of which stage of eclampsia', 'Clonic', 'Tonic', 'Premonitory', 'Coma', 'B', 'In the tonic phase of an eclamptic fit the muscles enter sustained rigid contraction, producing an arched (opisthotonic) back and clenched jaw, which then gives way to the clonic (jerking) phase. The premonitory stage shows twitching and the coma stage follows the convulsion. Per Myles Textbook for Midwives.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Causes of polyhydramnious includes', 'Congenital abnormalities and chorioangioma', 'Severe fetal hypoxia and multiple pregnancy', 'Uncontrolled diabetes mellitus and anaemia', 'Rhesus D isoimmunisation and post datism', 'A', 'Per Myles Textbook for Midwives, classic causes of polyhydramnios include fetal congenital anomalies that impair swallowing (oesophageal atresia, anencephaly, open neural tube defects) and placental chorioangioma, both of which appear in option A. Multiple pregnancy and uncontrolled maternal diabetes also cause polyhydramnios, but options B and C pair them with fetal hypoxia and anaemia which are not primary causes; Rhesus isoimmunisation (D) causes hydrops rather than being the paired cause listed with post-datism.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Some of the neonatal complications of eclampsia are', 'Cerebral haemorrhage and pneumonia', 'Severe asphyxia and prematurity', 'Fractures and soft tissue trauma', 'Respiratory distress and hypoglycaemia', 'B', 'Per Myles Textbook for Midwives and Kenya obstetric guidelines, eclampsia impairs uteroplacental perfusion and usually forces preterm delivery, so the neonate suffers severe birth asphyxia and prematurity. Cerebral haemorrhage/pneumonia (A) and fractures/soft-tissue trauma (C) are birth-trauma events not specific to eclampsia; respiratory distress and hypoglycaemia (D) are consequences of the prematurity in B rather than the primary answer.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Productive cough, dyspnoea at rest and generalized oedema are among the features of:', 'Folate deficiency', 'Very severe anaemia', 'Mild iron deficiency', 'Severe anaemia', 'B', 'Per Myles/Kenya anaemia-in-pregnancy guidelines, productive cough, dyspnoea at rest and generalised oedema indicate high-output cardiac decompensation seen in very severe anaemia (Hb typically <4 g/dl), a transfusion emergency. Mild iron deficiency (C) and folate deficiency (A) do not cause dyspnoea at rest; ''severe anaemia'' (D) is a lesser grade whose defining feature is not cardiac failure, so ''very severe anaemia'' is the best fit.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Incidental antepartum haemorrhage is also referred to as', 'Intraplacental haemorrhage', 'Intrapartum haemorrhage', 'Extraplacental haemorrhage', 'Preterm haemorrhage', 'C', 'Per Myles Textbook for Midwives, incidental (unavoidable) antepartum haemorrhage originates from lesions of the lower genital tract outside the placental site, hence it is termed extraplacental haemorrhage, in contrast to placental causes (praevia/abruption). Intrapartum (B) refers to timing not site, and ''intraplacental'' (A) and ''preterm'' (D) are not recognised synonyms.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Chemical diabetes mellitus is a classification based on', 'Symptom are absent and abnormal specific laboratory results', 'Presence of symptoms and abnormal specific laboratory results', 'Previous congenital abnormalities and unexplained stillbirth', 'Previous birth of a baby weighing >4.3kg and spontaneous abortion', 'A', 'Per standard obstetric (White/Myles) classification, chemical or subclinical diabetes is diagnosed by abnormal specific laboratory glucose results in the ABSENCE of symptoms, exactly as stated in option A. Option B (symptoms present) describes clinical/overt diabetes, and options C and D describe potential/latent diabetes risk history rather than chemical diabetes.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Diamorphic anaemia results due to deficiency of', 'Iron and thiamine', 'Iron and folic acid', 'Folic acid and thiamine', 'Liver enzymes and iron', 'B', 'Per Myles Textbook for Midwives and Kenya anaemia guidelines, dimorphic (dimorphic) anaemia results from combined deficiency of iron and folic acid, giving a mixed microcytic-hypochromic and macrocytic blood picture common in pregnancy. Thiamine (A, C) causes beri-beri/neurological disease, and liver-enzyme deficiency (D) is not a recognised cause of dimorphic anaemia.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A MAJOR predisposing factor to cardiac disease in pregnancy includes', 'Rheumatic heart disease', 'Notable peripheral oedema', 'Easy fatiguability', 'Basal crepitation', 'A', 'Per Myles Textbook for Midwives, rheumatic heart disease is the major underlying/predisposing cause of cardiac disease complicating pregnancy in low-resource settings such as Kenya. Peripheral oedema (B), easy fatiguability (C) and basal crepitations (D) are clinical signs of cardiac decompensation, not predisposing factors.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following clinical features denotes cardiac disease grade III?', 'Patient is comfortable even at rest', 'Patient is asymptomatic initially', 'Marked limitation of physical activity', 'Absolute limitation of physical activity', 'C', 'Per the NYHA classification used in Myles/Kenya obstetric cardiac guidelines, Grade III is defined by marked limitation of physical activity: comfortable at rest but less-than-ordinary activity causes symptoms. ''Comfortable at rest'' (A) and ''asymptomatic'' (B) fit Grades I-II, while ''absolute limitation''/symptoms at rest (D) is Grade IV.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The MOST common causative organism of acute pyelonephritis in pregnancy is', 'Streptococcus faecalis', 'Escherichia coli', 'Proteus vulgaris', 'Staphylococcus aureus', 'B', 'Per Myles Textbook for Midwives and Kenya MOH obstetric guidelines, Escherichia coli, a gram-negative gut commensal, is the commonest organism causing acute pyelonephritis in pregnancy (the great majority of cases). Streptococcus faecalis (A), Proteus (C) and Staph. aureus (D) are far less frequent causes.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The PRIORITY management of uncomplicated malaria during the second trimester includes administration of', 'Oral quinine', 'Parenteral quinine', 'Artemether lumefantrine', 'Sulphadoxine pyrimethamine', 'C', 'Per the Kenya National Malaria Treatment Guidelines, uncomplicated malaria in the 2nd and 3rd trimesters is treated first-line with artemether-lumefantrine (an ACT). Oral/parenteral quinine (A, B) is reserved for the 1st trimester or severe disease, and sulphadoxine-pyrimethamine (D) is for IPTp prophylaxis, not treatment.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The factor that is in indicative of an abnormal labour pattern on vaginal examination is', 'The vagina is warm and moist', 'Cervical canal is long and thick', 'Cervical canal is short and thin', 'The vagina is hot and dry', 'B', 'Per Myles Textbook for Midwives, in progressing labour the cervix effaces and thins, so a cervix that remains long and thick on vaginal examination indicates poor progress/abnormal labour. A short, thin cervix (C) is the normal progressing finding, and a warm moist vagina (A) is normal while a hot dry vagina (D) suggests obstruction/dehydration but is not the effacement indicator asked.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following statements is correct about secondary post-partum haemorrhage?', 'Mostly occurs between the 8th-14th day post-partumly', 'Results due to bleeding immediately after delivery', 'Can extend up to the first 46 days following delivery', 'Is diagnosed by presence of persistent lochia serosa', 'A', 'Per Myles Textbook for Midwives, secondary PPH is abnormal bleeding from 24 hours to 6 weeks postpartum, most commonly between the 8th and 14th days, usually from retained products or endometritis. Bleeding immediately after delivery (B) is primary PPH; option C (''46 days'') is an OCR/typo error, and persistent lochia serosa (D) is not the diagnostic criterion.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A non- pharmacological measure of pain relief in labour includes', 'Entonox', 'Cyclothane', 'Homeopathy', 'Diamorphine', 'C', 'Per Myles Textbook for Midwives, non-pharmacological pain relief in labour includes complementary therapies such as homeopathy, massage, relaxation and hydrotherapy. Entonox (A), cyclothane/an anaesthetic gas (B) and diamorphine (D) are all pharmacological agents.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In monozygotic twinning, splitting after twelfth (12th ) day of fertilization is highly associated with', 'Fetal papyraceous', 'Premature birth', 'Siamese twin', 'Diamniotic twin', 'C', 'Per Myles Textbook for Midwives, in monozygotic twinning splitting after the 12th-13th day is incomplete and produces conjoined (Siamese) twins. Earlier splits give diamniotic arrangements (D); fetus papyraceous (A) and prematurity (B) are not the specific association of late splitting.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The drug of choice in the management of eclampsia is', 'Phenobarbitone', 'Magnesium sulphate', 'Calcium gluconate', 'Sodium bicarbonate', 'B', 'Per Kenya MOH maternal guidelines and WHO, magnesium sulphate is the drug of choice to control and prevent eclamptic convulsions. Calcium gluconate (C) is only the antidote for magnesium toxicity; phenobarbitone (A) and sodium bicarbonate (D) are not first-line.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main clinical feature in Hyperemesis gravidarum is', 'Persistent vomiting or nausea', 'Persistent sight related problems', 'Persistent diarrhea and vomiting', 'Frequency or urgency of micturition', 'A', 'Per Myles Textbook for Midwives, hyperemesis gravidarum is defined by persistent, severe nausea and vomiting causing dehydration, electrolyte imbalance and weight loss, so option A is the main clinical feature. Visual problems (B), diarrhoea (C) and urinary frequency (D) are not features of hyperemesis.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Wernickle''s encephalopathy and Mallory-Weiss syndrome are among the complications of', 'Placenta praevia', 'Hypertensive disorders', 'Vitamin B deficiency', 'Hyperemesis gravidarum', 'D', 'Per Myles Textbook for Midwives, prolonged severe vomiting in hyperemesis gravidarum causes Wernicke''s encephalopathy (thiamine deficiency) and Mallory-Weiss oesophageal tears from repeated retching. Placenta praevia (A), hypertensive disorders (B) and isolated vitamin B deficiency (C) do not produce this combination.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Uterine apoplexy is associated with', 'Incidental haemorrhage', 'Placental abruption', 'Multiple pregnancy', 'Placenta preavia', 'B', 'Per Myles Textbook for Midwives, uterine apoplexy (Couvelaire uterus) is blood extravasation into the myometrium associated with severe placental abruption. Incidental haemorrhage (A), multiple pregnancy (C) and placenta praevia (D) are not causes of the Couvelaire uterus.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Positive fasting blood sugar and oral glucose torelance test, as well as being symptomatic is diagnostic of', 'Potential diabetes mellitus', 'Gestational diabetes mellitus', 'Clinical diabetes mellitus', 'Chemical diabetes mellitus', 'C', 'Per standard obstetric (White/Myles) classification, a woman who is symptomatic with a positive fasting blood sugar AND abnormal OGTT has overt/clinical diabetes mellitus. Chemical diabetes (D) is asymptomatic with only an abnormal OGTT; gestational diabetes (B) is glucose intolerance first recognised in pregnancy but the symptomatic-plus-positive-FBS picture defines clinical/overt disease, and potential diabetes (A) is a risk category without abnormal tests.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Neonate born of a diabetic mother, is fed within the first 15 minutes to prevent', 'Hypocalcaemia', 'Hypoglycaemia', 'Hyponatraemia', 'Hypokalaemia', 'B', 'Per Kenya Basic Paediatric Protocols, the infant of a diabetic mother has fetal hyperinsulinaemia and is prone to neonatal hypoglycaemia, so early feeding within the first 15-30 minutes prevents it. Hypocalcaemia (A) is also seen in these infants but is not prevented by early feeding within 15 minutes, and hyponatraemia (C)/hypokalaemia (D) are not the primary early risk.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is associated with diazygotic twinning?', 'Conjoined twins', 'Polyhydramnious', 'Superfecundation', 'Foetus compressus', 'C', 'Per Myles Textbook for Midwives, dizygotic (binovular) twinning arises from two ova fertilised by two sperm, so superfecundation (fertilisation of two ova by sperm from separate coital acts) can only occur in dizygotic twinning. Conjoined twins (A), fetus compressus (D) and the shared-circulation cause of polyhydramnios (B) are phenomena of monozygotic twinning.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Haematinics , dietary advice and close surveillance are management plans for', 'Moderate anaemia', 'Mild anaemia', 'Severe anaemia', 'Anaemia prevention', 'B', 'Per Kenya MOH ANC guidelines, mild anaemia in pregnancy is managed conservatively with haematinics (iron/folate), dietary advice and close surveillance. Moderate (A) and severe (C) anaemia require higher-dose/parenteral iron or transfusion, and ''anaemia prevention'' (D) refers to routine prophylaxis rather than treatment of established anaemia.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A predisposing factor to cardiac disease in pregnancy includes', 'Pulmonary oedema', 'Easy fatiguability', 'Basal crepitation', 'Severe anaemia', 'D', 'Per Myles Textbook for Midwives, severe anaemia raises cardiac output and workload and is a recognised predisposing/aggravating factor for cardiac disease in pregnancy. Pulmonary oedema (A), easy fatiguability (B) and basal crepitations (C) are clinical features/consequences of cardiac failure, not predisposing factors.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The clinical feature that is suggestive of acute pyelonephritis in pregnancy is', 'Kinking of the ureters', 'Vesico-ureteric reflux', 'Fishy smell in urine', 'Uncontrolled diabetes', 'B', 'Per Myles Textbook for Midwives, the physiological ureteric dilatation of pregnancy with vesico-ureteric reflux permits ascending infection producing acute pyelonephritis, making reflux the relevant clinical/pathophysiological feature listed. Kinking of the ureters (A) is a predisposing anatomical change, a fishy urine odour (C) suggests bacterial vaginosis, and uncontrolled diabetes (D) is a risk factor, not a feature.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pregnant woman with acute pyelonephritis is advised on a high fluid intake so as to', 'Promote enough rest', 'Correct dehydration', 'Relief irritability', 'Increase urine output', 'D', 'Per Myles Textbook for Midwives, high fluid intake in pyelonephritis increases urine output which flushes bacteria from the urinary tract, so option D states the primary rationale. Correcting dehydration (B) is a secondary benefit, and promoting rest (A) or relieving irritability (C) are not the purpose of pushing fluids.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The priority management of uncomplicated malaria during the second trimester includes the administration of', 'Oral quinine', 'Parenteral quinine', 'Artemether lumefantrine', 'Sulfadoxine pyrimethamine', 'C', 'Per the Kenya National Malaria Treatment Guidelines, uncomplicated malaria in the 2nd trimester is treated first-line with artemether-lumefantrine (an ACT). Oral/parenteral quinine (A, B) is reserved for the 1st trimester or severe malaria, and sulfadoxine-pyrimethamine (D) is for IPTp prophylaxis, not treatment.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The correct statement about malaria prophylaxis during pregnancy is that', 'Sulfadoxine Pyrimethamine should be given to all pregnant women in malaria endemic zones', 'All pregnant women in malaria endemic zones are assumed free of the parasite until tested', 'Sulfadoxine Pyrimethamine should be administered with each alternate visit after quickening', 'All antenatal clients in Kenya should receive intermittent presumptive treatment at least 6 doses', 'A', 'Per the Kenya National Malaria Guidelines, all pregnant women in malaria-endemic (moderate-to-high transmission) zones should receive IPTp with sulfadoxine-pyrimethamine, making option A the correct core policy. Option B misstates the presumptive approach, option C''s ''each alternate visit after quickening'' is inaccurate (SP is given at each scheduled ANC visit at least one month apart), and option D''s ''at least 6 doses'' is wrong (a minimum of 3 doses is recommended).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The commonly used inhalational analgesia during labour is', 'Entonox', 'Trilene', 'Oxygen', 'Nitrous oxide', 'A', 'Per Myles Textbook for Midwives, Entonox, a 50:50 mixture of nitrous oxide and oxygen, is the commonly used inhalational analgesia in labour. Plain nitrous oxide (D), oxygen alone (C) and trilene/trichloroethylene (B, now largely obsolete) are not the standard inhalational analgesic.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following features is indicative of an abnormal labour pattern?', 'Presence of the retraction ring', 'Presence of the bandl''s ring', 'Cervical canal short and thin', 'Vagina is warm and moist', 'B', 'Per Myles Textbook for Midwives, Bandl''s ring is a pathological retraction ring that rises towards the umbilicus in obstructed labour and warns of impending rupture, indicating abnormal labour. The normal physiological retraction ring (A) and a short thin cervix (C) or warm moist vagina (D) are normal findings.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Post-partum haemorrhage is likely to lead to acute renal failure due to', 'Sheehan''s syndrome', 'Disseminated intravascular coagulation', 'Hypovolaemia leading to tubules necrosis', 'Asherman''s syndrome', 'C', 'Per Brunner & Suddarth and Myles, PPH causes hypovolaemia and renal hypoperfusion leading to acute tubular necrosis and acute renal failure. Sheehan''s syndrome (A) is pituitary necrosis, DIC (B) is a coagulation complication that can contribute but the direct renal mechanism is tubular necrosis, and Asherman''s syndrome (D) causes intrauterine adhesions.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Placental parasitation is associated with', 'Malaria prenatally', 'Candidiasis prenatally', 'Tuberculosis prenatally', 'Multiple gestation', 'A', 'Per the Kenya National Malaria Guidelines and Myles, placental parasitation (sequestration of parasitised red cells in the intervillous space) is characteristic of malaria in pregnancy, contributing to maternal anaemia and low birth weight. Candidiasis (B), tuberculosis (C) and multiple gestation (D) are not associated with placental parasitation.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Complete placenta praevia is also referred to as', 'Type 4', 'Type 1', 'Type 2', 'Type 3', 'A', 'Per Myles Textbook for Midwives, complete/central placenta praevia, where the placenta entirely covers the internal os, is classified as Type 4 (Grade IV). Types 1-3 (B, C, D) describe lateral, marginal and partial praevia respectively.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bruised and oedematous appeararnce of the uterus, associated with placenta abruption is collectively referred to as', 'Wernickle''s encephalopathy', 'Uterine prolapse', 'Couvelaire uterus', 'Asherman''s syndrome', 'C', 'Per Myles Textbook for Midwives, the bruised, oedematous uterus from blood extravasation into the myometrium in severe abruptio placentae is the Couvelaire uterus (uterine apoplexy). Wernicke''s encephalopathy (A), uterine prolapse (B) and Asherman''s syndrome (D) are unrelated conditions.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main feature of Hyperemesis gravidarum is', 'Pallor or cyanosis of mucous membrane', 'Inability to eat or retain food all through', 'Weakness because of severe state of shock', 'Smaller fundal height compared to dates', 'B', 'Per Myles Textbook for Midwives, the main feature of hyperemesis gravidarum is the intractable inability to eat or retain food due to persistent severe vomiting, leading to dehydration and weight loss. Pallor/cyanosis (A) and shock (C) are late/severe complications rather than the defining feature, and a small fundal height (D) is unrelated.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following can lead to placenta preavia?', 'Grandemultiparity', 'Preeclampsia', 'Placenta fenestrate', 'placenta increta', 'A', 'Per Myles Textbook for Midwives, grand multiparity is a recognised predisposing factor for placenta praevia because uterine scarring and poor decidua favour low implantation. Pre-eclampsia (B) predisposes to abruption not praevia, and placenta fenestrata (C) and placenta increta (D) are morphological/adherence anomalies, not causes of praevia.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mallory-Weiss syndrome is a complication of', 'Placenta preavia', 'Cardiac disease', 'Postpartum haemorrhage', 'Hyperemesis gravidarum', 'D', 'Per Myles Textbook for Midwives, Mallory-Weiss syndrome (oesophageal mucosal tears from forceful retching) is a complication of the severe persistent vomiting of hyperemesis gravidarum. Placenta praevia (A), cardiac disease (B) and PPH (C) do not cause oesophageal tears.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bishop''s score is based on', 'Descent, presentation and cervical dilatation', 'Position, attitude and cervical length', 'Descent, cervical length and dilatation', 'Cervical dilatation, lie and effacement', 'A', 'Per Myles Textbook for Midwives, the Bishop''s score assesses cervical dilatation, effacement (length), consistency, position and station/descent of the presenting part to grade favourability for induction; among the options, A (descent, presentation-station and cervical dilatation) captures the most genuine Bishop components. Options B, C and D each substitute non-Bishop parameters such as attitude, lie or fetal position.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Total loss of polarity and fundal dominance leads to', 'Precipitate labour', 'Colicky uterus', 'Spontaneous labour', 'Cervical dystocia', 'B', 'Per Myles Textbook for Midwives, total loss of polarity and fundal dominance produces uncoordinated uterine action, a colicky uterus with painful but ineffective contractions. Precipitate labour (A) is over-efficient rapid labour, spontaneous labour (C) is normal onset, and cervical dystocia (D) is a rigid-cervix problem, not loss of polarity.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Among the major predisposing factors of cardiac disease prenatally are', 'Rheumatic heart disease and leukaemia', 'Ischaemic heart disease and dehydration', 'Uncontrolled hypertension and obesity', 'Smoking and peptic ulcer disease', 'A', 'Per Myles Textbook for Midwives, rheumatic heart disease is the leading predisposing cause of cardiac disease in pregnancy in developing countries, so option A (which contains it) is the best fit. The other options pair non-primary factors (ischaemic disease/dehydration, hypertension/obesity, smoking/PUD) that are not the major recognised predisposing cause.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is NOT a source of pain in labour', 'Uterine contractions', 'Socio-cultural norms', 'Cervical dilatation', 'Pelvic floor stretching', 'B', 'Per Myles Textbook for Midwives, the physical sources of labour pain are uterine contractions, cervical dilatation/effacement and stretching of the pelvic floor, vagina and perineum. Socio-cultural norms modify the perception and expression of pain but are NOT a physical source, so option B is correctly the exception.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Surgical induction of labour refers to use of', 'Cytotec and Mechanical cervical dilatation', 'Sweeping of membranes and amniotomy', 'Mechanical cervical dilatation and buscopan', 'Artificial rupture of membranes and synitocinon', 'D', 'Per Myles Textbook for Midwives, surgical induction of labour refers to artificial rupture of membranes (amniotomy), commonly combined with an oxytocin (syntocinon) infusion. The other options mix medical/mechanical methods (Cytotec, membrane sweeping, buscopan) that are not classified as surgical induction.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Perception and reaction to labour pain is highly influenced by', 'Labour preparedness and fatigue', 'Culture and age of the woman', 'Culture and level of education', 'Number of deliveries and anxiety.', 'C', 'Per Myles Textbook for Midwives, perception and reaction to labour pain are strongly influenced by socio-cultural background and the woman''s level of education/knowledge, which shape expectations and coping. Options pairing fatigue (A), age (B) or parity/anxiety (D) capture only single modifiers, whereas culture plus education (C) reflect the strongest recognised influences.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Based on vaginal examination findings, indicators of abnormal labour are', 'Bandl''s ring and oedematous vulva', 'Oedematous cervix and fetal hypoxia', 'Hot ,dry vagina and arrest in descend', 'Maternal distress and severe moulding', 'A', 'Per Myles Textbook for Midwives, vaginal-examination indicators of obstructed/abnormal labour include a rising Bandl''s ring and an oedematous vulva/cervix from prolonged pressure, both directly assessable at VE. Fetal hypoxia (B) is detected by fetal monitoring, and maternal distress/severe moulding (D) or a hot dry vagina (C) are not the paired VE oedema/Bandl indicators asked.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Inability to eat or retain feeds throughout the day prenatally is highly associated with', 'Weight gain control', 'Hyperemesis gravidarum', 'Morning sickness', 'presence of preeclampsia', 'B', 'Per Myles Textbook for Midwives, inability to eat or retain feeds throughout the day is the hallmark of hyperemesis gravidarum. Ordinary morning sickness (C) is milder and self-limiting without persistent inability to retain food, and pre-eclampsia (D) or weight-gain control (A) are unrelated to this feature.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In eclampsia, violent contraction and relaxation of the whole body occurs in', 'Clonic stage', 'Coma stage', 'Premonitory stage', 'Tonic stage', 'A', 'Per Myles Textbook for Midwives, the eclamptic fit has four stages; the clonic stage is characterised by violent alternating contraction and relaxation (jerking convulsive movements) of the whole body. The tonic stage (option D) is sustained muscular rigidity with clenched jaw and arched back, the premonitory stage (C) is twitching of face/hands, and the coma stage (B) is post-ictal unconsciousness.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinical diagnosis of polyhydramnios is based on excessive amount of amniotic fluid exceeding', '1500 mls', '2500 mls', '1900 mls', '3000 mls', 'B', 'Per Myles Textbook for Midwives, normal amniotic fluid at term is about 500-1500 ml and polyhydramnios is diagnosed when the volume is excessive (classically exceeding roughly 2000-2500 ml). Of the four options, 2500 ml (B) is the accepted clinical threshold; 1500 ml (A) is merely the upper limit of normal, while 1900 ml (C) and 3000 ml (D) are not the standard cut-off.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Immediate management of a neonate whose mother is TB smear positive at birth is', 'isoniazid 5 mg per kg daily for 3 months', 'isoniazid 5 mg per kg daily for 3 weeks', 'isoniazid 5 mg per kg daily for 6 weeks', 'isoniazid 5 mg per kg daily for 6 months', 'D', 'Per the Kenya National TB (Guidelines for Management of TB) and IPT policy, an asymptomatic neonate born to a smear-positive mother is given isoniazid preventive therapy at 5-10 mg/kg daily for 6 months, with BCG deferred/given after completion and follow-up for active TB. Six months (D) is the full protective course; 3 weeks (B), 6 weeks (C) and 3 months (A) are all too short to prevent progression.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bipartite placenta and succenturiate lobe are causes of', 'Placenta abruption', 'Retained placenta', 'Placental calcification', 'Placental insufficieny', 'B', 'Per Myles Textbook for Midwives, both bipartite placenta and succenturiate lobe placenta are abnormal morphological variants that increase the risk of retained placental tissue after delivery. A bipartite placenta is divided into two nearly equal lobes connected by blood vessels within the membranes — one lobe may remain in the uterus after delivery of the other. A succenturiate (accessory) lobe develops separately from the main placenta and is connected to it by fetal blood vessels running through the membranes; after the main placenta is delivered, the accessory lobe may be retained in the uterus, causing retained placenta and postpartum haemorrhage. Retained placenta (option B) is the correct answer. Placenta praevia is a site-of-implantation disorder unrelated to placental morphology; placental abruption (A), calcification (C) and insufficiency (D) are not caused by these structural variants.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The diagnostic factor of Polyhydramnious, based on percussion is', 'Muffled fetal heart sounds', 'Presence of a dull sound', 'Excessive fetal movements', 'Presence of a fluid thrill', 'D', 'Per Myles Textbook for Midwives, in polyhydramnios the tense fluid-filled uterus transmits a fluid thrill (wave) felt on percussion/palpation, and fetal parts are hard to palpate with muffled heart sounds on auscultation. The characteristic percussion sign specifically is the fluid thrill (D); muffled heart sounds (A) are an auscultation finding, a dull note (B) is not typical of a fluid-filled uterus, and excessive fetal movement (C) is not a percussion sign.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which drug facilitates multiplication of malaria parasite when administered together with sulfadoxine pyrimethamine?', 'Ranferon', 'Albendazole', 'Folic acid', 'Pholia acid', 'C', 'Sulfadoxine-pyrimethamine (used as IPTp in pregnancy) works by blocking the parasite''s folate synthesis pathway; co-administering folic acid (especially high-dose 5 mg) supplies the folate the parasite needs and antagonises SP, reducing efficacy. Per Kenya National Malaria Guidelines high-dose folate is spaced away from SP dosing. Ranferon (A) and albendazole (B) do not antagonise SP, and ''Pholia acid'' (D) is an OCR-garbled duplicate of folic acid.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Among absolute contraindications to induction of labour are', 'Fetal compromise and previous uterine scar', 'Cephalopelvic disproportion and genital ulcers.', 'Cephalopelvic disproportion and malpresentation.', 'Active genital herpes and intrauterine fetal death.', 'C', 'Per Myles Textbook for Midwives, absolute contraindications to induction of labour are conditions where vaginal delivery is unsafe under any circumstance, notably cephalopelvic disproportion and abnormal lie/malpresentation such as transverse lie (C). Previous uterine scar (A) is a relative/caution factor, active genital herpes is a relative contraindication, and intrauterine fetal death (D) is actually an indication for induction.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In monozygotic twinning, splitting after twelfth (12th ) day of fertilization is highly associated with 17', 'Fetal papyraceous', 'Premature birth', 'Siamese twin', 'Diamniotic twin', 'C', 'Per Myles Textbook for Midwives, the timing of the split in monozygotic twinning determines the outcome; incomplete division of the embryonic disc after the 12th-13th day produces conjoined (Siamese) twins (C). Earlier splitting gives diamniotic-dichorionic, diamniotic-monochorionic or monoamniotic twins, so premature birth (B), diamniotic twin (D) and fetus papyraceous (A) are not the specific association with late splitting.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinical diagnosis of Polyhydramnious is based on an amount of amniotic fluid exceeding', '1500 ml', '3000 ml', '1900 ml', '2500 ml', 'D', 'Per Myles Textbook for Midwives, normal amniotic fluid at term is 500-1500 ml and polyhydramnios is diagnosed when the volume is excessive (classically exceeding ~2000-2500 ml); the value the fluid must EXCEED to be pathological is best represented by 2500 ml (D). Option A (1500 ml) is only the upper limit of normal, not an excessive amount, so keying it as the diagnostic threshold understates the definition.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A characteristic of monozygotic twins is that', 'They are always of the same sex', 'They share a similar fingerprint pattern', 'They have different blood groups', 'Superfetation is a common finding', 'A', 'Per Myles Textbook for Midwives, monozygotic (identical) twins arise from one fertilised zygote and share an identical genotype, so they are always of the same sex (A) and same blood group. Fingerprint patterns differ (B/false), blood groups are the same not different (C false), and superfetation (D) is a rare unrelated phenomenon.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Postmaturity is pregnancy equal to or more than', '38 completed weeks', '42 completed weeks', '40 completed weeks', '36 completed weeks', 'B', 'Per WHO and Myles Textbook for Midwives, post-maturity (post-term/prolonged pregnancy) is defined as a gestation of 42 completed weeks (294 days) or more from the first day of the LMP. 40 weeks (C) is term, 38 weeks (A) is early term, and 36 weeks (D) is late preterm.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In marginal cephalopelvic disproportion', 'All the patients will need an operative delivery.', 'Half of the patients will need an operative delivery.', 'The problem is always overcome during labour.', 'The pelvis too is small for the fetus to pass through.', 'B', 'Per Myles Textbook for Midwives, in marginal (borderline) cephalopelvic disproportion the outcome is uncertain, so a trial of labour is offered; roughly half of such women deliver vaginally while about half require operative (caesarean) delivery (B). It is not true that all need operative delivery (A) or that it always resolves (C), and the pelvis is only marginally, not absolutely, too small (D).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A cause of shoulder presentation is', 'Macerated fetus', 'Postdates pregnancy', 'Oligo hydramnious', 'Placenta abruption', 'A', 'Per Myles Textbook for Midwives, shoulder presentation (transverse lie) results from factors that allow abnormal lie, including a dead macerated fetus with loss of tone (A), lax multiparous uterus, placenta praevia, polyhydramnios and multiple pregnancy. Oligohydramnios (C) and post-dates (B) tend to fix a stable longitudinal lie, and placental abruption (D) is unrelated to lie.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The presenting diameter in brow presentation is 20', 'Submentobregmantic', 'Suboccipitofrontal', 'Occipitalfrontal', 'Mentovertical', 'D', 'Per Myles Textbook for Midwives, in brow presentation the head lies midway between flexion and extension, presenting the mentovertical diameter (~13.5 cm), the largest antero-posterior diameter of the fetal skull, which cannot engage a normal pelvis. Suboccipitofrontal (B) and occipitofrontal (C) belong to vertex presentations and submentobregmatic (A) to face presentation.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('On vaginal examination, the findings characteristic of brow presentation include', 'Presenting diameter is submento-vertical 11.5cm, head partially extended', 'Back difficult to palpate, foetal heart heard on the same side as the limbs', 'Presenting diameter is mentovertical 13.5cm, heard partially extended', 'Presenting diameter is mento-vertical 13.5cm, heard completely extended', 'C', 'Per Myles Textbook for Midwives, brow presentation is partial extension of the fetal head giving a presenting mentovertical diameter of 13.5 cm (C), and on vaginal examination the orbital ridges, root of nose and anterior fontanelle are felt. Full/complete extension (D) would be a face presentation, and the 11.5 cm submento-vertical figure (A) is incorrect for a brow.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In breech delivery, the midwife is advised to keep her hands off the breech as it progressively descends so as to', 'Ascertain the fetal wellbeing in utero', 'Allow enough room for the fetus to pass', 'Allow gravitating descent of the fetus', 'Prevent excessive traction being applied', 'D', 'Per Myles Textbook for Midwives, the ''hands off the breech'' principle avoids premature handling or traction that provokes extension of the fetal head and nuchal (extended) arms; allowing spontaneous descent keeps the head flexed. The main reason is to prevent excessive traction being applied (D); gravitating descent (C) and room for the fetus (B) are not the underlying rationale and fetal wellbeing (A) is assessed separately.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The presenting diameters in face presentation are', 'Submentovertival, bitemporal', 'Submentobregmatic, bitemporal', 'Submentobregmatic, biparietal', 'Mentovertical, bitemporal', 'B', 'Per Myles Textbook for Midwives, in a fully extended head (face presentation) the presenting diameters are the submentobregmatic (9.5 cm) antero-posteriorly and the bitemporal (8.2 cm) transversely (B). Mentovertical (D) is a brow diameter, biparietal (C) is the transverse vertex diameter, and ''submentovertical'' (A) is a misnomer.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term used to describe the situation whereby there is presence of more than one part of the fetus on the pelvic brim at the onset of labour is', 'Unstable lie', 'Foetal malpresentation', 'Foetal malposition', 'Compound presentation', 'D', 'Per Myles Textbook for Midwives, compound presentation is when more than one fetal part (e.g. a hand alongside the head) presents at the pelvic brim simultaneously at the onset of labour (D). Unstable lie (A) is a changing lie before labour, malpresentation (B) and malposition (C) are broader/other categories.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Post maturity is a term that is used to describe a pregnancy that is equal to or more than', '40 completed weeks', '38 completed weeks', '41 completed weeks', '42 completed weeks', 'D', 'Per WHO and Myles Textbook for Midwives, post-maturity (prolonged/post-term pregnancy) is a gestation equal to or more than 42 completed weeks (D). 40 (A), 38 (B) and 41 (C) completed weeks all fall within the term/early post-dates range and do not meet the definition.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A foetal associated risk of prolonged pregnancy includes', 'Foetal macrosomia', 'Placental dysfunction', 'Caesarean section', 'Shoulder dystocia', 'D', 'Per Myles Textbook for Midwives, prolonged pregnancy leads to fetal macrosomia which predisposes to shoulder dystocia (D), a direct intrapartum fetal complication, alongside meconium aspiration and stillbirth. Placental dysfunction (B) is a placental/cause factor, and caesarean section (C) is an intervention rather than a fetal risk.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Arrested active phase of labour in a multiparous woman denotes an abnormal labour pattern as characterized by', 'Cessation of cervical dilatation for more than 2 hours', 'Cessation of cervical dilatation for more than 4 hours', 'Duration of latent phase of labour lasting more than 8 hours', 'Cessation of descent of the presenting part for more than 1 hour', 'A', 'Per WHO labour care/partograph guidance and Myles Textbook for Midwives, arrest of the active phase is defined as cessation of cervical dilatation for 2 hours or more despite adequate uterine contractions (A). Four hours (B) is too long a criterion, a latent phase over 8 hours (C) describes prolonged latent phase not active-phase arrest, and 1 hour of arrested descent (D) is not the active-phase dilatation criterion.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Uterus hypotonicity is likely to lead to prolonged labour due to', 'Incoordination of the uterus muscle fibres during a contraction', 'Maternal exhaustion because of improper preparation for labour', 'Weak receptors thus not strong enough to signal enough contraction', 'Inadequate pelvis thus not able to stimulate enough uterine contractions', 'C', 'Per Myles Textbook for Midwives, hypotonic uterine action is a coordinated (fundal-dominant) but weak contraction pattern with low resting tone and insufficient force to progress labour. Of the options, weak signalling producing contractions that are not strong enough (C) best fits this weakness; incoordination (A) describes hypertonic/incoordinate action, and maternal exhaustion (B) and an inadequate pelvis (D) are not the intrinsic cause of hypotonicity.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Obstructed labour MAINLY results due to', 'Maternal exhaustion', 'Cephalopelvic disproportion', 'Microsomic foetus', 'Foetal exsanguination', 'B', 'Per Myles Textbook for Midwives and Kenya MOH obstetric guidelines, obstructed labour occurs when the presenting part cannot descend despite good uterine contractions, and the commonest cause is cephalopelvic disproportion (B), together with malpresentation. Maternal exhaustion (A) is a consequence, a microsomic (small) fetus (C) would ease passage, and fetal exsanguination (D) is unrelated.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Trial of scar is likely to have an auspicious outcome in/if the', 'Estimated fetal weight is below 3500 grams', 'Maternal body mass index is estimated at 27.5', 'Gestational age is approximately 42 weeks', 'Maternal age is approximately 42 years', 'A', 'Per Myles Textbook for Midwives and MOH VBAC guidance, a trial of scar is most likely to succeed when the fetus is of average, non-macrosomic size, e.g. estimated fetal weight below 3500 g (A). A high BMI (B), post-term gestation of 42 weeks (C) and advanced maternal age (D) all reduce the likelihood of a successful trial of labour after caesarean.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A complication that is associated with breech delivery is', 'Compression of cord', 'Neonatal cephalhaematoma', 'Pathological jaundice', 'Abruption placentae', 'A', 'Per Myles Textbook for Midwives, in breech delivery the after-coming cord is compressed between the fetal head and the maternal pelvis during descent, risking hypoxia, making cord compression (A) a recognised complication. Cephalhaematoma (B) and pathological jaundice (C) are not specific to breech, and abruptio placentae (D) is an antepartum event unrelated to the mechanism of breech birth.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Prior to taking a patient for an emergency caesarean section, it is MOST important to assess that', 'A signed informed consent has been given', 'A Foley''s catheter has been inserted.', 'An intravenous line has been started', 'The perineal area has been shaved adequately.', 'A', 'Per Kenyan nursing/surgical practice standards and Kozier''s Fundamentals of Nursing, before any operation including emergency caesarean section the most important check is a valid, signed informed consent (A), the key legal and ethical prerequisite. Foley catheter (B), IV line (C) and perineal shaving (D) are important preparatory steps but are secondary to consent.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following fetal positions is associated with intense back pain during labour?', 'Occipito- anterior', 'Transverse position', 'Occipito- posterior', 'Occipito- lateral', 'C', 'Per Myles Textbook for Midwives, in the occipito-posterior position the fetal occiput presses on the maternal sacrum, producing intense, continuous low back pain (''backache labour'') (C). Occipito-anterior (A) is the favourable position with less back pain, and transverse (B)/occipito-lateral (D) do not classically cause this sacral backache.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Intraperitoneal uterine rupture involves', 'A tear of endometrium, myometrium & peritoneum', 'A tear of the endometrium, myometrium & basal laye', 'A tear of the endometrium, capsular layer & myometrium', 'A tear of the endometrium, spongy layer & myometrium only', 'A', 'Per Myles Textbook for Midwives, a complete (intraperitoneal) uterine rupture is a tear through the full thickness, endometrium, myometrium and the peritoneum (perimetrium), opening into the peritoneal cavity (A). An incomplete rupture leaves the peritoneum intact, so the options citing basal/capsular/spongy layers (B, C, D) are incorrect descriptions.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following statements is CORRECT with regards to precipitate delivery?', 'May lead to uterine atony due to the moderate contractions experienced by client', 'Puerperal sepsis is likely to result from unhygienic measures inco-oporated post-natally', 'With adequate monitoring of the prenatal mother, precipitate delivery minimally recurs', 'May cause cervical lacerations because of rapid descent and delivery of the baby', 'D', 'Per Myles Textbook for Midwives, precipitate labour (delivery in under 3 hours from strong tumultuous contractions) causes rapid fetal descent that can lacerate the cervix, vagina and perineum (D), and also risks PPH from subsequent atony. Option A is wrong because contractions are vigorous, not moderate; B and C are not the defining correct statements.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A mother with a cord prolapse is given oxygen at a rate of 4 litres/minute in order to 29', 'Relieve maternal distress', 'Promote her relative rest', 'Improve the fetal oxygenation', 'Achieve the effect of tocolysis', 'C', 'Per Myles Textbook for Midwives, in cord prolapse the compressed cord compromises fetal oxygen supply; giving the mother oxygen raises her oxygen saturation and thus improves oxygen delivery to the fetus (C) while urgent delivery is arranged. It is not primarily to relieve maternal distress (A), promote rest (B) or achieve tocolysis (D).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is a characteristic of fetal post-maturity syndrome?', 'Closed eyes, unusually alert', 'Long, frail finger nails', 'Wrinkled, peeling skin', 'Excess vernix caseosa', 'C', 'Per Myles Textbook for Midwives, post-maturity syndrome features dry, cracked, wrinkled and peeling skin (C), long finger nails, reduced or absent vernix, meconium staining and an alert ''old-man'' facies. Vernix is diminished not excess (so D is wrong), and the eyes are open and alert rather than closed (A).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A Para 3+0 client who was scheduled for the fourth caesarean section comes in active labour. The MAIN complication of concern in this case is', 'Placenta abruption.', 'Rupture of the uterus.', 'Prolonged labour.', 'Precipitate labour.', 'B', 'Per Myles Textbook for Midwives and Kenya MOH obstetric guidelines, a para 3 woman with three previous caesarean scars now in active labour is at high risk of rupture of the previous uterine scar (B), the main and most life-threatening complication. Abruption (A), prolonged (C) and precipitate (D) labour are not the principal scar-related concern here.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is declared fit for a vaginal birth after caesarean section if', 'Her previous C/S was due to cephalopelvic disproportion.', 'The current pregnancy is confirmed a multiple pregnancy.', 'Previous delivery was via caesarean section.', 'Previous delivery was via spontaneous vertex delivery.', 'D', 'Per Myles Textbook for Midwives, a woman is judged favourable for VBAC when she has had a previous successful spontaneous vaginal delivery (D) and the prior caesarean cause was non-recurrent. A previous CS for cephalopelvic disproportion (A) is a recurrent indication reducing suitability, and a current multiple pregnancy (B) also reduces suitability.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In deep transverse arrest,', 'The occipito-frontal diameter is caught at the bispinous diameter of the pelvic outlet.', 'The sub-occipito-bregmatic diameter is caught at the bispinous diameter of pelvic outlet.', 'The resulting outcome is usually a face to pubis delivery.', 'The sagittal suture is found at the oblique diameter of the pelvis.', 'B', 'Per Myles Textbook for Midwives, deep transverse arrest is failure of internal rotation from an occipito-posterior position, so the well-flexed head (suboccipitobregmatic diameter) becomes arrested with the sagittal suture lying in the transverse (bispinous) diameter of the pelvic cavity/outlet (B). Occipito-frontal caught transversely (A), a face-to-pubis outcome (C) and an oblique sagittal suture (D) do not describe deep transverse arrest.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The type of a cord prolapse characterized by presence of the fetal umbilical cord alongside the presenting part is', 'Occult umbilical cord prolapse', 'Overt umbilical cord prolapse', 'Funic cord prolapse', 'Complete cord prolapse', 'A', 'Per Myles Textbook for Midwives, occult cord prolapse (option A) is when the umbilical cord lies alongside — but not in front of — the presenting part. The cord is compressed between the fetus and the maternal pelvis but is not visible or palpable on vaginal examination. Overt cord prolapse (option B) is when the cord descends below or in front of the presenting part after rupture of membranes and is palpable or visible in the vagina or at the vulva. Funic presentation (option C) is the cord lying in front of the presenting part with intact membranes. ''Complete'' (option D) is not a standard classification term for cord prolapse.', 'KRCHN', 'Paper I', 'Midwifery', 'Obstetric Emergencies', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is involved in the management of cord prolapse?', 'Placing client on all fours position', 'Application of fundal pressure', 'Placing client on Trendelenburg position', 'Labour augmentation using oxytocin regimen', 'C', 'Per Myles Textbook for Midwives, management of cord prolapse aims to relieve cord compression by placing the mother head-down (Trendelenburg, exaggerated Sims or knee-chest) position (C), elevating the presenting part and expediting delivery. Fundal pressure (B) and oxytocin augmentation (D) are contraindicated, and the all-fours position (A) is used for shoulder dystocia.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A maternal cause of shoulder presentation includes', 'A sub-septate uterus.', 'Oligohydramnios.', 'Prematurity.', 'Multiple pregnancy.', 'A', 'Per Myles Textbook for Midwives, maternal causes of shoulder presentation (transverse lie) are uterine and pelvic abnormalities such as a subseptate/bicornuate uterus (A), lax multiparous uterus, placenta praevia and contracted pelvis. Oligohydramnios (B), prematurity (C) and multiple pregnancy (D) are fetal/adnexal rather than maternal structural causes.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The presenting diameter in brow presentation is', 'Mentovertical.', 'Submentobregmantic.', 'Suboccipitofrontal.', 'Occipitalfrontal.', 'A', 'Per Myles Textbook for Midwives, in brow presentation the head is partially extended and the presenting diameter is the mentovertical (~13.5 cm) (A), too large to engage a normal pelvis. Submentobregmatic (B) belongs to face presentation, and suboccipitofrontal (C)/occipitofrontal (D) belong to vertex presentations.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Delivery of the head in a breech presentation is usually accomplished through', 'Lovset maneuver.', 'Burns Marshal Method.', 'Mauriceau-smellie veit manoeuvre.', 'Reverse woodscrew manoeuvre.', 'C', 'Per Myles Textbook for Midwives, the after-coming head in breech delivery is delivered by the Mauriceau-Smellie-Veit manoeuvre (jaw flexion and shoulder traction) (C) or the Burns-Marshall method. The Lovset manoeuvre (A) delivers extended arms/shoulders, and the reverse woodscrew (D) is used for shoulder dystocia.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When a hand or foot, lies alongside the presenting part, the presentation is said to be', 'Footling.', 'Transverse.', 'Cephalic.', 'Compound.', 'D', 'Per Myles Textbook for Midwives, when a hand or foot lies alongside the presenting part the presentation is termed compound (D). Footling (A) is a breech variant with the foot as the sole presenting part, transverse (B) refers to lie, and cephalic (C) is a normal head presentation.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Precipitate labour is an unusually rapid labour', 'Where the external cervical os fails to dilate despite good uterine contractions.', 'That is concluded in more than three hours.', 'That is concluded in less than three hours.', 'Where the external cervical os fails to dilate due to poor uterine contractions.', 'C', 'Per Myles Textbook for Midwives, precipitate labour is unusually rapid labour completed in less than 3 hours from onset of contractions to delivery (C), caused by strong frequent contractions meeting little soft-tissue resistance. Failure of the os to dilate (A, D) describes obstructed/hypotonic labour, and ''more than three hours'' (B) is the opposite of precipitate.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A circumscribed swelling on the newborn''s scalp is indicative of', 'Caput succedaneum', 'Subgaleal haemorrhage', 'Intracranial injury', 'Neonatal cephalhaematoma', 'D', 'Per Myles Textbook for Midwives, a cephalhaematoma is a circumscribed, well-demarcated subperiosteal swelling that does not cross suture lines and appears within hours of birth (D). Caput succedaneum (A) is a diffuse, non-circumscribed oedematous swelling that crosses sutures, subgaleal haemorrhage (B) is diffuse and boggy, and intracranial injury (C) is not a scalp swelling.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Acute inflammatory mastitis can be prevented postnatally by encouraging breastfeeding mothers to', 'Use prophylactic antibiotics', 'Use braziers of the right size', 'Wash the breasts thoroughly before breastfeeding', 'Empty the breast completely when breastfeeding', 'D', 'Per WHO/Kenya breastfeeding guidance and Myles Textbook for Midwives, acute mastitis usually arises from milk stasis with infection, so prevention centres on frequent effective breastfeeding with complete emptying of the breast (D), good attachment and prompt treatment of cracked nipples. Prophylactic antibiotics (A), correct bra size (B) and pre-feed breast washing (C) are not the key preventive measures.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Complications of deep venous thrombosis include', 'Pulmonary embolism, varicosity', 'Moist gangrene, secondary post partum haemorrhage', 'Hydronephrosis, haematoma formation', 'Prolonged labour, disseminated intravascular coagulopathy', 'A', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, the major complication of deep venous thrombosis is pulmonary embolism from an embolised clot, with later chronic venous insufficiency and varicosities/post-thrombotic syndrome (A). The other options pair unrelated conditions (moist gangrene, hydronephrosis, prolonged labour, DIC) that are not direct DVT complications.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Icterus gravis and hydrops fetalis are conditions highly associated with', 'Rhesus D incompatibility', 'ABO incompatibility', 'Physiological jaundice', 'Instant perinatal death', 'A', 'Icterus gravis neonatorum and hydrops fetalis are the severe forms of haemolytic disease of the newborn caused by maternal anti-D antibodies crossing the placenta to a Rh-D positive fetus (Rhesus D isoimmunisation), per Myles Textbook for Midwives. ABO incompatibility (B) causes a much milder, self-limiting jaundice and not hydrops; physiological jaundice (C) is benign; instant perinatal death (D) is an outcome, not the association.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Aims of exchange transfusion procedure includes', 'Cure of haemolysis and restoration of haemoglobin level', 'Cure of hypoxia and removal of all toxic materials', 'Stabilisation of baby''s immune system and liver functions', 'Control of haemolysis and restoration of haemoglobin level', 'D', 'Exchange transfusion in haemolytic disease of the newborn removes circulating maternal antibodies and bilirubin, controls ongoing haemolysis and restores haemoglobin, per Myles Textbook for Midwives. It does not cure haemolysis (the underlying antibody-mediated process continues until sensitised cells clear), so option A (''cure of haemolysis'') is inaccurate; B and C misstate its purpose. ''Control of haemolysis and restoration of haemoglobin'' is the precise aim.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The earliest onset of cephalohaematoma is', 'Six hours postnatally', 'Twelve hours postnatally', 'Eighteen hours postnatally', 'Immediately after birth', 'B', 'Cephalhaematoma is a subperiosteal collection of blood that, unlike caput succedaneum, is NOT present at birth; it appears some hours after delivery and enlarges over the first 12-24 hours as bleeding accumulates, per Myles Textbook for Midwives. ''Immediately after birth'' (D) is therefore wrong and is the very feature distinguishing it from caput; among the timed options twelve hours postnatally best represents its recognised onset.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Use of bed cradle in the management of leg thrombosis is meant to', 'Keep the legs straight', 'Prevent embolism', 'Control body temperature', 'Promote venous drainage.', 'A', 'A bed cradle keeps the weight of the bedclothes off the affected limb in leg (deep vein) thrombosis, keeping the leg straight, supported and immobile to reduce discomfort and avoid dislodging the clot, per Myles Textbook for Midwives. It does not itself prevent embolism (B — that requires anticoagulation), control temperature (C) or promote venous drainage (D — elevation does that).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following birth trauma results from damage of cervical nerve root 5 & 6?', 'Erb''s palsy', 'Radial palsy', 'Brachial palsy', 'Facial palsy', 'A', 'Erb''s (Erb-Duchenne) palsy results from injury to the upper brachial plexus roots C5 and C6, producing the classic ''waiter''s tip'' posture, per Myles Textbook for Midwives. Klumpke''s (not listed) affects C8-T1; radial palsy (B) and facial palsy (D) involve different nerves; ''brachial palsy'' (C) is too non-specific for the C5-C6 lesion described.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Psychosis during puerperium mostly manifests as', 'Mania', 'Bipolar', 'Depression', 'Infection', 'C', 'Puerperal psychosis most commonly manifests with a severe affective disturbance, predominantly of depressive type (though manic and mixed presentations occur), per Myles Textbook for Midwives and standard mental-health nursing texts. ''Bipolar'' (B) and ''mania'' (A) are components/subtypes rather than the commonest manifestation, and ''infection'' (D) is unrelated to psychosis. Depression best fits.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Non-infective mastitis is associated with', 'Cellulitis', 'Flat nipples', 'Bifid nipples', 'Adenitis', 'A', 'Non-infective (inflammatory) mastitis arises from milk stasis causing localised inflammation/cellulitis of the breast tissue before any infection is established, per Myles Textbook for Midwives. Flat (B) and bifid (C) nipples predispose to poor attachment but are not the inflammatory process itself, and adenitis (D) denotes lymph-node infection. Cellulitis is the associated feature.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An oedematous swelling on the newborn''s scalp is indicative of 37', 'Caput succedaneum', 'Subgaleal haemorrhage', 'Intracranial injury', 'Neonatal cephalhaematoma', 'A', 'Caput succedaneum is a diffuse, soft, pitting oedematous swelling of the scalp caused by pressure of the presenting part against the dilating cervix; it crosses suture lines and resolves within days, per Myles Textbook for Midwives. The ''oedematous'' quality distinguishes it from the firm, suture-bounded cephalhaematoma (D); subgaleal haemorrhage (B) is a boggy fluctuant blood collection and intracranial injury (C) causes neurological signs, not a simple scalp swelling.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Respiratory distress syndrome is caused by', 'Poor quality of surfactant', 'Inadequate surfactant levels', 'Rib cage underdevelopment', 'Gradual alveolar rupture', 'B', 'Neonatal respiratory distress syndrome (hyaline membrane disease) results from inadequate quantity of pulmonary surfactant due to prematurity, causing alveolar collapse, per Kenya Basic Paediatric Protocols and Myles Textbook for Midwives. It is chiefly a deficiency (quantity) problem, so ''inadequate surfactant levels'' is more accurate than ''poor quality'' (A); rib-cage underdevelopment (C) and alveolar rupture (D) are not the cause.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinical features of intracranial injury includes', 'Limpness, bruises and hypothermia', 'Irritability, hypoxia and paralysis', 'Hypothermia, limpness and irritability', 'Hypocalcaemia, paralysis and hypoxia', 'C', 'Neonatal intracranial (birth) injury/haemorrhage presents with irritability, limpness/hypotonia and temperature instability (hypothermia), along with poor feeding and convulsions, per Myles Textbook for Midwives. Option C (''hypothermia, limpness and irritability'') captures these recognised signs best; the other combinations mix in bruises, hypocalcaemia or paralysis that are not the characteristic triad.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An in-organic risk factor to birth injuries includes', 'Maternal short stature', 'Prenatal oligohydramnios', 'External cephalic version', 'Foetal macrosomia', 'C', 'An ''in-organic'' (non-biological, i.e. procedural/mechanical) risk factor for birth injury is an intervention such as external cephalic version, per Myles Textbook for Midwives. Maternal short stature (A), oligohydramnios (B) and fetal macrosomia (D) are organic (maternal/fetal biological) factors, leaving the manipulative procedure as the in-organic cause.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A specific clinical feature of respiratory distress syndrome includes', 'Grunting on inspiration', 'Grunting on expiration', 'Flaring of the nostrils', 'Neonatal tachycardia', 'B', 'Expiratory grunting is the specific hallmark of neonatal respiratory distress syndrome, produced as the infant partially closes the glottis on expiration to maintain end-expiratory lung volume against surfactant deficiency, per Kenya Basic Paediatric Protocols. Grunting occurs on expiration not inspiration (A); nasal flaring (C) and tachycardia (D) are non-specific signs of respiratory distress generally.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is an endogenous cause of puerperal sepsis?', 'Chlamydia trachomatis', 'Escherichia coli', 'Chlostridium tetani', 'Pseudomonas aeruginosa', 'B', 'Endogenous puerperal sepsis arises from the woman''s own commensal genital/bowel flora, notably Escherichia coli, per Myles Textbook for Midwives. Chlamydia trachomatis (A), Clostridium tetani (C) and Pseudomonas aeruginosa (D) are exogenous organisms introduced from outside the patient, so E. coli is the endogenous cause.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The MAIN clinical feature of puerperal psychosis is', 'Episodic insomnia', 'Neglect of hygiene', 'Major depression', 'Mild headache', 'C', 'The main clinical feature of puerperal psychosis is a severe (major) depressive/affective disturbance, frequently with psychotic features, per Myles Textbook for Midwives. Episodic insomnia (A), neglect of hygiene (B) and mild headache (D) are secondary or non-specific, whereas major depression is the predominant presentation.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The MAIN aim of encouraging plenty of fluids to a postnatal client with urinary tract trauma is to', 'Control growth of organisms', 'Keep client well hydrated', 'Main proper fluid balance', 'Facilitate proper healing', 'A', 'Encouraging plenty of oral fluids in a postnatal woman with urinary tract trauma promotes a good dilute urine output that flushes the bladder and urethra, mechanically washing out bacteria; the MAIN aim is to prevent/control infection (growth of organisms), per Myles Textbook for Midwives. Good hydration (B), fluid balance (C) and healing (D) are secondary benefits rather than the principal aim.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The neonatal birth injury that results due to bleeding between the epicranial aponeurosis and the periosteum is', 'Caput succedaneum', 'Intracranial haemorrhage', 'Subgaleal haemorrhage', 'Aponeurotic haemorrhage', 'C', 'Bleeding between the epicranial (galea) aponeurosis and the periosteum is a subgaleal (subaponeurotic) haemorrhage, which can cross suture lines and cause dangerous blood loss, per Myles Textbook for Midwives. Caput succedaneum (A) is oedema not blood in this plane, cephalhaematoma is subperiosteal (below periosteum), and ''aponeurotic haemorrhage'' (D) is not the recognised term.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Neonatal injury to nerve roots C8 & T1 causes one of the following', 'Erb''s palsy', 'Klumpke''s palsy', 'Phrenic injury', 'Radial palsy', 'B', 'Injury to the lower brachial plexus roots C8 and T1 produces Klumpke''s palsy (''claw hand'') affecting the intrinsic hand muscles, per Myles Textbook for Midwives. Erb''s palsy (A) involves the upper roots C5-C6; phrenic nerve injury (C) affects the diaphragm; radial palsy (D) is a different peripheral lesion.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Kleihauser acid solution test is recommended in the management of', 'Moderate physiological jaundice', 'Hemolytic jaundice prenatally', 'Severe hepatospleenomegally', 'Hemolytic jaundice postnatally', 'D', 'The Kleihauer(-Betke) acid-elution test detects and quantifies fetal red cells in the maternal circulation (feto-maternal haemorrhage) to guide anti-D dosing in Rhesus isoimmunisation, which produces haemolytic disease/jaundice recognised after birth, per Myles Textbook for Midwives. Of the options, haemolytic jaundice postnatally best fits; physiological jaundice (A) and hepatosplenomegaly (C) are unrelated to the test, and it is not a prenatal jaundice test per se (B).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A neonate whose birth weight is 1201 grams is regarded as', 'Genetically small neonate', 'Low birth weight neonate', 'Very low birth weight neonate', 'Extremely low birth weight', 'C', 'Per WHO/Kenya Basic Paediatric Protocols weight bands (LBW <2500g, VLBW <1500g, ELBW <1000g), a birth weight of 1201g falls below 1500g but above 1000g and is therefore very low birth weight. It is not simply low birth weight (B, which would be 1500-2499g) nor extremely low (D, <1000g).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Laryngeal stridor as a congenital abnormality is caused by', 'Choanal atresia', 'Laryngomalacia', 'Diaphragmatic hernia', 'Hirschsprung''s disease', 'B', 'Congenital laryngeal stridor is most commonly caused by laryngomalacia, softening/floppiness of the supraglottic laryngeal cartilages that collapse inward on inspiration, per standard paediatric texts and Kenya Basic Paediatric Protocols. Choanal atresia (A) causes nasal obstruction not stridor; diaphragmatic hernia (C) and Hirschsprung''s disease (D) do not produce laryngeal stridor.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Predisposing factors to vitamin K deficiency bleeding include', 'Postdatism, prematurity', 'Asphyxia, congenital abnormalities', 'Prematurity, hypoxia', 'Hypoxia, congenital abnormalities', 'C', 'Vitamin K deficiency bleeding of the newborn is predisposed by prematurity (immature liver and poor stores) and hypoxia/perinatal stress, alongside exclusive breastfeeding and lack of prophylaxis, per Kenya Basic Paediatric Protocols. Options pairing postdatism (A) or congenital abnormalities (B, D) are not the recognised predisposing factors; ''prematurity, hypoxia'' is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main feature in the initial stage of shock is', 'Cyanosis', 'Tachycardia', 'Sweat beads', 'Hypotension', 'B', 'In the initial (compensated) stage of shock the earliest sign is tachycardia, driven by sympathetic activation to maintain perfusion, per Brunner & Suddarth''s Medical-Surgical Nursing. Hypotension (D) and cyanosis (A) are late decompensated signs, and sweating (C) is non-specific; tachycardia is the main early feature.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In uterine inversion, the last part to be replaced is the', 'Cervix', 'Fundus', 'Isthmus', 'Body', 'B', 'In manual replacement of an inverted uterus, the part that inverted last (the fundus) is the last to be replaced; the cervix/lower segment is corrected first and the fundus is pushed back up last, per Myles Textbook for Midwives. Cervix (A), isthmus (C) and body (D) are restored before the fundus.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Greatly reduced eliminations and red rosy appearance of face are among the features of', 'Hypothermia neonatorum', 'Hypoglycaemia neonatorum', 'Hyperthermia neonatorum', 'Hypocalcaemia neonatorum', 'C', 'Greatly reduced eliminations (oliguria from dehydration) with a flushed, red rosy face are features of neonatal hyperthermia/overheating, per Myles Textbook for Midwives. Hypothermia (A) instead gives pallor, central cyanosis and cool skin; hypoglycaemia (B) and hypocalcaemia (D) present with jitteriness/seizures, not a flushed face. Hyperthermia neonatorum fits.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The birth weight of a very low birth weight baby ranges between', '1000- 500 gm', '500-1500 gm', '1001-1500 gm', '1500-2000 gm', 'C', 'Very low birth weight is a birth weight below 1500g, i.e. the 1000-1499g band, so ''1001-1500 gm'' is the correct option, per WHO/Kenya Basic Paediatric Protocols. Options A (''1000-500 gm'') and B (''500-1500 gm'') are mis-ordered/too wide and D (1500-2000 gm) falls in the low-birth-weight range.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The gradual rewarming process in the management of hypothermia neonatorum is aim at', 'Providing energy', 'Preventing shock', 'Providing comfort', 'Preventing burns', 'B', 'A hypothermic neonate is rewarmed gradually because rapid rewarming causes peripheral vasodilatation, a fall in blood pressure and rewarming shock (with apnoea and hypoglycaemia), per Kenya Basic Paediatric Protocols and Myles. Slow, controlled rewarming prevents this cardiovascular collapse; providing energy (A), comfort (C) or preventing burns (D) are not the primary aim.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Teratogenic causes of congenital abnormalities includes', 'Medical conditions and pesticides', 'Prescription drugs and chromosomes', 'Radiation and substances of abuse', 'Disordered genes and medical conditions', 'C', 'Teratogens are external environmental agents; radiation and substances of abuse (alcohol, drugs) are classic teratogenic causes of congenital abnormality, per Myles Textbook for Midwives. Options invoking chromosomes (B) and disordered genes (D) describe genetic (not teratogenic) causes, and A mixes in maternal medical conditions; radiation and substances of abuse is the clean teratogenic pair.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('McEwen sign is associated with', 'Hydrocephalus', 'Myelomeningocele', 'Microcephaly', 'Encephalocele', 'A', 'Macewen''s (McEwen) sign, a ''cracked-pot'' resonance on percussion of the skull, is associated with hydrocephalus and raised intracranial pressure with separated sutures, per standard paediatric neurology texts. Myelomeningocele (B), microcephaly (C) and encephalocele (D) do not produce this percussion sign.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The congenital abnormality of the respiratory tract, associated with abnormal apical position is', 'Laryngeal stridor', 'Diaphragmatic hernia', 'Choanal atresia', 'Tracheo-bronchi fistula', 'B', 'Congenital diaphragmatic hernia allows abdominal contents into the thorax, shifting the mediastinum and displacing the cardiac apex beat to an abnormal position with associated lung hypoplasia, per standard paediatric surgical texts. Laryngeal stridor (A) and choanal atresia (C) are airway/nasal lesions, and tracheo-oesophageal fistula (D) does not typically shift the apex; the diaphragmatic hernia fits the abnormal apical position.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The baby dies immediately after birth due to presence of', 'Pulmonary stenosis', 'Aorta Coarctation', 'Trancus arteriosus', 'Ductus arteriosus', 'C', 'Truncus arteriosus is a severe cyanotic congenital heart defect causing early neonatal collapse and death from mixing of circulations and heart failure, per standard paediatric cardiology texts. Patent ductus arteriosus (D) alone is compatible with survival, and pulmonary stenosis (A) and coarctation (B) usually present later; truncus arteriosus best fits early death.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Causes of Down syndrome are', 'Trisomy, deletion and non-disjunction', 'Mosaicism, duplication and translocation', 'Translocation, mosaicism and deletion', 'Mosaicism, trisomy and translocation', 'D', 'Down syndrome (trisomy 21) arises by three mechanisms: free trisomy 21 from non-disjunction (~95%), translocation (~4%) and mosaicism (~1%), per standard genetics/paediatric texts. Option D lists all three (mosaicism, trisomy, translocation); the other options include deletion or duplication, which do not cause Down syndrome.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vitamin K prevents haemorrhagic disease of the neonate by', 'Activating the white blood cells', 'Activating the dormant clotting factors', 'Adopting a fibrinogen sparing mechanism', 'Altering the red blood cells count', 'B', 'Vitamin K is the cofactor for hepatic synthesis/activation of clotting factors II, VII, IX and X, thereby preventing haemorrhagic disease of the newborn, per Kenya Basic Paediatric Protocols. It does not act via white blood cells (A), fibrinogen sparing (C) or altering red cell count (D); it activates the vitamin-K-dependent clotting factors.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Specific management of Severe pre-eclampsia involves', 'Admission at first contact', 'Managing as an outpatient case', 'Admission in the intensive care unit', 'Encouraging plenty of oral fluids', 'A', 'Per Kenya MOH Maternal & Newborn guidelines and Myles Textbook for Midwives, severe pre-eclampsia is an obstetric emergency requiring immediate hospital admission at first contact for stabilisation with antihypertensives and magnesium sulphate prophylaxis and planned delivery. Routine ICU admission (C) is not needed for every case, and outpatient management (B) or encouraging oral fluids (D) are unsafe, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Causes of polyhydramnios includes :-', 'Congenital abnormalities and chorioangioma', 'Severe fetal hypoxia and multiple pregnancy', 'Uncontrolled diabetes mellitus and anaemia', 'Rhesus D isoimmunisation and post datism', 'A', 'Per Myles Textbook for Midwives, polyhydramnios arises when fetal swallowing is impaired by congenital anomalies (e.g. oesophageal atresia, anencephaly) and from placental chorioangioma, so option A pairs two genuine causes. Although maternal diabetes and multiple pregnancy (parts of B and C) are also recognised causes, their paired items are wrong — ''severe fetal hypoxia'' (B) and ''post-datism'' (D, which causes oligohydramnios) are not causes — so A is the only fully correct pair.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bruised and oedematous appearance of the uterus, associated with placenta abruption is collectively referred to as', 'Wernickle''s encephalopathy', 'Uterine prolapse', 'Couvelaire uterus', 'Asherman''s syndrome', 'C', 'Per Myles Textbook for Midwives, Couvelaire uterus (uteroplacental apoplexy) is the bruised, oedematous, purplish uterus caused by extravasation of blood into the myometrium in severe placental abruption. Wernicke''s encephalopathy (thiamine deficiency), uterine prolapse and Asherman''s syndrome (intrauterine adhesions) are unrelated, so C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Alice is six (6) weeks pregnant on assessment findings a nurse determines that she has gonococcal infection. The significance of this information is that gonorrhoea can', 'A. Cause spontaneous abortion.', 'B. Result in thrush in the newborn. .', 'C. Cause ophthalmia neonatorum.', 'D. Increase the risk of acquired immuno deficiency syndrome', 'C', 'Per Kenya National STI/RH guidelines and Myles, maternal gonococcal infection is transmitted to the neonate''s eyes during vaginal birth, causing ophthalmia neonatorum (gonococcal conjunctivitis), a leading preventable cause of neonatal blindness. Thrush (B) is candidal not gonococcal, and while gonorrhoea can facilitate HIV transmission (D) and other complications, the specific significance in the newborn is ophthalmia neonatorum, so C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During the first antenatal visit, urine is tested for:', 'A. Ketone and blood.', 'B. Bilirubin and urobilinogen.', 'C. Glucose and protein.', 'D. Ketones and glucose.', 'C', 'Per Kenya MOH focused antenatal care guidelines, routine urinalysis at the first ANC visit screens for glucose (gestational diabetes) and protein (pre-eclampsia/urinary tract infection). Ketones, bilirubin and urobilinogen are not the routine ANC dipstick targets, so C (glucose and protein) is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The initial management of a postnatal mother suffering from deep venous thrombosis include', 'A. Anticoagulants, restriction of movement.', 'B. Reassurance, anticoagulants.', 'C. Analgesics, exercises.', 'D. Application of crape bandage, warm compression', 'A', 'Per Myles Textbook for Midwives, initial management of postnatal deep vein thrombosis is anticoagulation (heparin/LMWH) together with bed rest, limb elevation and restriction of movement to prevent thrombus dislodgement and pulmonary embolism. Massage, exercises or applying a crepe bandage over an acute clot (C, D) are contraindicated initially, and reassurance alone (B) omits the essential anticoagulation, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The management of a patient suffering from hyperemesis gravidarum include:-', 'A. Sweetened snack, intravenous fluids four hourly, observation-of vital signs.', 'B. Reassurance, intravenous fluids four hourly, observation of vital signs.', 'C. Antacids, proping up in bed, reassurance.', 'D. Antiemetic, maintenance of fluid intake and output', 'B', 'Per Myles and Kenya MOH guidelines, hyperemesis gravidarum management centres on correcting dehydration and electrolyte imbalance with intravenous fluids, close monitoring of vital signs and fluid intake/output, and psychological reassurance while withholding oral intake until vomiting settles. A sweetened oral snack (A) is inappropriate during active vomiting, so B is the correct combination.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lactation amenorrhoea as a family planning method is effective under the following conditions:-', 'A. Baby should be below six months of age and exclusively breastfed on demand.', 'B. Baby should be six weeks of age and exclusively breastfed on demand.', 'C. Baby should be below two years and exclusively breastfed on demand.', 'D. Baby should be below one year and exclusively breastfed on demand.', 'A', 'Per Kenya National Family Planning Guidelines, the lactational amenorrhoea method is effective only when all three criteria are met: the baby is under 6 months of age, is exclusively breastfed on demand (day and night), and the mother remains amenorrhoeic. Option A states the correct age and feeding criteria; options C and D give ages beyond 6 months when LAM efficacy is lost, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The complications of a baby born of a diabetic mother include:-', 'A. Shallow irregular breathing, chest infection, polyuria.', 'B. Hypocalcemia, respiratory distress syndrome, hypoglycemia.', 'C. Vomiting, intrauterine death, hyperglycemia.', 'D. Urinary tract infection, candidiasis, hypoglycemia.', 'B', 'Per Kenya Basic Paediatric Protocols and Myles Textbook for Midwives, the infant of a diabetic mother develops hypoglycaemia (fetal hyperinsulinaemia after cutting maternal glucose supply), hypocalcaemia, and respiratory distress syndrome (hyperinsulinaemia delays surfactant/lung maturity). A, C and D are wrong: the neonate becomes HYPOglycaemic not hyperglycaemic (C), and polyuria/UTI/candidiasis are not characteristic IDM neonatal complications.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Respiratory distress syndrome is characterised by:-', 'A. Underdeveloped alveoli and deficient surfactant production.', 'B. Decreased pulmonary resistance and underdeveloped alveoli.', 'C. Inflatable alveoli and overproduction of surfactant.', 'D. Poor alveolar ventilation and pulmonary vasodilation.', 'A', 'Per Myles Textbook for Midwives and Kenya Basic Paediatric Protocols, neonatal RDS (hyaline membrane disease) arises from prematurity with underdeveloped alveoli and deficient surfactant, raising surface tension and causing alveolar collapse. B is wrong (pulmonary vascular resistance is high, not decreased, and surfactant deficiency does not decrease it), C is the opposite of the pathology (surfactant is deficient, not overproduced), and D wrongly cites pulmonary vasodilation.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The aim of testing for alpha-fetoprotein in amniotic fluid is to:-', 'A. Determine fetal maturity.', 'B. Detect neural tube defects such as spina bifida', 'C. Detect Tay-Sachs disease.', 'D. Detect respiratory distress syndrome in the newborn.', 'B', 'Per Myles Textbook for Midwives, raised alpha-fetoprotein in amniotic fluid (and maternal serum) is the marker for open neural tube defects such as spina bifida and anencephaly. AFP does not assess fetal maturity (A), does not diagnose Tay-Sachs (C, an enzyme/DNA diagnosis), and is unrelated to neonatal RDS (D, assessed by L/S ratio).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vasa praevia means that the placenta:-', 'A. Is low lying and blood vessels are likely to pass across, it and may rupture during an artificial rupture of membranes.', 'B. Has a very short foetal cord that is likely to snap with any traction or may cause an invasion of the uterus. .', 'C. Is lying at the fundus of the uterus and is likely to be retained after the baby is born.', 'D. Is centrally placed and may easily form a retroplacental clot that will speed up the separation of the placenta', 'A', 'Per Myles Textbook for Midwives, vasa praevia is where fetal blood vessels (typically velamentous cord insertion or a succenturiate lobe) run through the membranes across or near the internal os ahead of the presenting part, so they can rupture during ARM/spontaneous membrane rupture causing fatal fetal exsanguination. B describes a short cord, C describes a fundal/retained placenta, and D describes abruption features - none define vasa praevia.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Estriol testing is a urine test taken at certain intervals to determine:', 'A. Fetal maturity.', 'B. Secretion of lung surfactant in the fetus.', 'C. Chromosomal abnormalities', 'D. Uterine function.', 'D', 'Per Myles Textbook for Midwives, serial estriol assays reflect the intact fetoplacental (placental) unit, with falling levels signalling fetoplacental compromise; estriol does not test fetal maturity (A), lung surfactant (B, L/S ratio) or chromosomes (C, karyotype). Of the four listed options, D (''uterine function'') is the closest proxy for placental/fetoplacental function and is therefore the least-wrong choice.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 30 year old woman is pregnant for the third time. She has one living child and a history of abortion. A midwife would accurately record that the patient is:-', 'A. Para II gravida III', 'B. Para II gravida II', 'C. Para I+I gravida III', 'D. Para III gravida II', 'C', 'Per standard Myles obstetric record convention, gravida counts all pregnancies including the current one (3rd pregnancy = gravida III), and parity is expressed as viable births plus abortions/losses: one living child plus one abortion = Para 1+1. Thus Para I+I Gravida III (C) is correct; A/B/D miscount either gravida or the abortion component.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Baby Karo has just been delivered at 38 weeks gestation to a diabetic mother with a birth weight of 4.5 kilograms and APGAR score of 10/10 at 1 minute and 10/10 al minutes. One of the most likely complication that the baby may develop is:-', 'A. Hyperglycaemia.', 'B. Hypoglycaemia.', 'C. Hypovolemia.', 'D. Hypocalaemia.', 'B', 'Per Kenya Basic Paediatric Protocols and Myles, the macrosomic (4.5 kg) infant of a diabetic mother has fetal hyperinsulinaemia and develops hypoglycaemia within the first hours once the maternal glucose supply ceases; early feeding and blood glucose monitoring are required. Hyperglycaemia (A) is the opposite; hypovolaemia (C) is not typical; hypocalcaemia (D, mis-spelled ''hypocalaemia'') can occur but hypoglycaemia is the single MOST likely early complication.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following clients would the midwife prepare for an emergency caesarean delivery?', 'A. A woman who has a pulsating prolapsed cord.', 'B. A woman who is expecting twins.', 'C. A woman who is shouting a lot due to the strong contractions.', 'D. A woman who says she has been in labour for 24 hours.', 'A', 'Per Myles and Kenya MOH emergency obstetric (EmONC) guidelines, a pulsating (still viable) prolapsed cord with a live fetus not imminently deliverable is an indication for immediate emergency caesarean section to prevent fetal asphyxia. A twin pregnancy (B), a woman shouting with strong contractions (C), and 24 hours of labour alone (D) do not by themselves mandate emergency CS.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('By the 8th week of pregnancy a nurse midwife should expect to observe which of the following in a woman''s physical examination?', 'A. Bluish-purple colour on the cervix.', 'B. Loss of abdominal muscle tone .', 'C. Fundal height at the symphysis pubis.', 'D. Milky white discharge from the breasts', 'A', 'Per Myles Textbook for Midwives, Chadwick''s sign - a bluish-purple discolouration of the cervix and vagina from increased vascularity - is an early probable sign present by about 6-8 weeks. Loss of abdominal muscle tone (B) is late; the fundus is not palpable abdominally until about 12 weeks so it is not at the symphysis at 8 weeks (C); and milky breast discharge/colostrum (D) appears much later, not at 8 weeks.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The effects of polyhydramnios on labour are:', 'A. Prolonged labour with indigestion and prematurity', 'B. Disordered uterine action, cervical dystocia with oedema of the vulva,', 'C. Obstructed labour, uterine inertia and''hypertonic uterine action', 'D. Hypotonic uterine action, cord prolapse and post-partum haemorrhage,', 'D', 'Per Myles Textbook for Midwives, polyhydramnios overdistends the uterus causing hypotonic (poor) uterine action, predisposes to cord prolapse when the membranes rupture, and leads to atonic postpartum haemorrhage from the overstretched uterus. A/B/C are wrong: polyhydramnios is not classically associated with hypertonic/obstructed labour or cervical dystocia, and indigestion is not a labour effect.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Ms Kema who is at 30 weeks gestation suddenly experiences painless bright red vaginal bleeding. The most likely to cause of this problem is:-', 'A. Abruptio placentae.', 'B. An ectopic pregnancy.', 'C. Placenta praevia.', 'D. Twin pregnancy', 'C', 'Per Myles and Kenya MOH guidelines, painless bright-red vaginal bleeding in the late second/third trimester (here 30 weeks) is characteristic of placenta praevia. Abruptio placentae (A) causes painful bleeding with a tense/woody uterus; ectopic (B) is a first-trimester event; twin pregnancy (D) is not a cause of painless APH.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A woman who is at 32 weeks gestation, has ruptured membranes for 26 hours. The midwife would assess the woman for which of the following manifestations:-', 'A. Proteinuria.', 'B. Dependent oedema.', 'C. Elevated blood pressure.', 'D. Elevated temperature', 'D', 'Per Myles Textbook for Midwives, prolonged rupture of membranes (>18-24 hours, here 26 hours) predisposes to chorioamnionitis, so the midwife assesses for elevated temperature, maternal/fetal tachycardia and offensive liquor as signs of intrauterine infection. Proteinuria, dependent oedema and raised BP (A/B/C) are features of pre-eclampsia, not of prolonged PROM.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following manifestations in a woman who delivered 36 hours ago would lead a midwife to suspect the woman may be experiencing post-partum depression?', 'A. Expressing concern about taking the infant home.', 'B. Delaying her morning shower.', 'C. Exhibiting prolonged periods of fatigue,', 'D. Asking repeated questions about her care.', 'C', 'Per Myles and standard mental-health nursing, postpartum depression (as distinct from transient ''baby blues'') is suggested by persistent, prolonged features such as ongoing fatigue with low mood and loss of interest. Expressing concern about taking the baby home (A), delaying a shower once (B) and asking repeated care questions (D) are normal early postnatal behaviours, making prolonged fatigue (C) the best listed indicator.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A midwife observes a new mother breastfeeding her newborn. Which of the following actions would indicate to the midwife that the mother has a correct understanding of breastfeeding techniques?', 'A. Cleaning the breasts with soap and water prior to feeding the newborn.', 'B. Scheduling the newborn to feed every six hours around the clock.', 'C. Initiating the newborn''s feeding on the same breast for each feeding.', 'D. Placing the nipple and areola into the newborn''s mouth.', 'D', 'Per Myles and Kenya MOH/BFHI breastfeeding guidance, correct attachment requires the baby to take the nipple AND much of the areola into the mouth. Washing the breasts with soap (A) dries and cracks nipples, rigid 6-hourly scheduling (B) is wrong as feeding should be on demand, and always starting on the same breast (C) is incorrect as breasts should be alternated.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Complications of haemorrhoids (during pregnancy may be minimized or prevented by:-', 'A. Adequate dietary fibre.', 'B. Regular bowel habits to evacuate the colon', 'C. Adequate muscular exercises.', 'D. All of the above.', 'D', 'Per Myles Textbook for Midwives, prevention of haemorrhoids in pregnancy combines adequate dietary fibre, avoidance of constipation through regular bowel habits, and exercise/pelvic-floor activity to improve venous return - so all listed measures apply, making ''All of the above'' (D) correct. A, B and C are each individually true but incomplete.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vaginal bleeding in the first trimester may be due to:-', 'A. Ectopic pregnancy.', 'B. Abruptio placentae.', 'C. Placenta praevia.', 'D. Fetal abnormalities.', 'A', 'Per Myles and Kenya MOH guidelines, first-trimester vaginal bleeding is caused by abortion, ectopic pregnancy or molar pregnancy; of the listed options ectopic pregnancy (A) is the correct first-trimester cause. Abruptio placentae (B) and placenta praevia (C) are third-trimester (antepartum) causes, and fetal abnormalities (D) are not a typical direct cause of first-trimester bleeding.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The structure in the fetal circulation that shunts blood around the lungs is known as:-', 'A. Ductus venosus.', 'B. Ductus arteriosus.', 'C. Foramen ovale.', 'D. Ligamentum venosus.', 'B', 'Per Myles and anatomy/physiology, the ductus arteriosus shunts blood from the pulmonary artery to the aorta, bypassing the non-functioning fetal lungs. The ductus venosus (A) bypasses the liver, the foramen ovale (C) shunts blood right-to-left between the atria, and the ligamentum venosum (D) is the postnatal remnant of the ductus venosus - none shunts blood around the lungs.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A Rhesus-negative mother would need to receive Rho (D) immune globulin (Rho G AM) within 72 hours after delivery if the new born had which of the following blood test results:-', 'A. Rhesus-negative, coombs positive.', 'B. Rhesus-negative, coombs negative.', 'C. Rhesus- positive, coombs negative.', 'D. Rhesus-positive, coombs positive.', 'C', 'Per Kenya MOH/Myles guidance, anti-D (Rho D) immunoglobulin is given to a Rh-negative mother when the newborn is Rh-POSITIVE and the direct Coombs test is NEGATIVE (no sensitisation yet), to prevent isoimmunisation. Options A and B (Rh-negative baby) need no anti-D as there is no Rh incompatibility, and a positive Coombs (D) means sensitisation has already occurred, so prophylaxis is not the indicated action.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which fetal heart monitor pattern can indicate cord compression?', 'A. variable decelerations', 'B. early decelerations', 'C. bradycardia', 'D. tachycardia', 'A', 'Per Myles and standard fetal monitoring, variable decelerations (abrupt, variable-shaped, variable-timing drops in FHR) indicate umbilical cord compression. Early decelerations (B) reflect head compression and mirror contractions, bradycardia (C) is sustained low baseline, and tachycardia (D) suggests fever/hypoxia - none is the specific pattern of cord compression.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sampling of the amniotic fluid can be very useful in determining fetal lung maturity. The test used for this purpose is based on:', 'A. Bilirubin levels.', 'B. Cytology.', 'C. Creatinine levels.', 'D. Lecithin-sphingomyelin (L.S) ratio.', 'D', 'Per Myles Textbook for Midwives, fetal lung maturity is assessed on amniotic fluid by the lecithin/sphingomyelin (L/S) ratio; a ratio of 2:1 or greater indicates mature surfactant production and low RDS risk. Bilirubin (A) assesses haemolytic disease, cytology (B) and creatinine (C, a rough maturity index) do not specifically assess lung/surfactant maturity.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When cord prolapse is diagnosed during the second stage of labour, the immediate action would be to:-', 'A. Explain the condition to the mother. .', 'B. Push the presenting part up in the vagina.', 'C. Assess cervical dilatation and effacement', 'D. Examine the cord for pulsation and cover it with & sterile towel', 'D', 'Per Myles and Kenya MOH emergency obstetric care, on diagnosing cord prolapse the immediate action is to check the cord for pulsation (fetal viability) and minimise handling by keeping it warm/moist (cover with a sterile towel) while relieving compression and preparing for urgent delivery. Explaining to the mother (A) and assessing dilatation (C) delay action, and pushing the presenting part up (B) is done to relieve compression but not the single defined immediate step described here.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Placenta preavia is also referred as unavoidable haemorrhage because', 'A. Bleeding results as the segment separations for true labour', 'B. Bleeding results from pathological processes of the placenta', 'C. Bleeding always occurs after a gestation of 37 complete weeks', 'D. Of the high morbidity and mortality rate to the mother and neonate', 'A', 'Per Myles Textbook for Midwives, placenta praevia is termed ''unavoidable'' (inevitable) haemorrhage because as the lower uterine segment stretches and forms in late pregnancy and true labour, the abnormally sited placenta inevitably separates from the segment and bleeds - a process that cannot be prevented. B (pathological placental process), C (gestational timing) and D (morbidity/mortality) do not explain the ''unavoidable'' mechanism.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Effects of pregnancy on malaria are', 'A. Development of severe anaemia and severe jaundice', 'B. Blood smear is always positive and severe anaemia', 'C. Therapy limitation and few parasites in severe case', 'D. Loss of pregnancy and severe condition in few parasites', 'A', 'Per Kenya National Malaria Guidelines, malaria in pregnancy causes haemolysis leading to severe maternal anaemia with jaundice, alongside placental sequestration and low birth weight; severe anaemia (with jaundice) is the hallmark maternal effect (A). B is wrong because the peripheral smear is NOT always positive (placental sequestration can render it negative), and C/D contain internally contradictory or incorrect statements about parasite load and therapy.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Effects of preeclampsia on the reproductive systems includes', 'A. Development of infarcts and placental abruption', 'B. Lowered vaginal discharge PH and haemorrhage', 'C. Congestive cardiac failure and fetal hypoxia', 'D. Poor placental anchorage and severe infarction', 'A', 'Per Myles Textbook for Midwives, pre-eclampsia causes generalised vasospasm and reduced uteroplacental perfusion, producing placental infarcts and predisposing to placental abruption - the reproductive-system effects best captured by A. B (lowered vaginal pH) is not a pre-eclampsia effect, and C (CCF/fetal hypoxia) and D (poor placental anchorage) are less accurate or describe non-reproductive or aetiological features.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The correct statement with regards to polyhydramnios is that', 'A. Acute polyhydramnios has a gradual onset as from 20 weeks', 'B. Multiple pregnancy is a cause especially in dizygotic twinning', 'C. Chronic polyhydramnios has a gradual onset as from 30 weeks', 'D. On inspection, the abdomen is ovoid instead of being globular', 'B', 'Per Myles Textbook for Midwives, multiple pregnancy is a recognised cause of polyhydramnios (classically monozygotic twins via twin-to-twin transfusion, but multiple pregnancy generally increases risk), so B is the correct statement. A is false because ACUTE polyhydramnios has a SUDDEN onset (around 20 weeks), C is false because chronic type develops gradually usually from around 30 weeks but the onset is not the defining ''correct'' statement here, and D is false because the abdomen appears globular/rounded, not ovoid.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is a cause of oligohydramnios?', 'A. Absence of fetal urine production', 'B. Excessive fetal urine production', 'C. Blockage of the fetal gastro-intestinal tract', 'D. Dizygotic twinning thus twin to twin transfusion', 'A', 'Per Myles Textbook for Midwives, oligohydramnios results from reduced or absent fetal urine production (fetal urine is the main source of amniotic fluid in later pregnancy), as in renal agenesis (Potter syndrome) or urinary tract obstruction. Excessive urine production (B), GI tract blockage (C) and twin-to-twin transfusion (D) are associated with POLYhydramnios, not oligohydramnios.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('T.B. in pregnancy predisposes a mother to premature labour due to', 'A. Poor maternal appetite', 'B. Severe anaemia experienced', 'C. Adverse reactions of anti-T.B. drugs', 'D. The fever experienced', 'D', 'Per Kenya National TB guidelines and Myles, maternal pyrexia (fever) from active tuberculosis stimulates uterine activity and predisposes to premature labour, as pyrexia from any maternal infection is a recognised trigger of preterm labour. Poor appetite (A) and anaemia (B) act indirectly and are less specific, and standard anti-TB drugs (C) are used in pregnancy and are not the mechanism of preterm labour here.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Prenatally, malaria parasite hide at the', 'A. Bone marrow', 'B. Placental bed', 'C. Fetal circulation', 'D. Uterine muscle', 'B', 'Per Kenya National Malaria Guidelines, in pregnancy Plasmodium falciparum-infected erythrocytes sequester in the placenta (placental bed) via chondroitin sulphate A adhesion, so peripheral blood smears may be negative while parasites are concentrated in the placenta. Bone marrow (A), fetal circulation (C) and uterine muscle (D) are not the site of this characteristic placental sequestration.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Homeopathy, music therapy and hydrotherapy are among the;', 'A. Systemic methods of pain relief', 'B. Regional analgesia methods of pain relief', 'C. Inhalational analgesia method of pain relief', 'D. Non pharmacological method of pain relief', 'D', 'Per Myles Textbook for Midwives, homeopathy, music therapy and hydrotherapy are complementary, non-pharmacological methods of labour pain relief. They are not systemic (A, e.g. opioids), regional (B, e.g. epidural) or inhalational (C, e.g. Entonox) drug-based analgesia, so D is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During induction of labor with syntocinon, drops increase is stopped prematurely on', 'A. Achieving three moderate contractions', 'B. Realizing normal maternal observations', 'C. Achieving progressive cervical dilatation', 'D. Observing normal fetal related observations', 'A', 'Per Myles and Kenya MOH induction protocols, during oxytocin (syntocinon) induction the infusion rate is not increased further once effective uterine activity of about three to four moderate contractions in 10 minutes is achieved, to avoid uterine hyperstimulation. Normal maternal observations (B), progressive cervical dilatation (C) and normal fetal observations (D) are reassuring but are not the specific endpoint for stopping the dose increase.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The commonest major cause of primary postpartum haemorrhage is', 'A. Trauma of the genital tract', 'B. Blood coagulation disorder', 'C. Prolonged 3rd stage', 'D. Atony of the uterus', 'D', 'Per Myles and Kenya MOH/EmONC guidelines, uterine atony is the commonest cause of primary postpartum haemorrhage, accounting for roughly 70-80% of cases and being the first of the ''4 Ts'' (Tone). Genital tract trauma (A), coagulation disorders (B) and a prolonged/retained third stage (C) are recognised but less common causes.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Excessive bleeding from the genital tract after the first 24 hours , but within puerperium period is referred to as', 'A. Primary postpartum haemorrhage', 'B. Tertiary postpartum haemorrhage', 'C. Secondary postpartum haemorrhage', 'D. Incidental postpartum haemorrhage', 'C', 'Per Myles Textbook for Midwives, secondary postpartum haemorrhage is excessive genital tract bleeding occurring after the first 24 hours and up to 6 weeks (the puerperium), commonly due to retained products of conception or infection. Primary PPH (A) occurs within the first 24 hours, and ''tertiary'' (B) and ''incidental'' (D) PPH are not recognised classifications.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following drugs when used by a pregnant woman is likely to lead to oligohydramnios?', 'A. Diazepam', 'B. Captopril', 'C. Ampicillin', 'D. Pethidine', 'B', 'Per Myles and MOH guidance, ACE inhibitors such as captopril are contraindicated in pregnancy because fetal renal hypoperfusion reduces fetal urine output causing oligohydramnios (and fetal renal damage). Diazepam (A), ampicillin (C) and pethidine (D) do not cause oligohydramnios.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A characteristic of dizygotic twins include', 'A. Always of the same sex', 'B. Share a similar fingerprint pattern', 'C. Could have different blood groups', 'D. Superfetation is a common finding', 'C', 'Per Myles Textbook for Midwives, dizygotic (fraternal) twins arise from two separately fertilised ova, so they are genetically like ordinary siblings and can differ in sex, fingerprints and blood group - hence ''could have different blood groups'' (C) is correct. Always being the same sex (A) and sharing a fingerprint pattern (B) apply to monozygotic twins, and superfetation (D) is a rare, unrelated phenomenon.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The lie is defined as unstable when it keeps varying after', 'A. 36 weeks gestation', 'B. 42 weeks gestation', 'C. 38 weeks gestation', 'D. 40 weeks gestation', 'A', 'Per Myles Textbook for Midwives, the lie is termed unstable when it continues to vary between longitudinal, oblique and transverse after 36 weeks gestation, when the fetus would normally have settled into a stable lie. 38, 40 and 42 weeks (C/D/B) are later than the recognised 36-week threshold.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When a hand/ foot, lies alongside the presenting part, the presentation is said to be', 'A. Footling', 'B. Transverse', 'C. Compound', 'D. Cephalic', 'C', 'Per Myles Textbook for Midwives, when a hand or foot lies alongside the presenting part (usually the head), it is a compound presentation. Footling (A) is a breech variant with the foot as the sole presenting part, transverse (B) describes lie not presentation, and cephalic (D) simply denotes a head-presenting fetus.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A condition of trial of scar is', 'A. Estimated foetal weight of less than 3600g', 'B. Availability of a level one hospital nearby', 'C. Not more than two previous caesarean section scar', 'D. An adequate pelvis with true conjugate 10.5cm', 'D', 'Per Myles and MOH guidance, a trial of scar (VBAC) requires an adequate pelvis - a true conjugate of about 10.5 cm or more - so vaginal delivery is mechanically feasible (D). A level-one facility (B) is inappropriate for VBAC which needs facilities for emergency CS, and an estimated fetal weight cut-off alone (A) or the number of previous scars (C, and more than one prior CS generally contraindicates trial of scar) are not the defining condition described.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vaginal birth after caesarean section is known as', 'A. Spontaneous vaginal delivery', 'B. Trial of scar', 'C. Spontaneous vertex delivery', 'D. Trial of birth', 'B', 'Per Myles Textbook for Midwives, a planned attempt at vaginal birth after a previous caesarean section is termed a trial of scar (also VBAC/trial of labour after caesarean) (B). Spontaneous vaginal/vertex delivery (A/C) describe unassisted deliveries generally, and ''trial of birth'' (D) is not a standard obstetric term.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The fetal head retracting against the perineum is a', 'A. Gaskin sign', 'B. Turtle sign', 'C. Klumpke sign', 'D. Chignon sign', 'B', 'The turtle sign is the fetal head emerging then retracting tightly back against the perineum, the cardinal warning of shoulder dystocia from anterior-shoulder impaction behind the symphysis pubis (Myles Textbook for Midwives). Gaskin (all-fours) is a manoeuvre not a sign; Klumpke is a lower brachial plexus palsy; a chignon is the artificial vacuum-cup scalp swelling, none of which describe head retraction.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vasa praevia occurs when there is a', 'A. Velamentous insertion of the cord', 'B. Succenturiate insertion of the cord', 'C. Tripartite cord', 'D. Bipartite cord', 'A', 'Vasa praevia is caused by a velamentous cord insertion (or vessels crossing to a succenturiate lobe) so unprotected fetal vessels run through the membranes across the internal os (Myles Textbook for Midwives). A succenturiate insertion is not the standard term used, and tripartite/bipartite cord are not recognised entities, making A the only correct cause among the options.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cord presentation is when the', 'A. Umbilical cord lies in front of the presenting part after the membranes have ruptured.', 'B. Umbilical cord lies in front of the presenting part before membranes have ruptured.', 'C. Umbilical cord is tied around the foetal neck.', 'D. Umbilical cord has prematurely been detached.', 'B', 'Cord presentation is when the umbilical cord lies below/in front of the presenting part while the membranes are still intact; once the membranes rupture and the cord descends it becomes cord prolapse (Myles Textbook for Midwives). Option A describes prolapse (ruptured membranes), option C describes a nuchal cord, and D describes cord avulsion, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following is an obstetric emergency', 'Aftercoming head in breech', 'Complete cephalic presentation', 'Complete breech presentation', 'Complete rupture of the uterus', 'D', 'Complete rupture of the uterus is a life-threatening obstetric emergency causing haemorrhage, fetal expulsion into the peritoneum and shock, demanding immediate laparotomy (Myles Textbook for Midwives; Kenya MOH). Aftercoming head in breech is a managed complication of an already-recognised breech, while complete cephalic and complete breech presentations are simply lie/presentation descriptors, not emergencies in themselves, so D is the clear answer.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The correct statement about shoulder dystocia is', 'Its an impaction of the anterior shoulder after delivery of the head', 'Its an impaction of the posterior shoulder after delivery of the head', 'Shoulder dystocia occurs due to compound presentation of the fetus', 'Shoulder dystocia is not an emergency, it usually resolves on its own', 'A', 'Shoulder dystocia is the impaction of the anterior fetal shoulder behind the maternal symphysis pubis after the head has delivered; it is a true obstetric emergency requiring manoeuvres (Myles Textbook for Midwives). It is not posterior-shoulder impaction (B), is not caused by compound presentation (C), and never resolves spontaneously (D).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The diameter that presents in complete breech presentation is', 'Bitrochanteric 9.5 cm', 'Bitrochanteric 10 cm', 'Bisacral 9.5 cm', 'Bisacral 10cm', 'B', 'In a breech the engaging/presenting diameter of the buttocks is the bitrochanteric diameter, quoted in Myles Textbook for Midwives as 10 cm. The bisacral diameter is not the engaging diameter, so C and D are wrong; 9.5 cm (A) is the value some older texts cite but Myles gives 10 cm, so B is the best answer.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Postdatism is pregnancy equal to or more than', '280 days', '294 days', '290 days', '287 days', 'B', 'Post-term/postdatism is a pregnancy reaching or exceeding 42 completed weeks, i.e. 294 days from the last menstrual period (Myles Textbook for Midwives; WHO). 280 days is 40 weeks (term), 287 days is 41 weeks and 290 days is not a defined threshold, so 294 days (B) is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Prolonged second stage of labor in nulliporous women is labor for more than', '1 hour', '2 hours', '4 hours', '8 hours', 'B', 'Second stage is defined as prolonged in a nulliparous woman when it exceeds 2 hours (or 3 hours with regional analgesia) (Myles Textbook for Midwives; WHO labour care guidance). 1 hour is normal, while 4 and 8 hours are far beyond the diagnostic threshold, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Classical caesarean section is indicated for', 'An anteriorly situated placenta praevia', 'A posteriorly situated placenta praevia', 'A gestation of more than 32 weeks', 'Aesthetic purpose on maternal request', 'A', 'A classical (upper-segment) caesarean is indicated when the lower uterine segment is inaccessible or unsafe, as with an anteriorly situated placenta praevia overlying the lower segment where a low incision would cut through placenta and cause torrential bleeding (Myles Textbook for Midwives). A posterior praevia allows a lower-segment approach, gestation >32 weeks alone is not an indication, and maternal aesthetic request is never an indication.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An indication for forceps delivery is', 'Inadequate size of the pelvis', 'Delay in second stage of labor', 'Unsuccessful vacuum extraction', 'Fetal distress in first stage of labor', 'B', 'Forceps delivery is indicated for delay in the second stage of labour with a fully dilated cervix and engaged head (Myles Textbook for Midwives). An inadequate/contracted pelvis contraindicates forceps, first-stage fetal distress requires caesarean (the cervix is not fully dilated), and unsuccessful vacuum is a relative contraindication because sequential instruments increase fetal trauma; thus B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Signs of obstructed labour per vaginally include', 'Dry vagina, Oedema of the cervix, Caput succedaneum', 'Plenty amniotic fluid, Hot/ dry vagina, meconium stained liquor', 'Meconium stained liquor, Hot/dry vagina, Diluted urine', 'Caput succedaneum, Oedema of the cervix, plenty amniotic fluid', 'A', 'On vaginal examination obstructed labour shows a hot dry vagina, an oedematous cervix and a large caput succedaneum with moulding (Myles Textbook for Midwives; Kenya MOH). Plenty of amniotic fluid is NOT a feature (the liquor drains and the vagina becomes dry), so options B and D are wrong, and C mixes in diluted urine which is not a marker of obstruction; only A lists three genuine signs.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In True cephalopelvic disproportion', 'Half of the patient will need an operative delivery', 'The problem may be overcome during labour', 'Operative delivery is unnecessary', 'Operative delivery will be needed', 'D', 'In true (absolute) cephalopelvic disproportion vaginal delivery is impossible and operative (caesarean) delivery is required (Myles Textbook for Midwives). It cannot be overcome during labour (B) as that describes relative/borderline CPD, operative delivery is not unnecessary (C), and ''half will need operative delivery'' (A) describes borderline not true CPD.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A correct statement about shoulder dystocia is:-', 'It is an impaction of the anterior shoulder after delivery of the head', 'It is an impaction of the posterior shoulder after delivery of the head', 'Shoulder dystocia occurs due to compound presentation of the foetus', 'Shoulder is not an emergency and resolves on its own effort gradually', 'A', 'Shoulder dystocia is impaction of the anterior shoulder behind the symphysis pubis after delivery of the head, a true emergency requiring manoeuvres such as McRoberts and suprapubic pressure (Myles Textbook for Midwives). It is not posterior-shoulder impaction (B), is not due to compound presentation (C), and does not resolve on its own (D).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Predisposing factors to uterine rupture include', 'Nulliparity, neglected obstructed labor', 'Breech presentation, multiple pregnancy', 'Neglected obstructed labour, high parity', 'Obstetric maneuvers, breech presentation', 'C', 'Uterine rupture is predisposed by neglected obstructed labour and high (grand) parity, along with a previous uterine scar and injudicious oxytocin (Myles Textbook for Midwives; Kenya MOH). Nulliparity (A) is protective rather than a risk factor, and breech/multiple pregnancy and obstetric manoeuvres in the other options are not the classic predisposing pair, so C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pubiotomy is', 'Access to the lower uterine segment by dissection tissues around the peritoneum', 'A surgical procedure in which the cartilage of the pubic symphysis is divided', 'Ligating of the pubic bones in case they are invaded by cancerous cells', 'Dissection of the perineal tissues to hasten the perineal phase of labor', 'B', 'Pubiotomy/symphysiotomy is a surgical procedure in which the cartilage of the pubic symphysis is divided to enlarge the pelvic outlet and permit vaginal delivery (Myles Textbook for Midwives). It is not peritoneal dissection to reach the lower segment (A, that describes an extraperitoneal caesarean approach), not ligation for cancer (C), and not perineal dissection (D, which describes episiotomy).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An early sign of a ruptured uterus includes', 'Maternal dehydration', 'Maternal pyrexia >38°C', 'Maternal oliguria', 'Failure of cervix to dilate', 'D', 'The earliest sign of impending (incipient) uterine rupture is obstruction shown by failure of the cervix to dilate despite strong contractions, with a rising retraction (Bandl''s) ring (Myles Textbook for Midwives). Dehydration, pyrexia and oliguria are later, non-specific features of prolonged/obstructed labour and shock, so D is the early sign.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The MOST immediate action to take for a client in active labour at 32 weeks with a cord prolapse is to', 'Push the cord back into the uterus with a gloved hand', 'Cover cord with sterile dry gauze', 'Place the client in knee-chest position', 'Prepare the client for immediate vaginal delivery', 'C', 'In cord prolapse the immediate action is to relieve cord compression by positioning the mother in the knee-chest (or exaggerated Trendelenburg) position and elevating the presenting part while arranging urgent caesarean (Myles Textbook for Midwives; Kenya MOH). The cord is never pushed back (A, causes vasospasm), it should be kept warm and moist rather than dry (B), and at 32 weeks with a viable fetus immediate vaginal delivery (D) is not the safe route, so C is the most immediate correct action.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following signs is indicative of possible shoulder dystocia during delivery?', 'Failure of internal rotation of the head', 'Fetal head retracts against the perineum', 'Gentle traction aids in effecting the delivery', 'The occiput slowly restitutes towards the left side', 'B', 'The turtle sign, in which the fetal head retracts tightly back against the perineum after delivering, is the classic indicator of shoulder dystocia (Myles Textbook for Midwives). Failure of internal rotation (A) is not the recognised sign, gentle traction succeeding (C) indicates no dystocia, and normal restitution (D) is a physiological finding, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The maneuver used in management of shoulder dystocia whereby midwife first identifies the posterior shoulder then tries to rotate it in the direction of the fetal chest is', 'Wood''s maneuver', 'Rubin''s maneuver', 'Zavanelli maneuver', 'Reverse wood''s maneuver', 'B', 'The Rubin manoeuvre involves reaching the most accessible shoulder and pushing it toward the fetal chest to adduct/reduce the shoulder diameter and relieve dystocia (Myles Textbook for Midwives). Wood''s screw rotates the posterior shoulder anteriorly (toward the back), the reverse Wood''s rotates the other way, and the Zavanelli manoeuvre replaces the head for caesarean; the description of rotating toward the chest matches Rubin, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Prior to application of traction in forceps delivery, it''s MOST important to note', 'When the contraction ends', 'When the client feels the contraction', 'When the contraction begins', 'When the fetal heart rate drops', 'C', 'Forceps traction is applied in concert with maternal expulsive effort during a contraction, so it is most important to note when the contraction begins so that traction coincides with it (Myles Textbook for Midwives). Noting when it ends (A) or when the mother feels it (B) is too late or subjective, and fetal heart-rate drop (D) is monitored but is not the trigger for timing traction, so C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The PRIORITY health message to share with a client in the recovery room immediately following caesarean section includes', 'Frequent coughing & deep breathing', 'Importance of perineal self-care', 'Importance of early ambulation', 'Signs of puerperal infections', 'A', 'Immediately in the recovery room after caesarean under general or spinal anaesthesia the priority teaching is respiratory - deep breathing and coughing to prevent atelectasis and hypostatic pneumonia (Brunner & Suddarth, post-operative nursing). Early ambulation (C), perineal self-care (B, largely irrelevant after CS) and later signs of puerperal infection (D) are important but are not the immediate recovery-room priority, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The engaging diameter in a face presentation is', 'Sub-mento vertical diameter', 'Sub-mento bregmatic diameter', 'Mento vertical diameter', 'Sub-occipito bregmatic diameter', 'A', 'In a face (fully extended) presentation the engaging diameter is the submentovertical (11.5 cm), while the submentobregmatic (9.5 cm) is the diameter that ultimately distends the vulva as the chin escapes (Myles Textbook for Midwives). The mentovertical (13.5 cm) is the brow diameter and the suboccipitobregmatic is the well-flexed vertex diameter, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vaginal delivery is possible in', 'Brow presentation', 'Face presentation', 'Shoulder presentation', 'Unstable lie', 'B', 'Vaginal delivery is possible in a mento-anterior face presentation because the chin can pass under the symphysis and the head delivers by flexion (Myles Textbook for Midwives). Brow presentation (mentovertical 13.5 cm) obstructs labour, shoulder (transverse) presentation cannot deliver vaginally, and an unstable lie is not itself deliverable, so B is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The MOST common type of breech presentation is', 'Frank breech presentation', 'Complete breech presentation', 'Incomplete breech presentation', 'Footling breech presentation', 'A', 'Frank (extended) breech - hips flexed and knees extended so the legs are splinted up against the trunk - is the commonest type of breech, particularly in primigravidae (Myles Textbook for Midwives). Complete, incomplete and footling breeches are all less common, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A maternal associated risk of prolonged pregnancy includes:-', 'Labour dystocia', 'Placental insufficiency', 'Fetal post-maturity syndrome', 'Large for gestational age baby', 'A', 'Among these options the maternal risk of prolonged pregnancy is labour dystocia (from a larger, less-mouldable baby) leading to obstructed labour and operative delivery (Myles Textbook for Midwives). Placental insufficiency (B), fetal post-maturity syndrome (C) and a large-for-gestational-age baby (D) are all fetal rather than maternal risks, so A is the correct maternal-associated answer.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following positions is SAFEST for a woman in labour with a cord prolapse?', 'Lithotomy', 'Trendelenburg', 'Fowler''s', 'Prone', 'B', 'The Trendelenburg (head-down) position uses gravity to shift the presenting part off the umbilical cord, relieving compression in cord prolapse; knee-chest is the equivalent alternative (Myles Textbook for Midwives; Kenya MOH). Lithotomy and Fowler''s do not relieve cord pressure and prone is unsafe/impractical, so B is the safest position.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Complete uterine rupture involves', 'A. A tear of endometrium, myometrium & peritoneum', 'B. A tear of the endometrium, myometrium & basal layer', 'C. A tear of the endometrium, capsular layer & myometrium', 'D. A tear of the endometrium, spongy layer & myometrium only', 'A', 'Complete uterine rupture is a full-thickness tear of the uterine wall - endometrium, myometrium and perimetrium (peritoneum) - allowing uterine contents to escape into the peritoneal cavity; incomplete rupture leaves the peritoneum intact (Myles Textbook for Midwives). The ''basal'', ''capsular'' and ''spongy'' layers in options B, C and D are decidual, not uterine-wall, layers, so A is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A mother with a cord prolapse is given oxygen at a rate of 4 litres/minute in order to', 'A. Relieve maternal distress', 'B. Promote her relative rest', 'C. Improve the fetal oxygenation', 'D. Achieve the effect of tocolysis', 'C', 'Giving the mother oxygen in cord prolapse maximises the maternal-to-fetal oxygen gradient and so improves fetal oxygenation while delivery is arranged (Myles Textbook for Midwives; Kenya MOH). It is not primarily to relieve maternal distress (A) or promote rest (B), and oxygen has no tocolytic effect (D), so C is correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
